INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_L05_challenge#3','kor',5,1,'u4','L05','g5_1_kor_u4_L05_challenge','lesson_challenge','K5-1-u4-C24',3,'mc','auto','단계가 있는 것도, 두 대상을 견주는 것도 아니고 방법을 세 가지로 나누어 하나씩 설명했다면 어떤 구조인가요?',ARRAY['K5-1-u4-X08','K5-1-u4-X10','K5-1-u4-X14']::text[],false,'{"seq":3,"concept":"K5-1-u4-C24","difficulty":3,"kind":"mc","stem":"단계가 있는 것도, 두 대상을 견주는 것도 아니고 방법을 세 가지로 나누어 하나씩 설명했다면 어떤 구조인가요?","options":[{"t":"열거 구조","correct":true},{"t":"순서 구조","mis":"K5-1-u4-X08"},{"t":"비교와 대조 구조","mis":"K5-1-u4-X10"},{"t":"구조를 알 수 없다","mis":"K5-1-u4-X14"}],"explanation":["단계가 없어요.","견주지 않았어요.","항목별로 나열한 열거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_L05_challenge#4','kor',5,1,'u4','L05','g5_1_kor_u4_L05_challenge','lesson_challenge','K5-1-u4-C26',3,'error','auto','하천 글을 요약하려는 친구들의 말이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-1-u4-X26','K5-1-u4-X25']::text[],false,'{"seq":4,"concept":"K5-1-u4-C26","difficulty":3,"kind":"error","stem":"하천 글을 요약하려는 친구들의 말이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「글에 나온 중요한 낱말만 쭉 늘어놓으면 요약이 돼.」","correct":true,"mis_target":"K5-1-u4-X26"},{"t":"「문단마다 중심 문장을 찾아 이어 보자.」","mis":"K5-1-u4-X26"},{"t":"「처음 · 가운데 · 끝으로 나누어 정리하자.」","mis":"K5-1-u4-X25"}],"explanation":["알맞은 말이에요.","알맞은 말이에요.","낱말 나열은 요약이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_L05_challenge#5','kor',5,1,'u4','L05','g5_1_kor_u4_L05_challenge','lesson_challenge','K5-1-u4-C25',3,'mc','auto','이 글의 처음 부분(㉮)이 하는 일로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u4-X25','K5-1-u4-X10']::text[],false,'{"seq":5,"concept":"K5-1-u4-C25","difficulty":3,"kind":"mc","stem":"이 글의 처음 부분(㉮)이 하는 일로 알맞은 것은 어느 것인가요?","options":[{"t":"하천이 어떤 곳인지 밝히고 왜 지켜야 하는지 열어 준다","correct":true},{"t":"세 가지 방법을 자세히 설명한다","mis":"K5-1-u4-X25"},{"t":"실천을 권하며 글을 맺는다","mis":"K5-1-u4-X25"},{"t":"하천과 바다를 견준다","mis":"K5-1-u4-X10"}],"explanation":["그것은 가운데예요.","그것은 끝이에요.","처음은 대상을 밝히고 글을 열어요."],"asset":{"type":"passage","lines":["㉮ 마을 하천은 여러 생물이 사는 곳이자 사람들이 쉬어 가는 곳이다.","　 그러나 조금만 소홀히 하면 물이 쉽게 오염된다.","㉯ 첫째, 하천에 쓰레기를 버리지 않는다. 무단으로 버린 비닐은 오래 남는다.","㉰ 둘째, 생활 하수를 줄인다. 설거지 전에 기름기를 먼저 닦아 낸다.","㉱ 셋째, 하천가의 풀과 나무를 함부로 뽑지 않는다. 풀뿌리는 흙을","　 붙잡고, 물을 정화하며, 작은 생물의 서식 공간이 된다.","㉲ 이처럼 하천을 지키는 일은 생활 속의 작은 습관에서 시작된다."],"title":"「우리 마을 하천을 지키는 방법」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_L05_challenge#6','kor',5,1,'u4','L05','g5_1_kor_u4_L05_challenge','lesson_challenge','K5-1-u4-C22',3,'mc','auto','하천 글을 처음 받아 든 친구가 요약하려고 가장 먼저 할 일은 무엇인가요?',ARRAY['K5-1-u4-X22','K5-1-u4-X06']::text[],false,'{"seq":6,"concept":"K5-1-u4-C22","difficulty":3,"kind":"mc","stem":"하천 글을 처음 받아 든 친구가 요약하려고 가장 먼저 할 일은 무엇인가요?","options":[{"t":"구조를 드러내는 말을 찾아 글의 구조를 살핀다","correct":true},{"t":"요약문부터 쓴다","mis":"K5-1-u4-X22"},{"t":"낱말을 모두 외운다","mis":"K5-1-u4-X22"},{"t":"끝 부분만 읽는다","mis":"K5-1-u4-X06"}],"explanation":["읽고 정리한 뒤에 써요.","외우기가 목적이 아니에요.","구조 찾기가 첫걸음이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_L05_challenge#7','kor',5,1,'u4','L05','g5_1_kor_u4_L05_challenge','lesson_challenge','K5-1-u4-C27',3,'mc','auto','과학 교과서에서 두 생물을 견주어 설명한 부분을 요약하는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u4-X27','K5-1-u4-X13','K5-1-u4-X21']::text[],false,'{"seq":7,"concept":"K5-1-u4-C27","difficulty":3,"kind":"mc","stem":"과학 교과서에서 두 생물을 견주어 설명한 부분을 요약하는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"비교와 대조 구조로 같은 점과 다른 점을 정리한다","correct":true},{"t":"과학 글은 요약할 수 없다","mis":"K5-1-u4-X27"},{"t":"열거 구조로만 정리한다","mis":"K5-1-u4-X13"},{"t":"처음부터 끝까지 옮겨 쓴다","mis":"K5-1-u4-X21"}],"explanation":["과학 글도 요약할 수 있어요.","견주는 글이에요.","구조에 맞게 정리해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_L05_challenge#8','kor',5,1,'u4','L05','g5_1_kor_u4_L05_challenge','lesson_challenge','K5-1-u4-C26',4,'essay','teacher','「우리 마을 하천을 지키는 방법」을 처음 한 문장, 가운데 한두 문장, 끝 한 문장으로 요약하세요.','{}'::text[],false,'{"seq":8,"concept":"K5-1-u4-C26","difficulty":4,"kind":"essay","stem":"「우리 마을 하천을 지키는 방법」을 처음 한 문장, 가운데 한두 문장, 끝 한 문장으로 요약하세요.","answer_guide":{"answer":"예: 마을 하천은 생물이 살고 사람이 쉬는 곳이지만 쉽게 오염된다. 하천을 지키려면 쓰레기를 버리지 않고, 생활 하수를 줄이며, 하천가의 풀과 나무를 함부로 뽑지 않아야 한다. 하천을 지키는 일은 생활 속의 작은 습관에서 시작된다.","scoring_points":["처음 · 가운데 · 끝을 갖추었는가","세 방법을 빠짐없이 담았는가","뒷받침 내용은 줄였는가"]},"explanation":["처음은 무엇을 밝혔나요?","가운데는 세 방법이에요.","끝은 무엇을 권했나요?"],"asset":{"type":"passage","lines":["㉮ 마을 하천은 여러 생물이 사는 곳이자 사람들이 쉬어 가는 곳이다.","　 그러나 조금만 소홀히 하면 물이 쉽게 오염된다.","㉯ 첫째, 하천에 쓰레기를 버리지 않는다. 무단으로 버린 비닐은 오래 남는다.","㉰ 둘째, 생활 하수를 줄인다. 설거지 전에 기름기를 먼저 닦아 낸다.","㉱ 셋째, 하천가의 풀과 나무를 함부로 뽑지 않는다. 풀뿌리는 흙을","　 붙잡고, 물을 정화하며, 작은 생물의 서식 공간이 된다.","㉲ 이처럼 하천을 지키는 일은 생활 속의 작은 습관에서 시작된다."],"title":"「우리 마을 하천을 지키는 방법」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_L05_challenge#9','kor',5,1,'u4','L05','g5_1_kor_u4_L05_challenge','lesson_challenge','K5-1-u4-C26',4,'essay','teacher','「하천은 중요하다. 쓰레기가 있다. 설거지 이야기도 나온다.」라는 요약이 왜 아쉬운지 쓰고, 좋은 요약문은 무엇을 이어 만드는지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K5-1-u4-C26","difficulty":4,"kind":"essay","stem":"「하천은 중요하다. 쓰레기가 있다. 설거지 이야기도 나온다.」라는 요약이 왜 아쉬운지 쓰고, 좋은 요약문은 무엇을 이어 만드는지 쓰세요.","answer_guide":{"answer":"예: 글에 나온 낱말을 늘어놓기만 해서 하천을 지키는 방법이 무엇인지 알 수 없다. 좋은 요약문은 문단마다 중심 문장을 찾아 이어 만들기 때문에 「쓰레기를 버리지 않고, 생활 하수를 줄이며, 풀과 나무를 지킨다」처럼 중심 내용이 드러난다.","scoring_points":["아쉬운 까닭을 썼는가","좋은 요약문은 중심 문장을 잇는다고 썼는가","예를 들었는가"]},"explanation":["무엇이 빠졌나요?","중심 문장을 떠올려요.","고친 예를 들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_L05_challenge#10','kor',5,1,'u4','L05','g5_1_kor_u4_L05_challenge','lesson_challenge','K5-1-u4-C25',4,'essay','teacher','하천 글의 처음 · 가운데 · 끝에 각각 어떤 내용이 있는지 쓰고, 요약하기 전에 구조를 먼저 찾으면 왜 도움이 되는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K5-1-u4-C25","difficulty":4,"kind":"essay","stem":"하천 글의 처음 · 가운데 · 끝에 각각 어떤 내용이 있는지 쓰고, 요약하기 전에 구조를 먼저 찾으면 왜 도움이 되는지 쓰세요.","answer_guide":{"answer":"예: 처음은 하천이 어떤 곳인지 밝히고 지키는 방법을 알아보자고 연다. 가운데는 쓰레기 버리지 않기, 생활 하수 줄이기, 풀과 나무 지키기를 첫째 · 둘째 · 셋째로 설명한다. 끝은 작은 습관에서 시작된다며 실천을 권한다. 구조를 먼저 찾으면 가운데의 세 방법이 중심 내용이라는 것이 드러나 쉽게 간추릴 수 있다.","scoring_points":["처음 · 가운데 · 끝의 내용을 썼는가","구조를 먼저 찾는 까닭을 썼는가","중심 내용이 드러난다는 점을 썼는가"]},"explanation":["세 부분을 나누어요.","첫째 · 둘째 · 셋째를 봐요.","구조가 길잡이예요."],"asset":{"type":"passage","lines":["㉮ 마을 하천은 여러 생물이 사는 곳이자 사람들이 쉬어 가는 곳이다.","　 그러나 조금만 소홀히 하면 물이 쉽게 오염된다.","㉯ 첫째, 하천에 쓰레기를 버리지 않는다. 무단으로 버린 비닐은 오래 남는다.","㉰ 둘째, 생활 하수를 줄인다. 설거지 전에 기름기를 먼저 닦아 낸다.","㉱ 셋째, 하천가의 풀과 나무를 함부로 뽑지 않는다. 풀뿌리는 흙을","　 붙잡고, 물을 정화하며, 작은 생물의 서식 공간이 된다.","㉲ 이처럼 하천을 지키는 일은 생활 속의 작은 습관에서 시작된다."],"title":"「우리 마을 하천을 지키는 방법」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_L07_basic#1','kor',5,1,'u4','L07','g5_1_kor_u4_L07_basic','lesson_basic','K5-1-u4-C28',1,'mc','auto','설명하는 글을 쓸 때의 마음가짐으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u4-X28','K5-1-u4-X33','K5-1-u4-X30']::text[],false,'{"seq":1,"concept":"K5-1-u4-C28","difficulty":1,"kind":"mc","stem":"설명하는 글을 쓸 때의 마음가짐으로 알맞은 것은 어느 것인가요?","options":[{"t":"읽을 사람에게 필요한 것을 골라 쓴다","correct":true},{"t":"아는 것을 모두 쓴다","mis":"K5-1-u4-X28"},{"t":"떠오르는 차례대로 쓴다","mis":"K5-1-u4-X33"},{"t":"글자 수를 많이 채운다","mis":"K5-1-u4-X30"}],"explanation":["다 쓰는 글이 아니에요.","차례도 생각해야 해요.","필요한 것을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_L07_basic#2','kor',5,1,'u4','L07','g5_1_kor_u4_L07_basic','lesson_basic','K5-1-u4-C29',1,'mc','auto','쓸 내용을 정할 때 가장 먼저 정하는 것은 어느 것인가요?',ARRAY['K5-1-u4-X29']::text[],false,'{"seq":2,"concept":"K5-1-u4-C29","difficulty":1,"kind":"mc","stem":"쓸 내용을 정할 때 가장 먼저 정하는 것은 어느 것인가요?","options":[{"t":"글을 쓰는 목적","correct":true},{"t":"글의 구조","mis":"K5-1-u4-X29"},{"t":"글 제목의 글씨 색","mis":"K5-1-u4-X29"},{"t":"친구에게 남길 댓글","mis":"K5-1-u4-X29"}],"explanation":["구조는 맨 나중에 정해요.","먼저 정할 것이 아니에요.","목적부터 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_L07_basic#3','kor',5,1,'u4','L07','g5_1_kor_u4_L07_basic','lesson_basic','K5-1-u4-C30',1,'mc','auto','설명할 대상을 고를 때 생각할 것이 아닌 것은 어느 것인가요?',ARRAY['K5-1-u4-X30']::text[],false,'{"seq":3,"concept":"K5-1-u4-C30","difficulty":1,"kind":"mc","stem":"설명할 대상을 고를 때 생각할 것이 아닌 것은 어느 것인가요?","options":[{"t":"내가 좋아하는 색과 어울리는가","correct":true},{"t":"내가 잘 아는 대상인가","mis":"K5-1-u4-X30"},{"t":"읽을 사람이 흥미로워할 대상인가","mis":"K5-1-u4-X30"},{"t":"믿을 수 있는 자료를 구할 수 있는가","mis":"K5-1-u4-X30"}],"explanation":["생각할 것이에요.","생각할 것이에요.","색은 기준이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_L07_basic#4','kor',5,1,'u4','L07','g5_1_kor_u4_L07_basic','lesson_basic','K5-1-u4-C32',1,'mc','auto','「우리의 자랑, 줄타기」의 ㉰에서 쓰인 설명 방법은 어느 것인가요?',ARRAY['K5-1-u4-X09','K5-1-u4-X32','K5-1-u4-X38']::text[],false,'{"seq":4,"concept":"K5-1-u4-C32","difficulty":1,"kind":"mc","stem":"「우리의 자랑, 줄타기」의 ㉰에서 쓰인 설명 방법은 어느 것인가요?","options":[{"t":"비교와 대조 — 다른 나라 줄 공연과 견주었다","correct":true},{"t":"순서 — 공연의 차례를 밝혔다","mis":"K5-1-u4-X09"},{"t":"열거 — 줄광대 한 사람만 소개했다","mis":"K5-1-u4-X32"},{"t":"설명하지 않고 느낌만 적었다","mis":"K5-1-u4-X38"}],"explanation":["차례를 밝히지 않았어요.","「반면」으로 견주었어요.","다른 나라 줄 공연과 견주었어요."],"asset":{"type":"passage","lines":["㉮ 줄타기는 우리나라의 국가 무형유산이자 인류 무형문화유산이다.","㉯ 줄타기는 높이 맨 굵은 줄 위에서 재주를 부리는 공연이다. 줄 위의","　 사람을 줄광대, 땅에서 말을 주고받는 사람을 어릿광대라 한다.","㉰ 다른 나라의 줄 공연은 대개 재주를 보여 주는 데 집중한다. 반면 우리","　 줄타기의 줄광대는 노래하고 어릿광대와 우스갯소리를 주고받는다.","㉱ 한때 이어 갈 사람이 줄어 사라질 뻔했으나 오늘날까지 전해진다."],"title":"신문 글 「우리의 자랑, 줄타기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_L07_basic#5','kor',5,1,'u4','L07','g5_1_kor_u4_L07_basic','lesson_basic','K5-1-u4-C29',2,'match','auto','선정 단계와 글쓴이의 생각을 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K5-1-u4-C29","difficulty":2,"kind":"match","stem":"선정 단계와 글쓴이의 생각을 이으세요.","pairs":[{"l":"목적 정하기","r":"우리 전통 예술을 알리고 싶다"},{"l":"읽을 사람 정하기","r":"같은 학교 학생들이 읽을 것이다"},{"l":"대상 고르기","r":"직접 본 적이 있어 자세히 쓸 수 있겠다"},{"l":"구조 정하기","r":"여러 면을 소개하니 열거가 맞겠다"}],"mis":"K5-1-u4-X29","explanation":["왜 쓰나요?","누가 읽나요?","무엇을 어떤 틀로 쓰나요?"],"asset":{"type":"passage","lines":["목적 — 우리 전통 예술을 학교 친구들에게 알리기","읽을 사람 — 우리 학교 학생들","대상 — 줄타기(직접 공연을 본 적이 있음)","구조 — 여러 면을 소개하므로 열거 구조"],"title":"줄타기 글을 쓴 사람의 선정 과정"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_L07_basic#6','kor',5,1,'u4','L07','g5_1_kor_u4_L07_basic','lesson_basic','K5-1-u4-C31',2,'mc','auto','다른 나라 친구에게 줄타기를 설명한다면 무엇을 더하면 좋을까요?',ARRAY['K5-1-u4-X31']::text[],false,'{"seq":6,"concept":"K5-1-u4-C31","difficulty":2,"kind":"mc","stem":"다른 나라 친구에게 줄타기를 설명한다면 무엇을 더하면 좋을까요?","options":[{"t":"줄광대 · 어릿광대 같은 말의 뜻을 풀어 설명한다","correct":true},{"t":"더 어려운 말을 많이 쓴다","mis":"K5-1-u4-X31"},{"t":"설명을 모두 줄인다","mis":"K5-1-u4-X31"},{"t":"우리끼리 아는 말은 그대로 둔다","mis":"K5-1-u4-X31"}],"explanation":["더 어렵게 쓰면 안 돼요.","줄이면 이해하기 어려워요.","우리에게 익숙한 것도 낯설 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_L07_basic#7','kor',5,1,'u4','L07','g5_1_kor_u4_L07_basic','lesson_basic','K5-1-u4-C31',2,'mc','auto','저학년 동생들이 읽을 글을 쓴다면 어떻게 하면 좋을까요?',ARRAY['K5-1-u4-X31']::text[],false,'{"seq":7,"concept":"K5-1-u4-C31","difficulty":2,"kind":"mc","stem":"저학년 동생들이 읽을 글을 쓴다면 어떻게 하면 좋을까요?","options":[{"t":"어려운 말을 줄이고 그림을 함께 넣는다","correct":true},{"t":"어른이 읽는 글과 똑같이 쓴다","mis":"K5-1-u4-X31"},{"t":"어려운 낱말을 더 많이 넣는다","mis":"K5-1-u4-X31"},{"t":"그림은 빼고 글만 길게 쓴다","mis":"K5-1-u4-X31"}],"explanation":["읽을 사람을 생각해요.","쉽게 써야 해요.","그림이 도움이 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_L07_basic#8','kor',5,1,'u4','L07','g5_1_kor_u4_L07_basic','lesson_basic','K5-1-u4-C13',2,'mc','auto','줄타기 공연이 진행되는 차례를 소개하는 글이라면 알맞은 구조는 어느 것인가요?',ARRAY['K5-1-u4-X13']::text[],false,'{"seq":8,"concept":"K5-1-u4-C13","difficulty":2,"kind":"mc","stem":"줄타기 공연이 진행되는 차례를 소개하는 글이라면 알맞은 구조는 어느 것인가요?","options":[{"t":"순서 구조","correct":true},{"t":"열거 구조","mis":"K5-1-u4-X13"},{"t":"비교와 대조 구조","mis":"K5-1-u4-X13"},{"t":"줄타기는 열거 구조로만 쓸 수 있다","mis":"K5-1-u4-X13"}],"explanation":["차례를 밝혀요.","견주는 것이 아니에요.","같은 대상도 말하려는 것에 따라 구조가 달라져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_L07_basic#9','kor',5,1,'u4','L07','g5_1_kor_u4_L07_basic','lesson_basic','K5-1-u4-C33',2,'ox','auto','쓸 내용은 떠오른 차례대로 늘어놓으면 돼요.',ARRAY['K5-1-u4-X33']::text[],false,'{"seq":9,"concept":"K5-1-u4-C33","difficulty":2,"kind":"ox","stem":"쓸 내용은 떠오른 차례대로 늘어놓으면 돼요.","answer":"X","reason_options":[{"t":"읽는 사람의 흥미를 끌고 짜임새 있게 되도록 무엇을 먼저 놓을지 생각해 배열해야 하기 때문에","correct":true},{"t":"떠오른 차례가 가장 자연스러운 차례이기 때문에","mis":"K5-1-u4-X33"}],"mis":"K5-1-u4-X33","explanation":["떠오른 차례는 흩어지기 쉬워요.","읽는 사람을 생각해요.","배열도 쓰기의 일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_L07_basic#10','kor',5,1,'u4','L07','g5_1_kor_u4_L07_basic','lesson_basic','K5-1-u4-C30',3,'mc','auto','글쓴이가 줄타기를 대상으로 고른 까닭과 이어지는 기준은 어느 것인가요?',ARRAY['K5-1-u4-X30']::text[],false,'{"seq":10,"concept":"K5-1-u4-C30","difficulty":3,"kind":"mc","stem":"글쓴이가 줄타기를 대상으로 고른 까닭과 이어지는 기준은 어느 것인가요?","options":[{"t":"잘 아는 것 — 직접 공연을 본 적이 있다","correct":true},{"t":"글자 수를 많이 채울 수 있다","mis":"K5-1-u4-X30"},{"t":"좋아하는 색과 어울린다","mis":"K5-1-u4-X30"},{"t":"아무도 몰라서 자료가 없다","mis":"K5-1-u4-X30"}],"explanation":["글자 수는 기준이 아니에요.","색은 기준이 아니에요.","직접 보았으니 자세히 쓸 수 있어요."],"asset":{"type":"passage","lines":["목적 — 우리 전통 예술을 학교 친구들에게 알리기","읽을 사람 — 우리 학교 학생들","대상 — 줄타기(직접 공연을 본 적이 있음)","구조 — 여러 면을 소개하므로 열거 구조"],"title":"줄타기 글을 쓴 사람의 선정 과정"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_L07_challenge#1','kor',5,1,'u4','L07','g5_1_kor_u4_L07_challenge','lesson_challenge','K5-1-u4-C32',2,'mc','auto','「우리의 자랑, 줄타기」의 구조를 가장 바르게 말한 것은 어느 것인가요?',ARRAY['K5-1-u4-X09','K5-1-u4-X32']::text[],false,'{"seq":1,"concept":"K5-1-u4-C32","difficulty":2,"kind":"mc","stem":"「우리의 자랑, 줄타기」의 구조를 가장 바르게 말한 것은 어느 것인가요?","options":[{"t":"글 전체는 열거 구조이고 ㉰ 안에는 비교와 대조가 함께 쓰였다","correct":true},{"t":"글 전체가 순서 구조이다","mis":"K5-1-u4-X09"},{"t":"한 글에는 구조가 하나만 쓰이므로 ㉰도 열거일 뿐이다","mis":"K5-1-u4-X32"},{"t":"글 전체가 비교와 대조 구조이다","mis":"K5-1-u4-X32"}],"explanation":["단계가 아니라 항목이에요.","한 항목 안에서 견주었어요.","큰 틀 안에 작은 틀이 있어요."],"asset":{"type":"passage","lines":["㉮ 줄타기는 우리나라의 국가 무형유산이자 인류 무형문화유산이다.","㉯ 줄타기는 높이 맨 굵은 줄 위에서 재주를 부리는 공연이다. 줄 위의","　 사람을 줄광대, 땅에서 말을 주고받는 사람을 어릿광대라 한다.","㉰ 다른 나라의 줄 공연은 대개 재주를 보여 주는 데 집중한다. 반면 우리","　 줄타기의 줄광대는 노래하고 어릿광대와 우스갯소리를 주고받는다.","㉱ 한때 이어 갈 사람이 줄어 사라질 뻔했으나 오늘날까지 전해진다."],"title":"신문 글 「우리의 자랑, 줄타기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_L07_challenge#2','kor',5,1,'u4','L07','g5_1_kor_u4_L07_challenge','lesson_challenge','K5-1-u4-C28',2,'mc','auto','「설명하는 글은 아는 것을 다 쓰는 글이 아니다」라는 말의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u4-X28']::text[],false,'{"seq":2,"concept":"K5-1-u4-C28","difficulty":2,"kind":"mc","stem":"「설명하는 글은 아는 것을 다 쓰는 글이 아니다」라는 말의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"읽을 사람에게 필요한 것을 골라 써야 한다","correct":true},{"t":"아는 것은 하나도 쓰지 않는다","mis":"K5-1-u4-X28"},{"t":"모르는 것만 골라 쓴다","mis":"K5-1-u4-X28"},{"t":"짧을수록 무조건 좋은 글이다","mis":"K5-1-u4-X28"}],"explanation":["아는 것을 바탕으로 써요.","잘 아는 것을 써요.","필요한 것을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_L07_challenge#3','kor',5,1,'u4','L07','g5_1_kor_u4_L07_challenge','lesson_challenge','K5-1-u4-C33',3,'mc','auto','다른 나라 친구들을 위한 줄타기 글의 내용을 배열한 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u4-X33']::text[],false,'{"seq":3,"concept":"K5-1-u4-C33","difficulty":3,"kind":"mc","stem":"다른 나라 친구들을 위한 줄타기 글의 내용을 배열한 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"줄타기가 무엇인지 → 특별한 점 → 기술 → 오늘날의 모습","correct":true},{"t":"역사 → 내 경험 → 기술 이름 → 다른 나라와 비교","mis":"K5-1-u4-X33"},{"t":"기술 이름 → 내 경험 → 역사 → 줄타기가 무엇인지","mis":"K5-1-u4-X33"},{"t":"생각나는 대로 아무 차례","mis":"K5-1-u4-X33"}],"explanation":["떠오른 대로 놓았어요.","무엇인지 모르는데 기술 이름부터 나와요.","낯선 친구가 따라오기 쉬운 차례예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_L07_challenge#4','kor',5,1,'u4','L07','g5_1_kor_u4_L07_challenge','lesson_challenge','K5-1-u4-C29',3,'error','auto','쓸 내용을 정하며 친구들이 한 말이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-1-u4-X29','K5-1-u4-X30']::text[],false,'{"seq":4,"concept":"K5-1-u4-C29","difficulty":3,"kind":"error","stem":"쓸 내용을 정하며 친구들이 한 말이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「구조부터 정해 두고 목적과 읽을 사람은 다 쓴 뒤에 생각하자.」","correct":true,"mis_target":"K5-1-u4-X29"},{"t":"「누가 읽을지 먼저 정해야 쓸 내용을 고를 수 있어.」","mis":"K5-1-u4-X29"},{"t":"「대상을 고른 까닭도 함께 말할 수 있어야 해.」","mis":"K5-1-u4-X30"}],"explanation":["알맞은 말이에요.","알맞은 말이에요.","목적과 읽을 사람이 먼저예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_L07_challenge#5','kor',5,1,'u4','L07','g5_1_kor_u4_L07_challenge','lesson_challenge','K5-1-u4-C31',3,'mc','auto','같은 줄타기라도 읽을 사람이 바뀌면 어떻게 되나요?',ARRAY['K5-1-u4-X31','K5-1-u4-X29']::text[],false,'{"seq":5,"concept":"K5-1-u4-C31","difficulty":3,"kind":"mc","stem":"같은 줄타기라도 읽을 사람이 바뀌면 어떻게 되나요?","options":[{"t":"고르는 내용과 쓰는 말이 달라진다","correct":true},{"t":"내용은 그대로 두고 글씨 크기만 바꾼다","mis":"K5-1-u4-X31"},{"t":"읽을 사람과 관계없이 똑같이 쓴다","mis":"K5-1-u4-X31"},{"t":"대상도 반드시 다른 것으로 바꿔야 한다","mis":"K5-1-u4-X29"}],"explanation":["글씨만의 문제가 아니에요.","읽을 사람을 생각해요.","대상은 그대로여도 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_L07_challenge#6','kor',5,1,'u4','L07','g5_1_kor_u4_L07_challenge','lesson_challenge','K5-1-u4-C30',3,'mc','auto','설명할 대상으로 가장 알맞지 않은 것은 어느 것인가요?',ARRAY['K5-1-u4-X30']::text[],false,'{"seq":6,"concept":"K5-1-u4-C30","difficulty":3,"kind":"mc","stem":"설명할 대상으로 가장 알맞지 않은 것은 어느 것인가요?","options":[{"t":"아무도 본 적 없고 자료도 없는 상상 속 놀이","correct":true},{"t":"할머니 댁에서 직접 해 본 투호","mis":"K5-1-u4-X30"},{"t":"우리 고장에서 해마다 열리는 탈놀이 공연","mis":"K5-1-u4-X30"},{"t":"도서관에서 책을 찾을 수 있는 옛 악기","mis":"K5-1-u4-X30"}],"explanation":["잘 아는 대상이에요.","알릴 값이 있어요.","자료가 없으면 설명할 수 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_L07_challenge#7','kor',5,1,'u4','L07','g5_1_kor_u4_L07_challenge','lesson_challenge','K5-1-u4-C13',3,'mc','auto','같은 대상을 두고 구조를 정하는 것은 무엇인가요?',ARRAY['K5-1-u4-X13','K5-1-u4-X30']::text[],false,'{"seq":7,"concept":"K5-1-u4-C13","difficulty":3,"kind":"mc","stem":"같은 대상을 두고 구조를 정하는 것은 무엇인가요?","options":[{"t":"무엇을 말하려는지","correct":true},{"t":"대상의 이름","mis":"K5-1-u4-X13"},{"t":"글의 길이","mis":"K5-1-u4-X13"},{"t":"글쓴이가 좋아하는 구조","mis":"K5-1-u4-X30"}],"explanation":["이름이 정하지 않아요.","길이는 기준이 아니에요.","말하려는 내용이 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_L07_challenge#8','kor',5,1,'u4','L07','g5_1_kor_u4_L07_challenge','lesson_challenge','K5-1-u4-C29',4,'essay','teacher','「우리 고장의 자랑거리」 가운데 설명할 대상을 하나 골라 글을 쓰는 목적 · 읽을 사람 · 대상과 고른 까닭 · 구조를 차례대로 정해 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K5-1-u4-C29","difficulty":4,"kind":"essay","stem":"「우리 고장의 자랑거리」 가운데 설명할 대상을 하나 골라 글을 쓰는 목적 · 읽을 사람 · 대상과 고른 까닭 · 구조를 차례대로 정해 쓰세요.","answer_guide":{"answer":"예: 목적 — 우리 고장의 갈대 습지를 알리기. 읽을 사람 — 다른 학교 친구들. 대상 — 갈대 습지(가족과 여러 번 가 보아 잘 알고, 안내 자료도 있다). 구조 — 습지에서 볼 수 있는 것을 여러 가지 소개하므로 열거 구조.","scoring_points":["목적과 읽을 사람을 정했는가","대상과 고른 까닭을 썼는가","내용에 맞는 구조를 정했는가"]},"explanation":["왜 쓰나요?","무엇을 왜 골랐나요?","어떤 틀이 맞나요?"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_L07_challenge#9','kor',5,1,'u4','L07','g5_1_kor_u4_L07_challenge','lesson_challenge','K5-1-u4-C31',4,'essay','teacher','줄타기를 저학년 동생에게 설명할 때와 다른 나라 친구에게 설명할 때 각각 어떻게 다르게 쓸지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K5-1-u4-C31","difficulty":4,"kind":"essay","stem":"줄타기를 저학년 동생에게 설명할 때와 다른 나라 친구에게 설명할 때 각각 어떻게 다르게 쓸지 쓰세요.","answer_guide":{"answer":"예: 저학년 동생에게는 어릿광대 같은 어려운 말을 쉬운 말로 바꾸고 줄 위에서 재주를 부리는 그림을 함께 넣는다. 다른 나라 친구에게는 줄광대와 어릿광대의 뜻을 풀어 주고, 그 나라 줄 공연과 무엇이 다른지 차근차근 견주어 설명한다.","scoring_points":["동생에게 쓸 방법을 썼는가","다른 나라 친구에게 쓸 방법을 썼는가","읽을 사람에 따라 달라지는 까닭이 드러나는가"]},"explanation":["동생이 어려워할 것은?","다른 나라 친구에게 낯선 것은?","읽을 사람을 생각해요."],"asset":{"type":"passage","lines":["㉮ 줄타기는 우리나라의 국가 무형유산이자 인류 무형문화유산이다.","㉯ 줄타기는 높이 맨 굵은 줄 위에서 재주를 부리는 공연이다. 줄 위의","　 사람을 줄광대, 땅에서 말을 주고받는 사람을 어릿광대라 한다.","㉰ 다른 나라의 줄 공연은 대개 재주를 보여 주는 데 집중한다. 반면 우리","　 줄타기의 줄광대는 노래하고 어릿광대와 우스갯소리를 주고받는다.","㉱ 한때 이어 갈 사람이 줄어 사라질 뻔했으나 오늘날까지 전해진다."],"title":"신문 글 「우리의 자랑, 줄타기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_L07_challenge#10','kor',5,1,'u4','L07','g5_1_kor_u4_L07_challenge','lesson_challenge','K5-1-u4-C33',4,'essay','teacher','줄타기 글을 쓸 때 쓸 내용을 떠오른 차례대로 늘어놓지 않고 배열해야 하는 까닭을 쓰고, 내가 배열한 차례를 예로 드세요.','{}'::text[],false,'{"seq":10,"concept":"K5-1-u4-C33","difficulty":4,"kind":"essay","stem":"줄타기 글을 쓸 때 쓸 내용을 떠오른 차례대로 늘어놓지 않고 배열해야 하는 까닭을 쓰고, 내가 배열한 차례를 예로 드세요.","answer_guide":{"answer":"예: 떠오른 차례대로 쓰면 읽는 사람이 무엇부터 알아야 할지 몰라 흥미를 잃고 글도 흩어진다. 그래서 줄타기가 무엇인지 먼저 알려 주고, 다른 나라 줄 공연과 다른 특별한 점, 여러 가지 재주, 오늘날 이어지는 모습의 차례로 배열한다.","scoring_points":["배열해야 하는 까닭을 썼는가","내가 배열한 차례를 썼는가","읽는 사람의 흥미와 짜임새를 생각했는가"]},"explanation":["떠오른 차례의 문제는?","무엇을 먼저 놓을까요?","읽는 사람을 떠올려요."],"asset":{"type":"passage","lines":["㉮ 줄타기는 우리나라의 국가 무형유산이자 인류 무형문화유산이다.","㉯ 줄타기는 높이 맨 굵은 줄 위에서 재주를 부리는 공연이다. 줄 위의","　 사람을 줄광대, 땅에서 말을 주고받는 사람을 어릿광대라 한다.","㉰ 다른 나라의 줄 공연은 대개 재주를 보여 주는 데 집중한다. 반면 우리","　 줄타기의 줄광대는 노래하고 어릿광대와 우스갯소리를 주고받는다.","㉱ 한때 이어 갈 사람이 줄어 사라질 뻔했으나 오늘날까지 전해진다."],"title":"신문 글 「우리의 자랑, 줄타기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_L09_basic#1','kor',5,1,'u4','L09','g5_1_kor_u4_L09_basic','lesson_basic','K5-1-u4-C36',1,'mc','auto','모은 자료를 점검하는 기준이 아닌 것은 어느 것인가요?',ARRAY['K5-1-u4-X36']::text[],false,'{"seq":1,"concept":"K5-1-u4-C36","difficulty":1,"kind":"mc","stem":"모은 자료를 점검하는 기준이 아닌 것은 어느 것인가요?","options":[{"t":"분량이 긴 자료인가","correct":true},{"t":"목적에 맞는 자료인가","mis":"K5-1-u4-X36"},{"t":"최신 자료인가","mis":"K5-1-u4-X36"},{"t":"신뢰할 수 있는 자료인가","mis":"K5-1-u4-X36"}],"explanation":["점검 기준이에요.","점검 기준이에요.","길이는 기준이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_L09_basic#2','kor',5,1,'u4','L09','g5_1_kor_u4_L09_basic','lesson_basic','K5-1-u4-C34',1,'mc','auto','자료를 조사할 때 함께 기록할 것으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u4-X34']::text[],false,'{"seq":2,"concept":"K5-1-u4-C34","difficulty":1,"kind":"mc","stem":"자료를 조사할 때 함께 기록할 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"찾은 곳(출처)과 찾은 날짜","correct":true},{"t":"찾은 자료의 글자 수","mis":"K5-1-u4-X34"},{"t":"자료를 찾을 때 든 기분","mis":"K5-1-u4-X34"},{"t":"자료가 마음에 든 정도","mis":"K5-1-u4-X34"}],"explanation":["글자 수는 필요 없어요.","기분은 기록할 것이 아니에요.","출처와 날짜를 남겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_L09_basic#3','kor',5,1,'u4','L09','g5_1_kor_u4_L09_basic','lesson_basic','K5-1-u4-C10',1,'mc','auto','「김치와 장아찌」는 어떤 구조로 쓴 글인가요?',ARRAY['K5-1-u4-X10','K5-1-u4-X09','K5-1-u4-X03']::text[],false,'{"seq":3,"concept":"K5-1-u4-C10","difficulty":1,"kind":"mc","stem":"「김치와 장아찌」는 어떤 구조로 쓴 글인가요?","options":[{"t":"비교와 대조 구조","correct":true},{"t":"열거 구조","mis":"K5-1-u4-X10"},{"t":"순서 구조","mis":"K5-1-u4-X09"},{"t":"구조가 없는 글","mis":"K5-1-u4-X03"}],"explanation":["두 음식을 견주었어요.","만드는 차례가 아니에요.","공통점과 차이점을 찾아 썼어요."],"asset":{"type":"passage","lines":["㉮ 김치와 장아찌는 모두 제철 재료를 손질해 담그고, 시간이 지나면서","　 맛이 깊어진다는 공통점이 있다.","㉯ 김치는 배추나 무를 소금에 절인 뒤 고춧가루와 젓갈을 넣어 버무린다.","　 반면 장아찌는 오이 같은 재료를 간장이나 된장에 재워 둔다.","㉰ 김치는 담근 지 며칠 뒤부터 먹기 시작한다. 반면 장아찌는 몇 달을","　 두었다가 꺼내 먹는 경우가 많다.","㉱ 이처럼 두 음식에는 재료를 오래 살려 두려는 조상의 지혜가 담겨 있다."],"title":"친구의 글 「김치와 장아찌」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_L09_basic#4','kor',5,1,'u4','L09','g5_1_kor_u4_L09_basic','lesson_basic','K5-1-u4-C38',1,'ox','auto','설명하는 글에 「나는 김치가 세상에서 제일 맛있다」처럼 내 느낌을 중심으로 써도 돼요.',ARRAY['K5-1-u4-X38']::text[],false,'{"seq":4,"concept":"K5-1-u4-C38","difficulty":1,"kind":"ox","stem":"설명하는 글에 「나는 김치가 세상에서 제일 맛있다」처럼 내 느낌을 중심으로 써도 돼요.","answer":"X","reason_options":[{"t":"설명하는 글은 대상의 특성을 알려 주는 글이라 글쓴이의 느낌은 중심이 아니기 때문에","correct":true},{"t":"느낌이 많이 들어갈수록 설명이 잘 되기 때문에","mis":"K5-1-u4-X38"}],"mis":"K5-1-u4-X38","explanation":["느낌은 중심이 아니에요.","특성을 알려 줘요.","설명하는 글의 일을 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_L09_basic#5','kor',5,1,'u4','L09','g5_1_kor_u4_L09_basic','lesson_basic','K5-1-u4-C35',2,'match','auto','조사할 내용과 알맞은 매체를 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K5-1-u4-C35","difficulty":2,"kind":"match","stem":"조사할 내용과 알맞은 매체를 이으세요.","pairs":[{"l":"우리 집에서 장아찌를 담그는 방법","r":"어른께 여쭙기"},{"l":"전통 발효 음식의 여러 종류","r":"전통 음식을 다룬 책"},{"l":"나라에서 정한 전통 음식 안내","r":"공공 기관 누리집"}],"mis":"K5-1-u4-X35","explanation":["우리 집 방법은 집안 어른이 알아요.","여러 종류는 책에 정리되어 있어요.","공식 안내는 공공 기관에 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_L09_basic#6','kor',5,1,'u4','L09','g5_1_kor_u4_L09_basic','lesson_basic','K5-1-u4-C37',2,'mc','auto','비교와 대조 구조로 시작한 글에서 지킬 것으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u4-X37','K5-1-u4-X19']::text[],false,'{"seq":6,"concept":"K5-1-u4-C37","difficulty":2,"kind":"mc","stem":"비교와 대조 구조로 시작한 글에서 지킬 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"끝까지 두 대상을 나란히 놓고 같은 항목끼리 견준다","correct":true},{"t":"중간부터는 김치만 늘어놓아도 된다","mis":"K5-1-u4-X37"},{"t":"뒷부분은 담그는 차례로 바꾼다","mis":"K5-1-u4-X37"},{"t":"한 문단에는 한 음식만 쓰고 다른 음식은 뺀다","mis":"K5-1-u4-X19"}],"explanation":["구조를 바꾸면 안 돼요.","구조를 바꾸면 안 돼요.","정한 구조를 끝까지 지켜요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_L09_basic#7','kor',5,1,'u4','L09','g5_1_kor_u4_L09_basic','lesson_basic','K5-1-u4-C39',2,'mc','auto','친구의 글 「김치와 장아찌」에 남긴 댓글 가운데 가장 도움이 되는 것은 어느 것인가요?',ARRAY['K5-1-u4-X39']::text[],false,'{"seq":7,"concept":"K5-1-u4-C39","difficulty":2,"kind":"mc","stem":"친구의 글 「김치와 장아찌」에 남긴 댓글 가운데 가장 도움이 되는 것은 어느 것인가요?","options":[{"t":"「비교와 대조 구조라 두 음식이 잘 견주어졌어. 젓갈이라는 말을 짧게 풀어 주면 더 좋겠어.」","correct":true},{"t":"「잘 썼네.」","mis":"K5-1-u4-X39"},{"t":"「그냥 별로야.」","mis":"K5-1-u4-X39"},{"t":"「내 글이 더 나은 것 같아.」","mis":"K5-1-u4-X39"}],"explanation":["칭찬만 있어요.","근거 없는 지적이에요.","좋았던 점과 보탤 점을 함께 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_L09_basic#8','kor',5,1,'u4','L09','g5_1_kor_u4_L09_basic','lesson_basic','K5-1-u4-C38',2,'mc','auto','「김치와 장아찌」에 어울리지 않는 문장은 어느 것인가요?',ARRAY['K5-1-u4-X38']::text[],false,'{"seq":8,"concept":"K5-1-u4-C38","difficulty":2,"kind":"mc","stem":"「김치와 장아찌」에 어울리지 않는 문장은 어느 것인가요?","options":[{"t":"나는 김치가 세상에서 제일 맛있다.","correct":true},{"t":"두 음식은 모두 오래 두고 먹는 저장 음식이다.","mis":"K5-1-u4-X38"},{"t":"반면 장아찌는 간장이나 된장에 재워 만든다.","mis":"K5-1-u4-X38"},{"t":"김치는 담근 지 며칠 뒤부터 먹기 시작한다.","mis":"K5-1-u4-X38"}],"explanation":["공통점을 설명해요.","차이점을 설명해요.","글쓴이의 느낌이라 어울리지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_L09_basic#9','kor',5,1,'u4','L09','g5_1_kor_u4_L09_basic','lesson_basic','K5-1-u4-C40',2,'mc','auto','글을 다 쓴 뒤에 할 일로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u4-X40','K5-1-u4-X39']::text[],false,'{"seq":9,"concept":"K5-1-u4-C40","difficulty":2,"kind":"mc","stem":"글을 다 쓴 뒤에 할 일로 알맞은 것은 어느 것인가요?","options":[{"t":"읽을 사람의 처지에서 다시 읽고 부족한 것은 더하고 없어도 되는 것은 뺀다","correct":true},{"t":"다 썼으니 바로 낸다","mis":"K5-1-u4-X40"},{"t":"글자만 예쁘게 다시 쓴다","mis":"K5-1-u4-X40"},{"t":"친구들의 댓글은 읽지 않는다","mis":"K5-1-u4-X39"}],"explanation":["다듬는 것도 쓰기예요.","내용을 다듬어요.","댓글은 좋은 길잡이예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_L09_basic#10','kor',5,1,'u4','L09','g5_1_kor_u4_L09_basic','lesson_basic','K5-1-u4-C36',3,'mc','auto','김치에 대해 모은 자료 가운데 점검 결과 쓰기 어려운 것은 어느 것인가요?',ARRAY['K5-1-u4-X36','K5-1-u4-X35']::text[],false,'{"seq":10,"concept":"K5-1-u4-C36","difficulty":3,"kind":"mc","stem":"김치에 대해 모은 자료 가운데 점검 결과 쓰기 어려운 것은 어느 것인가요?","options":[{"t":"누가 썼는지 모르는 게시글에 적힌, 아주 오래전 김치 이야기","correct":true},{"t":"전통 음식을 다룬 책에 실린 담그는 방법","mis":"K5-1-u4-X36"},{"t":"공공 기관 누리집에 올라온 최근 안내","mis":"K5-1-u4-X36"},{"t":"할머니께 여쭈어 적은 우리 집 김치 이야기","mis":"K5-1-u4-X35"}],"explanation":["믿을 수 있는 자료예요.","최신이고 믿을 수 있어요.","믿기 어렵고 최신도 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_L09_challenge#1','kor',5,1,'u4','L09','g5_1_kor_u4_L09_challenge','lesson_challenge','K5-1-u4-C34',2,'mc','auto','「김치와 장아찌」 조사 계획에서 빠지면 안 되는 것은 어느 것인가요?',ARRAY['K5-1-u4-X34','K5-1-u4-X36','K5-1-u4-X30']::text[],false,'{"seq":1,"concept":"K5-1-u4-C34","difficulty":2,"kind":"mc","stem":"「김치와 장아찌」 조사 계획에서 빠지면 안 되는 것은 어느 것인가요?","options":[{"t":"찾은 곳(출처)과 찾은 날짜를 적는 칸","correct":true},{"t":"좋아하는 음식 순위","mis":"K5-1-u4-X34"},{"t":"사진을 꾸밀 스티커","mis":"K5-1-u4-X36"},{"t":"글자 수 목표","mis":"K5-1-u4-X30"}],"explanation":["조사와 관계없어요.","꾸밈은 기준이 아니에요.","출처와 날짜가 있어야 믿고 쓸 수 있어요."],"asset":{"type":"passage","lines":["글의 내용 — 김치와 장아찌의 공통점과 차이점","조사할 내용 — 재료 · 담그는 방법 · 보관하는 방법 · 먹는 때","활용할 매체 — 공공 기관 누리집 · 전통 음식을 다룬 책 · 어른께 여쭙기","기록할 것 — 찾은 곳(출처)과 찾은 날짜"],"title":"「김치와 장아찌」 조사 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_L09_challenge#2','kor',5,1,'u4','L09','g5_1_kor_u4_L09_challenge','lesson_challenge','K5-1-u4-C38',2,'mc','auto','읽는 사람을 생각한 표현으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u4-X31','K5-1-u4-X38','K5-1-u4-X37']::text[],false,'{"seq":2,"concept":"K5-1-u4-C38","difficulty":2,"kind":"mc","stem":"읽는 사람을 생각한 표현으로 알맞은 것은 어느 것인가요?","options":[{"t":"어려운 말은 쉽게 풀어 쓴다","correct":true},{"t":"어려운 말을 더 많이 쓴다","mis":"K5-1-u4-X31"},{"t":"내 느낌을 더 많이 넣는다","mis":"K5-1-u4-X38"},{"t":"구조를 중간에 바꾼다","mis":"K5-1-u4-X37"}],"explanation":["읽기 어려워져요.","느낌은 중심이 아니에요.","쉽게 풀어 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_L09_challenge#3','kor',5,1,'u4','L09','g5_1_kor_u4_L09_challenge','lesson_challenge','K5-1-u4-C37',3,'error','auto','「김치와 장아찌」를 이어 쓰며 친구들이 한 말이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-1-u4-X37','K5-1-u4-X11']::text[],false,'{"seq":3,"concept":"K5-1-u4-C37","difficulty":3,"kind":"error","stem":"「김치와 장아찌」를 이어 쓰며 친구들이 한 말이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「보관하는 방법 문단은 김치 담그는 차례만 먼저 · 다음으로로 쓸래.」","correct":true,"mis_target":"K5-1-u4-X37"},{"t":"「보관하는 방법도 두 음식을 나란히 견주어 쓸게.」","mis":"K5-1-u4-X37"},{"t":"「반면이라는 말로 차이를 드러낼게.」","mis":"K5-1-u4-X11"}],"explanation":["알맞은 말이에요.","알맞은 말이에요.","도중에 구조를 바꾸면 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_L09_challenge#4','kor',5,1,'u4','L09','g5_1_kor_u4_L09_challenge','lesson_challenge','K5-1-u4-C39',3,'mc','auto','도움이 되는 댓글의 짜임으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u4-X39']::text[],false,'{"seq":4,"concept":"K5-1-u4-C39","difficulty":3,"kind":"mc","stem":"도움이 되는 댓글의 짜임으로 알맞은 것은 어느 것인가요?","options":[{"t":"좋았던 점과 보태면 좋을 점을 근거와 함께 쓴다","correct":true},{"t":"칭찬만 많이 쓴다","mis":"K5-1-u4-X39"},{"t":"고칠 점만 따끔하게 쓴다","mis":"K5-1-u4-X39"},{"t":"내 글과 견주어 누가 나은지 쓴다","mis":"K5-1-u4-X39"}],"explanation":["글이 나아지지 않아요.","마음이 상해요.","두 가지를 함께 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_L09_challenge#5','kor',5,1,'u4','L09','g5_1_kor_u4_L09_challenge','lesson_challenge','K5-1-u4-C40',3,'mc','auto','쓰기 과정을 점검하는 질문으로 알맞지 않은 것은 어느 것인가요?',ARRAY['K5-1-u4-X40']::text[],false,'{"seq":5,"concept":"K5-1-u4-C40","difficulty":3,"kind":"mc","stem":"쓰기 과정을 점검하는 질문으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"글씨를 가장 빨리 썼나요?","correct":true},{"t":"대상과 내용에 맞게 자료를 모았나요?","mis":"K5-1-u4-X40"},{"t":"내용에 맞는 글의 구조를 정했나요?","mis":"K5-1-u4-X40"},{"t":"목적과 읽을 사람을 생각하며 다듬었나요?","mis":"K5-1-u4-X40"}],"explanation":["점검할 것이에요.","점검할 것이에요.","빠르기는 점검 기준이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_L09_challenge#6','kor',5,1,'u4','L09','g5_1_kor_u4_L09_challenge','lesson_challenge','K5-1-u4-C35',3,'mc','auto','나라에서 정해 알린 정확한 공식 정보를 찾으려면 어떤 매체가 가장 알맞나요?',ARRAY['K5-1-u4-X35','K5-1-u4-X36']::text[],false,'{"seq":6,"concept":"K5-1-u4-C35","difficulty":3,"kind":"mc","stem":"나라에서 정해 알린 정확한 공식 정보를 찾으려면 어떤 매체가 가장 알맞나요?","options":[{"t":"공공 기관 누리집","correct":true},{"t":"친구에게 전해 들은 이야기","mis":"K5-1-u4-X35"},{"t":"누가 썼는지 모르는 게시글","mis":"K5-1-u4-X36"},{"t":"내 짐작","mis":"K5-1-u4-X35"}],"explanation":["전해 들은 말은 정확하지 않을 수 있어요.","믿기 어려워요.","공식 정보는 공공 기관에 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_L09_challenge#7','kor',5,1,'u4','L09','g5_1_kor_u4_L09_challenge','lesson_challenge','K5-1-u4-C36',3,'mc','auto','자료를 점검할 때 「최신 자료인가」를 따지는 까닭은 무엇인가요?',ARRAY['K5-1-u4-X36']::text[],false,'{"seq":7,"concept":"K5-1-u4-C36","difficulty":3,"kind":"mc","stem":"자료를 점검할 때 「최신 자료인가」를 따지는 까닭은 무엇인가요?","options":[{"t":"설명하려는 내용이 바뀌었을 수 있어 요즘 것을 다룬 자료인지 봐야 하기 때문이다","correct":true},{"t":"오래된 자료일수록 믿을 만하기 때문이다","mis":"K5-1-u4-X36"},{"t":"자료가 길수록 새것이기 때문이다","mis":"K5-1-u4-X36"},{"t":"사진이 많을수록 새것이기 때문이다","mis":"K5-1-u4-X36"}],"explanation":["오래되면 바뀐 것이 있을 수 있어요.","길이와 관계없어요.","사진과 관계없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_L09_challenge#8','kor',5,1,'u4','L09','g5_1_kor_u4_L09_challenge','lesson_challenge','K5-1-u4-C39',4,'essay','teacher','친구의 글 「김치와 장아찌」에 도움이 되는 댓글을 쓰세요. 좋았던 점과 보태면 좋을 점을 근거와 함께 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K5-1-u4-C39","difficulty":4,"kind":"essay","stem":"친구의 글 「김치와 장아찌」에 도움이 되는 댓글을 쓰세요. 좋았던 점과 보태면 좋을 점을 근거와 함께 쓰세요.","answer_guide":{"answer":"예: 「반면」이라는 말로 두 음식의 차이를 분명하게 드러내서 담그는 방법과 먹는 때가 한눈에 견주어졌어. 다만 「젓갈」은 동생들이 모를 수 있으니 무엇인지 짧게 풀어 주고, 보관하는 방법도 견주어 주면 더 좋겠어.","scoring_points":["좋았던 점을 근거와 함께 썼는가","보태면 좋을 점을 썼는가","예의 있게 썼는가"]},"explanation":["잘된 곳은 어디인가요?","더하면 좋을 것은?","근거를 들어요."],"asset":{"type":"passage","lines":["㉮ 김치와 장아찌는 모두 제철 재료를 손질해 담그고, 시간이 지나면서","　 맛이 깊어진다는 공통점이 있다.","㉯ 김치는 배추나 무를 소금에 절인 뒤 고춧가루와 젓갈을 넣어 버무린다.","　 반면 장아찌는 오이 같은 재료를 간장이나 된장에 재워 둔다.","㉰ 김치는 담근 지 며칠 뒤부터 먹기 시작한다. 반면 장아찌는 몇 달을","　 두었다가 꺼내 먹는 경우가 많다.","㉱ 이처럼 두 음식에는 재료를 오래 살려 두려는 조상의 지혜가 담겨 있다."],"title":"친구의 글 「김치와 장아찌」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_L09_challenge#9','kor',5,1,'u4','L09','g5_1_kor_u4_L09_challenge','lesson_challenge','K5-1-u4-C36',4,'essay','teacher','모은 자료를 점검하는 세 가지 기준을 쓰고, 각 기준이 왜 필요한지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K5-1-u4-C36","difficulty":4,"kind":"essay","stem":"모은 자료를 점검하는 세 가지 기준을 쓰고, 각 기준이 왜 필요한지 쓰세요.","answer_guide":{"answer":"예: 첫째, 찾는 목적에 맞는 자료인지 본다. 목적과 관계없는 자료는 글을 흩트린다. 둘째, 최신 자료인지 본다. 오래된 자료는 지금과 다를 수 있다. 셋째, 신뢰할 수 있는 자료인지 본다. 누가 썼는지 모르는 자료는 틀린 내용이 있을 수 있다.","scoring_points":["세 기준을 모두 썼는가","기준마다 필요한 까닭을 썼는가","분량이나 꾸밈을 기준으로 넣지 않았는가"]},"explanation":["목적 · 최신 · 신뢰예요.","없으면 어떤 일이 생길까요?","세 가지를 모두 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_L09_challenge#10','kor',5,1,'u4','L09','g5_1_kor_u4_L09_challenge','lesson_challenge','K5-1-u4-C40',4,'essay','teacher','설명하는 글을 쓸 때 다 쓴 글만이 아니라 쓰기 과정 전체를 점검해야 하는 까닭을 쓰고, 다 쓴 뒤 다듬는 방법을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K5-1-u4-C40","difficulty":4,"kind":"essay","stem":"설명하는 글을 쓸 때 다 쓴 글만이 아니라 쓰기 과정 전체를 점검해야 하는 까닭을 쓰고, 다 쓴 뒤 다듬는 방법을 쓰세요.","answer_guide":{"answer":"예: 자료를 제대로 모았는지, 내용에 맞는 구조를 정했는지, 끝까지 구조를 지켰는지에 따라 글의 짜임이 달라지므로 과정 전체를 돌아봐야 어디를 고칠지 알 수 있다. 다 쓴 뒤에는 읽을 사람의 처지에서 다시 읽고, 부족한 내용은 더하고 없어도 되는 부분은 빼며, 친구들의 댓글도 참고한다.","scoring_points":["과정 전체를 점검하는 까닭을 썼는가","읽을 사람의 처지에서 다시 읽는다고 썼는가","더하고 빼는 다듬기를 썼는가"]},"explanation":["어느 단계에서 문제가 생길까요?","누구의 처지에서 읽나요?","무엇을 더하고 빼나요?"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_L12_basic#1','kor',5,1,'u4','L12','g5_1_kor_u4_L12_basic','lesson_basic','K5-1-u4-C41',1,'mc','auto','반 전체가 만드는 글 모음집의 주제로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u4-X41']::text[],false,'{"seq":1,"concept":"K5-1-u4-C41","difficulty":1,"kind":"mc","stem":"반 전체가 만드는 글 모음집의 주제로 알맞은 것은 어느 것인가요?","options":[{"t":"우리나라 전통 놀이","correct":true},{"t":"어제 내가 꾼 꿈","mis":"K5-1-u4-X41"},{"t":"내 사물함 비밀번호","mis":"K5-1-u4-X41"},{"t":"내 일기장에 적은 비밀","mis":"K5-1-u4-X41"}],"explanation":["혼자만 아는 일이에요.","알리면 안 되는 것이에요.","여럿이 나누어 쓸 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_L12_basic#2','kor',5,1,'u4','L12','g5_1_kor_u4_L12_basic','lesson_basic','K5-1-u4-C45',1,'mc','auto','글 모음집에 들어갈 것이 아닌 것은 어느 것인가요?',ARRAY['K5-1-u4-X45']::text[],false,'{"seq":2,"concept":"K5-1-u4-C45","difficulty":1,"kind":"mc","stem":"글 모음집에 들어갈 것이 아닌 것은 어느 것인가요?","options":[{"t":"친구들의 시험 점수","correct":true},{"t":"표지","mis":"K5-1-u4-X45"},{"t":"머리말","mis":"K5-1-u4-X45"},{"t":"차례","mis":"K5-1-u4-X45"}],"explanation":["들어가요.","들어가요.","모음집과 관계없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_L12_basic#3','kor',5,1,'u4','L12','g5_1_kor_u4_L12_basic','lesson_basic','K5-1-u4-C42',1,'mc','auto','글 모음집을 만들 때 가장 먼저 할 일은 어느 것인가요?',ARRAY['K5-1-u4-X42']::text[],false,'{"seq":3,"concept":"K5-1-u4-C42","difficulty":1,"kind":"mc","stem":"글 모음집을 만들 때 가장 먼저 할 일은 어느 것인가요?","options":[{"t":"반 전체가 다룰 큰 주제 정하기","correct":true},{"t":"글을 모음집으로 묶기","mis":"K5-1-u4-X42"},{"t":"구조를 골라 정리하기","mis":"K5-1-u4-X42"},{"t":"각자 글 쓰기","mis":"K5-1-u4-X42"}],"explanation":["맨 마지막이에요.","대상을 고른 뒤예요.","큰 주제부터 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_L12_basic#4','kor',5,1,'u4','L12','g5_1_kor_u4_L12_basic','lesson_basic','K5-1-u4-C43',1,'ox','auto','한 모음집에 실릴 글은 모두 똑같은 구조로 써야 해요.',ARRAY['K5-1-u4-X43']::text[],false,'{"seq":4,"concept":"K5-1-u4-C43","difficulty":1,"kind":"ox","stem":"한 모음집에 실릴 글은 모두 똑같은 구조로 써야 해요.","answer":"X","reason_options":[{"t":"주제가 같아도 대상과 말하려는 내용에 따라 알맞은 구조가 저마다 다를 수 있기 때문에","correct":true},{"t":"구조가 같아야만 한 권으로 묶을 수 있기 때문에","mis":"K5-1-u4-X43"}],"mis":"K5-1-u4-X43","explanation":["대상마다 달라요.","겉모습을 맞추면 한 권이 돼요.","구조는 저마다 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_L12_basic#5','kor',5,1,'u4','L12','g5_1_kor_u4_L12_basic','lesson_basic','K5-1-u4-C43',2,'match','auto','모음집에 실을 글의 쓸 내용과 알맞은 구조를 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K5-1-u4-C43","difficulty":2,"kind":"match","stem":"모음집에 실을 글의 쓸 내용과 알맞은 구조를 이으세요.","pairs":[{"l":"한지를 만드는 과정","r":"순서 구조"},{"l":"제기차기의 여러 방법","r":"열거 구조"},{"l":"널뛰기와 그네뛰기의 같은 점과 다른 점","r":"비교와 대조 구조"}],"mis":"K5-1-u4-X43","explanation":["과정은 차례가 있어요.","여러 방법은 나열해요.","두 놀이를 견줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_L12_basic#6','kor',5,1,'u4','L12','g5_1_kor_u4_L12_basic','lesson_basic','K5-1-u4-C44',2,'mc','auto','모음집을 만들 때 반 전체가 미리 정할 것으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u4-X43','K5-1-u4-X44']::text[],false,'{"seq":6,"concept":"K5-1-u4-C44","difficulty":2,"kind":"mc","stem":"모음집을 만들 때 반 전체가 미리 정할 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"제목 다는 방식과 글의 분량","correct":true},{"t":"모두 똑같은 구조로 쓰기","mis":"K5-1-u4-X43"},{"t":"모두 똑같은 대상 고르기","mis":"K5-1-u4-X43"},{"t":"아무것도 정하지 않고 각자 마음대로 하기","mis":"K5-1-u4-X44"}],"explanation":["구조는 저마다 달라도 돼요.","대상은 각자 골라요.","겉모습을 맞춰야 한 권으로 보여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_L12_basic#7','kor',5,1,'u4','L12','g5_1_kor_u4_L12_basic','lesson_basic','K5-1-u4-C45',2,'mc','auto','모음집의 머리말에 쓸 내용으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u4-X45']::text[],false,'{"seq":7,"concept":"K5-1-u4-C45","difficulty":2,"kind":"mc","stem":"모음집의 머리말에 쓸 내용으로 알맞은 것은 어느 것인가요?","options":[{"t":"어떤 주제로 왜 글을 모았는지","correct":true},{"t":"글 제목과 쪽수","mis":"K5-1-u4-X45"},{"t":"각 글에서 활용한 자료","mis":"K5-1-u4-X45"},{"t":"모음집 제목과 만든 사람들","mis":"K5-1-u4-X45"}],"explanation":["그것은 차례예요.","그것은 출처예요.","머리말은 모은 까닭을 밝혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_L12_basic#8','kor',5,1,'u4','L12','g5_1_kor_u4_L12_basic','lesson_basic','K5-1-u4-C45',2,'mc','auto','모음집에 출처를 넣는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u4-X45','K5-1-u4-X34']::text[],false,'{"seq":8,"concept":"K5-1-u4-C45","difficulty":2,"kind":"mc","stem":"모음집에 출처를 넣는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"각 글에서 활용한 자료를 밝혀 읽는 사람이 믿고 볼 수 있게 하려고","correct":true},{"t":"쪽수를 늘리려고","mis":"K5-1-u4-X45"},{"t":"차례 대신 쓰려고","mis":"K5-1-u4-X45"},{"t":"출처는 넣지 않아도 된다","mis":"K5-1-u4-X34"}],"explanation":["쪽수와 관계없어요.","차례와 다른 것이에요.","출처가 믿음을 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_L12_basic#9','kor',5,1,'u4','L12','g5_1_kor_u4_L12_basic','lesson_basic','K5-1-u4-C46',2,'mc','auto','완성한 모음집에서 친구의 글을 읽을 때 해 볼 일로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u4-X46']::text[],false,'{"seq":9,"concept":"K5-1-u4-C46","difficulty":2,"kind":"mc","stem":"완성한 모음집에서 친구의 글을 읽을 때 해 볼 일로 알맞은 것은 어느 것인가요?","options":[{"t":"어떤 구조를 썼는지 찾아보며 읽는다","correct":true},{"t":"구조는 보지 않고 글자 수만 센다","mis":"K5-1-u4-X46"},{"t":"같은 주제니까 모두 똑같이 읽힌다고 여긴다","mis":"K5-1-u4-X46"},{"t":"내 글만 읽는다","mis":"K5-1-u4-X46"}],"explanation":["구조를 살펴요.","틀이 다르면 느낌도 달라요.","친구의 글에서 배워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_L12_basic#10','kor',5,1,'u4','L12','g5_1_kor_u4_L12_basic','lesson_basic','K5-1-u4-C41',3,'mc','auto','「여러 가지 직업」이 글 모음집 주제로 알맞은 까닭은 무엇인가요?',ARRAY['K5-1-u4-X41','K5-1-u4-X43']::text[],false,'{"seq":10,"concept":"K5-1-u4-C41","difficulty":3,"kind":"mc","stem":"「여러 가지 직업」이 글 모음집 주제로 알맞은 까닭은 무엇인가요?","options":[{"t":"여러 사람이 각자 다른 직업을 골라 나누어 쓸 수 있기 때문이다","correct":true},{"t":"한 사람만 쓸 수 있기 때문이다","mis":"K5-1-u4-X41"},{"t":"아무도 자료를 찾을 수 없기 때문이다","mis":"K5-1-u4-X41"},{"t":"모두 똑같은 직업을 써야 하기 때문이다","mis":"K5-1-u4-X43"}],"explanation":["여럿이 써요.","자료를 찾을 수 있어요.","저마다 다른 대상을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_L12_challenge#1','kor',5,1,'u4','L12','g5_1_kor_u4_L12_challenge','lesson_challenge','K5-1-u4-C42',2,'mc','auto','글 모음집을 만드는 차례로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u4-X42']::text[],false,'{"seq":1,"concept":"K5-1-u4-C42","difficulty":2,"kind":"mc","stem":"글 모음집을 만드는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"큰 주제 → 각자 대상 → 대상에 맞는 구조 → 글을 써서 묶기","correct":true},{"t":"묶기 → 글쓰기 → 큰 주제 → 대상","mis":"K5-1-u4-X42"},{"t":"구조 → 큰 주제 → 묶기 → 대상","mis":"K5-1-u4-X42"},{"t":"대상 → 묶기 → 구조 → 큰 주제","mis":"K5-1-u4-X42"}],"explanation":["묶기는 맨 끝이에요.","주제부터 정해요.","주제 → 대상 → 구조 → 묶기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
