INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_L12_challenge#5','kor',5,1,'u4','L12','g5_1_kor_u4_L12_challenge','lesson_challenge','K5-1-u4-C45',3,'mc','auto','모음집의 차례를 만드는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u4-X45']::text[],false,'{"seq":5,"concept":"K5-1-u4-C45","difficulty":3,"kind":"mc","stem":"모음집의 차례를 만드는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"글 제목과 쪽수를 적고, 같은 구조의 글끼리 묶어 배열해도 좋다","correct":true},{"t":"쪽수 없이 제목만 아무렇게나 적는다","mis":"K5-1-u4-X45"},{"t":"차례에 친구들의 점수를 적는다","mis":"K5-1-u4-X45"},{"t":"차례는 만들지 않는다","mis":"K5-1-u4-X45"}],"explanation":["쪽수가 있어야 찾아요.","점수는 관계없어요.","차례가 있어야 찾아 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_L12_challenge#6','kor',5,1,'u4','L12','g5_1_kor_u4_L12_challenge','lesson_challenge','K5-1-u4-C41',3,'mc','auto','글 모음집 주제로 가장 알맞지 않은 것은 어느 것인가요?',ARRAY['K5-1-u4-X41']::text[],false,'{"seq":6,"concept":"K5-1-u4-C41","difficulty":3,"kind":"mc","stem":"글 모음집 주제로 가장 알맞지 않은 것은 어느 것인가요?","options":[{"t":"내 사물함 비밀번호","correct":true},{"t":"여러 가지 직업","mis":"K5-1-u4-X41"},{"t":"우리 고장의 자랑거리","mis":"K5-1-u4-X41"},{"t":"우리나라 전통 놀이","mis":"K5-1-u4-X41"}],"explanation":["알맞은 주제예요.","알맞은 주제예요.","알리면 안 되고 나누어 쓸 수도 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_L12_challenge#7','kor',5,1,'u4','L12','g5_1_kor_u4_L12_challenge','lesson_challenge','K5-1-u4-C46',3,'mc','auto','모음집을 만든 뒤 소감을 나눌 때 할 일로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u4-X46','K5-1-u4-X39']::text[],false,'{"seq":7,"concept":"K5-1-u4-C46","difficulty":3,"kind":"mc","stem":"모음집을 만든 뒤 소감을 나눌 때 할 일로 알맞은 것은 어느 것인가요?","options":[{"t":"친구 글에서 찾은 구조와 그에 따라 달라진 읽는 느낌을 이야기한다","correct":true},{"t":"누구 글이 가장 긴지 겨룬다","mis":"K5-1-u4-X46"},{"t":"구조는 이야기하지 않는다","mis":"K5-1-u4-X46"},{"t":"잘못된 점만 골라 말한다","mis":"K5-1-u4-X39"}],"explanation":["길이를 겨루는 것이 아니에요.","구조를 이야기해요.","좋은 점도 함께 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_L12_challenge#8','kor',5,1,'u4','L12','g5_1_kor_u4_L12_challenge','lesson_challenge','K5-1-u4-C43',4,'essay','teacher','「여러 가지 직업」 모음집에 실을 내 글의 대상을 하나 정하고, 말하려는 내용과 알맞은 구조를 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K5-1-u4-C43","difficulty":4,"kind":"essay","stem":"「여러 가지 직업」 모음집에 실을 내 글의 대상을 하나 정하고, 말하려는 내용과 알맞은 구조를 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 대상 — 소방관. 말하려는 내용 — 소방관이 하는 여러 가지 일(불 끄기 · 사람 구하기 · 안전 교육). 구조 — 여러 가지 일을 항목별로 소개하므로 열거 구조가 알맞다.","scoring_points":["대상을 정했는가","말하려는 내용을 썼는가","내용에 맞는 구조와 까닭을 썼는가"]},"explanation":["어떤 직업을 고를까요?","무엇을 말하려나요?","그 내용에 맞는 틀은?"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_L12_challenge#9','kor',5,1,'u4','L12','g5_1_kor_u4_L12_challenge','lesson_challenge','K5-1-u4-C44',4,'essay','teacher','따로 쓴 글을 한 권의 모음집으로 묶으려면 반 전체가 미리 정할 것과 모음집에 넣을 것을 각각 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K5-1-u4-C44","difficulty":4,"kind":"essay","stem":"따로 쓴 글을 한 권의 모음집으로 묶으려면 반 전체가 미리 정할 것과 모음집에 넣을 것을 각각 쓰세요.","answer_guide":{"answer":"예: 미리 정할 것 — 제목 다는 방식, 글의 분량, 사진을 넣을지. 넣을 것 — 모음집 제목과 만든 사람들을 적은 표지, 어떤 주제로 왜 모았는지 밝힌 머리말, 글 제목과 쪽수를 적은 차례, 각 글에서 활용한 자료의 출처.","scoring_points":["미리 정할 겉모습을 썼는가","넣을 것 네 가지를 썼는가","구조까지 똑같이 맞추라고 쓰지 않았는가"]},"explanation":["겉모습을 떠올려요.","표지 · 머리말 · 차례 · 출처예요.","구조는 저마다 달라도 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_L12_challenge#10','kor',5,1,'u4','L12','g5_1_kor_u4_L12_challenge','lesson_challenge','K5-1-u4-C46',4,'essay','teacher','완성한 모음집에서 친구의 글을 읽으며 어떤 구조를 썼는지 찾아보는 것이 왜 좋은지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K5-1-u4-C46","difficulty":4,"kind":"essay","stem":"완성한 모음집에서 친구의 글을 읽으며 어떤 구조를 썼는지 찾아보는 것이 왜 좋은지 쓰세요.","answer_guide":{"answer":"예: 같은 주제라도 친구가 고른 틀에 따라 읽는 느낌이 달라지는 것을 알 수 있다. 친구의 글에서 구조를 찾다 보면 열거 · 순서 · 비교와 대조가 각각 어떤 내용에 어울리는지 한 번 더 정리되어 배운 것이 내 것이 된다.","scoring_points":["읽는 느낌의 차이를 썼는가","배운 것이 다시 정리된다고 썼는가","구조를 찾아보는 활동과 이어 썼는가"]},"explanation":["틀이 다르면?","무엇이 다시 정리되나요?","찾아보는 활동과 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_review_a#1','kor',5,1,'u4','','g5_1_kor_u4_review_a','unit_review','K5-1-u4-C48',1,'mc','auto','「파랗다」 앞에 붙어 「매우 짙고 선명하게」의 뜻을 더하는 말로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u4-X48','K5-1-u4-X49']::text[],false,'{"seq":1,"concept":"K5-1-u4-C48","difficulty":1,"kind":"mc","stem":"「파랗다」 앞에 붙어 「매우 짙고 선명하게」의 뜻을 더하는 말로 알맞은 것은 어느 것인가요?","options":[{"t":"새-","correct":true},{"t":"샛-","mis":"K5-1-u4-X48"},{"t":"싯-","mis":"K5-1-u4-X48"},{"t":"시-","mis":"K5-1-u4-X49"}],"explanation":["ㄴ · ㅁ 앞에 붙어요.","ㄴ · ㅁ 앞에 붙어요.","첫소리가 거센소리 ㅍ, 모음이 ㅏ라 새-예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_review_a#2','kor',5,1,'u4','','g5_1_kor_u4_review_a','unit_review','K5-1-u4-C49',1,'mc','auto','「퍼렇다」 앞에 붙는 말로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u4-X49','K5-1-u4-X48']::text[],false,'{"seq":2,"concept":"K5-1-u4-C49","difficulty":1,"kind":"mc","stem":"「퍼렇다」 앞에 붙는 말로 알맞은 것은 어느 것인가요?","options":[{"t":"시-","correct":true},{"t":"새-","mis":"K5-1-u4-X49"},{"t":"샛-","mis":"K5-1-u4-X48"},{"t":"싯-","mis":"K5-1-u4-X48"}],"explanation":["모음이 ㅓ예요.","첫소리가 거센소리예요.","첫소리 ㅍ, 모음 ㅓ라 시-예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_review_a#3','kor',5,1,'u4','','g5_1_kor_u4_review_a','unit_review','K5-1-u4-C47',1,'mc','auto','새- · 샛- · 시- · 싯-이 뒤에 오는 말에 더하는 뜻은 어느 것인가요?',ARRAY['K5-1-u4-X47']::text[],false,'{"seq":3,"concept":"K5-1-u4-C47","difficulty":1,"kind":"mc","stem":"새- · 샛- · 시- · 싯-이 뒤에 오는 말에 더하는 뜻은 어느 것인가요?","options":[{"t":"매우 짙고 선명하게","correct":true},{"t":"조금 옅게","mis":"K5-1-u4-X47"},{"t":"새로 생긴","mis":"K5-1-u4-X47"},{"t":"아주 작게","mis":"K5-1-u4-X47"}],"explanation":["반대 뜻이에요.","「새것」의 뜻이 아니에요.","짙고 선명한 느낌을 더해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_review_a#4','kor',5,1,'u4','','g5_1_kor_u4_review_a','unit_review','K5-1-u4-C10',1,'mc','auto','단비의 글은 어떤 구조로 쓴 글인가요?',ARRAY['K5-1-u4-X10','K5-1-u4-X09','K5-1-u4-X03']::text[],false,'{"seq":4,"concept":"K5-1-u4-C10","difficulty":1,"kind":"mc","stem":"단비의 글은 어떤 구조로 쓴 글인가요?","options":[{"t":"비교와 대조 구조","correct":true},{"t":"열거 구조","mis":"K5-1-u4-X10"},{"t":"순서 구조","mis":"K5-1-u4-X09"},{"t":"구조가 없는 글","mis":"K5-1-u4-X03"}],"explanation":["두 신발을 견주었어요.","만드는 차례가 아니에요.","공통점과 차이점을 찾아 썼어요."],"asset":{"type":"passage","lines":["㉮ 짚신과 나막신은 옛날 사람들이 신던 신발로, 둘 다 자연에서","　 얻은 재료로 만들었다는 공통점이 있다.","㉯ 짚신은 볏짚을 꼬아 엮어 만들어 가볍고 발이 편하다. 반면","　 나막신은 통나무를 파서 만들어 무겁지만 물이 스미지 않는다.","㉰ 신는 날도 달랐다. 짚신은 마른 날에 신었고, 나막신은 굽이","　 높아서 비가 오거나 땅이 질척한 날에 신었다.","㉱ 나는 나막신이 또각또각 울리는 소리가 세상에서 제일 좋다."],"title":"단비의 글 초안 「짚신과 나막신」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_review_a#5','kor',5,1,'u4','','g5_1_kor_u4_review_a','unit_review','K5-1-u4-C8',1,'mc','auto','무진이의 글은 어떤 구조로 쓴 글인가요?',ARRAY['K5-1-u4-X08','K5-1-u4-X10','K5-1-u4-X03']::text[],false,'{"seq":5,"concept":"K5-1-u4-C8","difficulty":1,"kind":"mc","stem":"무진이의 글은 어떤 구조로 쓴 글인가요?","options":[{"t":"열거 구조","correct":true},{"t":"순서 구조","mis":"K5-1-u4-X08"},{"t":"비교와 대조 구조","mis":"K5-1-u4-X10"},{"t":"구조가 없는 글","mis":"K5-1-u4-X03"}],"explanation":["차례가 아니라 쓰임을 늘어놓았어요.","두 대상을 견주지 않았어요.","부채의 쓰임을 항목별로 나열했어요."],"asset":{"type":"passage","lines":["부채는 손으로 흔들어 바람을 일으키는 물건이다.","첫째, 더운 날 바람을 일으켜 땀을 식혀 준다.","둘째, 햇볕이 따가울 때 얼굴을 가리는 데 쓴다.","셋째, 판소리를 하는 소리꾼은 부채를 펴고 접으며 이야기를 살린다.","넷째, 옛날에는 단옷날 부채를 선물하며 여름을 잘 나기를 빌었다.","이처럼 부채는 바람을 일으키는 데에만 쓰인 것이 아니다."],"title":"무진이의 글 「부채의 여러 가지 쓰임」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_review_a#6','kor',5,1,'u4','','g5_1_kor_u4_review_a','unit_review','K5-1-u4-C9',1,'mc','auto','서우의 글은 어떤 구조로 쓴 글인가요?',ARRAY['K5-1-u4-X09','K5-1-u4-X10','K5-1-u4-X03']::text[],false,'{"seq":6,"concept":"K5-1-u4-C9","difficulty":1,"kind":"mc","stem":"서우의 글은 어떤 구조로 쓴 글인가요?","options":[{"t":"순서 구조","correct":true},{"t":"열거 구조","mis":"K5-1-u4-X09"},{"t":"비교와 대조 구조","mis":"K5-1-u4-X10"},{"t":"구조가 없는 글","mis":"K5-1-u4-X03"}],"explanation":["단계가 차례대로 있어요.","두 대상을 견주지 않았어요.","가는 차례를 밝혔어요."],"asset":{"type":"passage","lines":["맷돌은 둥근 돌 두 짝을 포개어 곡식을 가는 도구이다.","먼저, 콩을 물에 담가 하룻밤 불린다.","다음으로, 위짝의 구멍에 불린 콩과 물을 조금씩 넣는다.","그 뒤, 손잡이를 잡고 위짝을 한 방향으로 천천히 돌린다.","마지막으로, 두 짝 사이로 흘러나온 콩물을 그릇에 받는다."],"title":"서우의 글 「맷돌로 콩 가는 차례」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_review_a#7','kor',5,1,'u4','','g5_1_kor_u4_review_a','unit_review','K5-1-u4-C24',1,'mc','auto','강솔이의 글은 어떤 구조로 쓴 글인가요?',ARRAY['K5-1-u4-X08','K5-1-u4-X10','K5-1-u4-X03']::text[],false,'{"seq":7,"concept":"K5-1-u4-C24","difficulty":1,"kind":"mc","stem":"강솔이의 글은 어떤 구조로 쓴 글인가요?","options":[{"t":"열거 구조","correct":true},{"t":"순서 구조","mis":"K5-1-u4-X08"},{"t":"비교와 대조 구조","mis":"K5-1-u4-X10"},{"t":"구조가 없는 글","mis":"K5-1-u4-X03"}],"explanation":["차례를 바꾸어도 돼요.","견주지 않았어요.","방법을 항목별로 나열했어요."],"asset":{"type":"passage","lines":["㉮ 학교 도서관 책은 여러 사람이 돌려 가며 읽는다. 책을 오래","　 읽으려면 어떻게 해야 할지 알아보자.","㉯ 첫째, 깨끗한 손으로 책장을 넘긴다. 손에 묻은 기름과 먼지는","　 책장을 누렇게 만든다. 둘째, 읽던 곳은 책장을 접지 말고","　 책갈피를 끼운다. 셋째, 다 읽은 책은 제때 돌려준다.","㉰ 이처럼 책을 아끼는 작은 습관은 다음에 읽을 친구를 위한","　 배려이다. 오늘 빌린 책부터 실천해 보자."],"title":"강솔이의 학급 신문 글 「도서관 책을 오래 읽는 방법」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_review_a#8','kor',5,1,'u4','','g5_1_kor_u4_review_a','unit_review','K5-1-u4-C30',1,'mc','auto','해담이가 지게를 대상으로 고른 까닭과 이어지는 기준은 어느 것인가요?',ARRAY['K5-1-u4-X30']::text[],false,'{"seq":8,"concept":"K5-1-u4-C30","difficulty":1,"kind":"mc","stem":"해담이가 지게를 대상으로 고른 까닭과 이어지는 기준은 어느 것인가요?","options":[{"t":"잘 아는 것 — 직접 져 본 적이 있다","correct":true},{"t":"글자 수를 많이 채울 수 있다","mis":"K5-1-u4-X30"},{"t":"좋아하는 색과 어울린다","mis":"K5-1-u4-X30"},{"t":"아무도 몰라서 자료가 없다","mis":"K5-1-u4-X30"}],"explanation":["글자 수는 기준이 아니에요.","색은 기준이 아니에요.","직접 해 보았으니 자세히 쓸 수 있어요."],"asset":{"type":"passage","lines":["목적 — 옛 물건이 생활에서 어떻게 쓰였는지 알리기","읽을 사람 — 학교 축제에서 모음집을 볼 저학년 동생들","대상 — 지게(민속 마을 체험에서 직접 져 본 적이 있음)","쓸 내용 — 생김새 · 짐을 지는 방법 · 오늘날 볼 수 있는 곳","구조 — (　　　　)"],"title":"해담이의 글 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_review_a#9','kor',5,1,'u4','','g5_1_kor_u4_review_a','unit_review','K5-1-u4-C38',2,'mc','auto','단비가 ㉱를 고친다면 어떻게 하는 것이 가장 알맞나요?',ARRAY['K5-1-u4-X38','K5-1-u4-X33']::text[],false,'{"seq":9,"concept":"K5-1-u4-C38","difficulty":2,"kind":"mc","stem":"단비가 ㉱를 고친다면 어떻게 하는 것이 가장 알맞나요?","options":[{"t":"㉱를 빼거나 두 신발의 다른 점을 하나 더 견주는 문장으로 바꾼다","correct":true},{"t":"㉱에 느낌을 더 많이 넣는다","mis":"K5-1-u4-X38"},{"t":"㉱를 글 맨 앞으로 옮긴다","mis":"K5-1-u4-X33"},{"t":"㉱는 그대로 두는 것이 좋다","mis":"K5-1-u4-X38"}],"explanation":["느낌은 중심이 아니에요.","옮겨도 느낌은 그대로예요.","대상의 특성을 담아요."],"asset":{"type":"passage","lines":["㉮ 짚신과 나막신은 옛날 사람들이 신던 신발로, 둘 다 자연에서","　 얻은 재료로 만들었다는 공통점이 있다.","㉯ 짚신은 볏짚을 꼬아 엮어 만들어 가볍고 발이 편하다. 반면","　 나막신은 통나무를 파서 만들어 무겁지만 물이 스미지 않는다.","㉰ 신는 날도 달랐다. 짚신은 마른 날에 신었고, 나막신은 굽이","　 높아서 비가 오거나 땅이 질척한 날에 신었다.","㉱ 나는 나막신이 또각또각 울리는 소리가 세상에서 제일 좋다."],"title":"단비의 글 초안 「짚신과 나막신」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_review_a#10','kor',5,1,'u4','','g5_1_kor_u4_review_a','unit_review','K5-1-u4-C21',2,'mc','auto','무진이의 글 「셋째」 문장을 중심 낱말로 줄인 것은 어느 것인가요?',ARRAY['K5-1-u4-X21','K5-1-u4-X17']::text[],false,'{"seq":10,"concept":"K5-1-u4-C21","difficulty":2,"kind":"mc","stem":"무진이의 글 「셋째」 문장을 중심 낱말로 줄인 것은 어느 것인가요?","options":[{"t":"판소리 · 이야기 살리기","correct":true},{"t":"셋째, 판소리를 하는 소리꾼은 부채를 펴고 접으며 이야기를 살린다","mis":"K5-1-u4-X21"},{"t":"소리꾼 · 펴고 · 접으며","mis":"K5-1-u4-X21"},{"t":"단옷날 선물","mis":"K5-1-u4-X17"}],"explanation":["그대로 옮겼어요.","중심이 되는 낱말이 빠졌어요.","한눈에 들어오게 줄였어요."],"asset":{"type":"passage","lines":["부채는 손으로 흔들어 바람을 일으키는 물건이다.","첫째, 더운 날 바람을 일으켜 땀을 식혀 준다.","둘째, 햇볕이 따가울 때 얼굴을 가리는 데 쓴다.","셋째, 판소리를 하는 소리꾼은 부채를 펴고 접으며 이야기를 살린다.","넷째, 옛날에는 단옷날 부채를 선물하며 여름을 잘 나기를 빌었다.","이처럼 부채는 바람을 일으키는 데에만 쓰인 것이 아니다."],"title":"무진이의 글 「부채의 여러 가지 쓰임」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_review_a#11','kor',5,1,'u4','','g5_1_kor_u4_review_a','unit_review','K5-1-u4-C18',2,'mc','auto','서우의 글에서 「먼저」와 「다음으로」의 내용을 바꾸면 어떻게 될까요?',ARRAY['K5-1-u4-X18','K5-1-u4-X12','K5-1-u4-X10']::text[],false,'{"seq":11,"concept":"K5-1-u4-C18","difficulty":2,"kind":"mc","stem":"서우의 글에서 「먼저」와 「다음으로」의 내용을 바꾸면 어떻게 될까요?","options":[{"t":"불리지 않은 콩을 맷돌에 넣게 되어 방법이 달라진다","correct":true},{"t":"아무 문제가 없다","mis":"K5-1-u4-X18"},{"t":"열거 구조가 된다","mis":"K5-1-u4-X12"},{"t":"비교와 대조 구조가 된다","mis":"K5-1-u4-X10"}],"explanation":["차례가 곧 방법이에요.","구조가 바뀌는 것이 아니에요.","단계를 바꾸면 방법이 어긋나요."],"asset":{"type":"passage","lines":["맷돌은 둥근 돌 두 짝을 포개어 곡식을 가는 도구이다.","먼저, 콩을 물에 담가 하룻밤 불린다.","다음으로, 위짝의 구멍에 불린 콩과 물을 조금씩 넣는다.","그 뒤, 손잡이를 잡고 위짝을 한 방향으로 천천히 돌린다.","마지막으로, 두 짝 사이로 흘러나온 콩물을 그릇에 받는다."],"title":"서우의 글 「맷돌로 콩 가는 차례」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_review_a#12','kor',5,1,'u4','','g5_1_kor_u4_review_a','unit_review','K5-1-u4-C26',2,'mc','auto','강솔이의 글을 가장 잘 요약한 것은 어느 것인가요?',ARRAY['K5-1-u4-X26','K5-1-u4-X24']::text[],false,'{"seq":12,"concept":"K5-1-u4-C26","difficulty":2,"kind":"mc","stem":"강솔이의 글을 가장 잘 요약한 것은 어느 것인가요?","options":[{"t":"도서관 책을 오래 읽으려면 깨끗한 손으로 넘기고, 책갈피를 쓰며, 제때 돌려주어야 한다.","correct":true},{"t":"책이 있다. 손이 있다. 책갈피도 나온다.","mis":"K5-1-u4-X26"},{"t":"손에 묻은 기름과 먼지는 책장을 누렇게 만든다.","mis":"K5-1-u4-X26"},{"t":"첫째, 둘째, 셋째가 있다.","mis":"K5-1-u4-X24"}],"explanation":["낱말을 늘어놓았어요.","뒷받침 내용이에요.","중심 문장을 이었어요."],"asset":{"type":"passage","lines":["㉮ 학교 도서관 책은 여러 사람이 돌려 가며 읽는다. 책을 오래","　 읽으려면 어떻게 해야 할지 알아보자.","㉯ 첫째, 깨끗한 손으로 책장을 넘긴다. 손에 묻은 기름과 먼지는","　 책장을 누렇게 만든다. 둘째, 읽던 곳은 책장을 접지 말고","　 책갈피를 끼운다. 셋째, 다 읽은 책은 제때 돌려준다.","㉰ 이처럼 책을 아끼는 작은 습관은 다음에 읽을 친구를 위한","　 배려이다. 오늘 빌린 책부터 실천해 보자."],"title":"강솔이의 학급 신문 글 「도서관 책을 오래 읽는 방법」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_review_a#13','kor',5,1,'u4','','g5_1_kor_u4_review_a','unit_review','K5-1-u4-C31',2,'mc','auto','해담이가 읽을 사람을 생각해 더하면 좋을 것은 어느 것인가요?',ARRAY['K5-1-u4-X31']::text[],false,'{"seq":13,"concept":"K5-1-u4-C31","difficulty":2,"kind":"mc","stem":"해담이가 읽을 사람을 생각해 더하면 좋을 것은 어느 것인가요?","options":[{"t":"「멜빵」 같은 말을 쉽게 풀고 지게 그림을 함께 넣는다","correct":true},{"t":"어려운 말을 더 많이 쓴다","mis":"K5-1-u4-X31"},{"t":"설명을 다 줄여 한 줄만 쓴다","mis":"K5-1-u4-X31"},{"t":"어른이 읽는 글과 똑같이 쓴다","mis":"K5-1-u4-X31"}],"explanation":["동생들이 읽기 어려워요.","너무 줄이면 알 수 없어요.","저학년 동생들을 생각해요."],"asset":{"type":"passage","lines":["목적 — 옛 물건이 생활에서 어떻게 쓰였는지 알리기","읽을 사람 — 학교 축제에서 모음집을 볼 저학년 동생들","대상 — 지게(민속 마을 체험에서 직접 져 본 적이 있음)","쓸 내용 — 생김새 · 짐을 지는 방법 · 오늘날 볼 수 있는 곳","구조 — (　　　　)"],"title":"해담이의 글 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_review_a#14','kor',5,1,'u4','','g5_1_kor_u4_review_a','unit_review','K5-1-u4-C43',2,'mc','auto','모음집 회의에서 무진이의 말에 대한 생각으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u4-X43']::text[],false,'{"seq":14,"concept":"K5-1-u4-C43","difficulty":2,"kind":"mc","stem":"모음집 회의에서 무진이의 말에 대한 생각으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"구조는 대상에 맞게 저마다 골라도 한 권이 될 수 있다","correct":true},{"t":"무진이 말대로 모두 비교와 대조 구조로 써야 한다","mis":"K5-1-u4-X43"},{"t":"구조가 다르면 모음집을 만들 수 없다","mis":"K5-1-u4-X43"},{"t":"대상도 모두 같아야 한다","mis":"K5-1-u4-X43"}],"explanation":["구조까지 맞출 필요는 없어요.","겉모습을 맞추면 돼요.","대상은 저마다 골라요."],"asset":{"type":"speech","turns":[{"who":"해담","text":"우리 반 모음집의 큰 주제는 「옛 물건 이야기」로 정했어. 이제 무엇을 함께 정할까?"},{"who":"무진","text":"모두 똑같이 비교와 대조 구조로 쓰자. 그래야 한 권처럼 보여."},{"who":"단비","text":"구조는 각자 대상에 맞게 고르고, 제목 다는 방식이랑 분량을 맞추자."},{"who":"서우","text":"머리말에는 왜 옛 물건을 모았는지 쓰고, 글 제목과 쪽수로 차례도 만들자."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_review_a#15','kor',5,1,'u4','','g5_1_kor_u4_review_a','unit_review','K5-1-u4-C39',2,'mc','auto','「나」의 댓글이 도움이 되는 까닭은 무엇인가요?',ARRAY['K5-1-u4-X39']::text[],false,'{"seq":15,"concept":"K5-1-u4-C39","difficulty":2,"kind":"mc","stem":"「나」의 댓글이 도움이 되는 까닭은 무엇인가요?","options":[{"t":"좋았던 점과 보탤 점을 근거와 함께 말했다","correct":true},{"t":"칭찬만 했다","mis":"K5-1-u4-X39"},{"t":"지적만 했다","mis":"K5-1-u4-X39"},{"t":"자기 글과 견주었다","mis":"K5-1-u4-X39"}],"explanation":["보탤 점도 있어요.","좋았던 점도 있어요.","두 가지를 함께 말했어요."],"asset":{"type":"speech","turns":[{"who":"가","text":"잘 썼네."},{"who":"나","text":"비교와 대조 구조라 두 신발이 한눈에 견주어졌어. 볏짚이 무엇인지 짧게 풀어 주면 동생들도 읽기 쉽겠어."},{"who":"다","text":"내 글이 더 재미있는 것 같아."},{"who":"라","text":"㉱는 빼. 그냥 별로야."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_review_a#16','kor',5,1,'u4','','g5_1_kor_u4_review_a','unit_review','K5-1-u4-C6',2,'mc','auto','글의 구조를 아는 것이 중요한 까닭이 아닌 것은 어느 것인가요?',ARRAY['K5-1-u4-X06']::text[],false,'{"seq":16,"concept":"K5-1-u4-C6","difficulty":2,"kind":"mc","stem":"글의 구조를 아는 것이 중요한 까닭이 아닌 것은 어느 것인가요?","options":[{"t":"글을 읽지 않아도 내용을 알 수 있다","correct":true},{"t":"글 전체의 내용을 잘 이해할 수 있다","mis":"K5-1-u4-X06"},{"t":"중심 내용을 쉽게 간추릴 수 있다","mis":"K5-1-u4-X06"},{"t":"쓸 내용을 짜임새 있게 정리할 수 있다","mis":"K5-1-u4-X06"}],"explanation":["까닭이 맞아요.","까닭이 맞아요.","글은 읽어야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_review_a#17','kor',5,1,'u4','','g5_1_kor_u4_review_a','unit_review','K5-1-u4-C13',3,'mc','auto','「부채」를 대상으로 순서 구조의 글을 쓴다면 무엇을 말하는 글이 알맞을까요?',ARRAY['K5-1-u4-X13','K5-1-u4-X38']::text[],false,'{"seq":17,"concept":"K5-1-u4-C13","difficulty":3,"kind":"mc","stem":"「부채」를 대상으로 순서 구조의 글을 쓴다면 무엇을 말하는 글이 알맞을까요?","options":[{"t":"부채를 만드는 과정","correct":true},{"t":"부채의 여러 가지 쓰임","mis":"K5-1-u4-X13"},{"t":"부채와 선풍기의 같은 점과 다른 점","mis":"K5-1-u4-X13"},{"t":"부채를 받은 날의 기분","mis":"K5-1-u4-X38"}],"explanation":["그것은 열거예요.","그것은 비교와 대조예요.","과정은 차례가 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_review_a#18','kor',5,1,'u4','','g5_1_kor_u4_review_a','unit_review','K5-1-u4-C12',3,'mc','auto','「어떤 글 ㉠」은 어떤 구조이고, 그렇게 볼 수 있는 까닭은 무엇인가요?',ARRAY['K5-1-u4-X12','K5-1-u4-X10','K5-1-u4-X08']::text[],false,'{"seq":18,"concept":"K5-1-u4-C12","difficulty":3,"kind":"mc","stem":"「어떤 글 ㉠」은 어떤 구조이고, 그렇게 볼 수 있는 까닭은 무엇인가요?","options":[{"t":"순서 구조 — 첫째와 둘째를 바꾸면 차례가 어긋난다","correct":true},{"t":"열거 구조 — 첫째 · 둘째 · 셋째가 있기 때문이다","mis":"K5-1-u4-X12"},{"t":"비교와 대조 구조 — 두 가지를 견주었기 때문이다","mis":"K5-1-u4-X10"},{"t":"열거 구조 — 바꾸어도 글이 그대로이기 때문이다","mis":"K5-1-u4-X08"}],"explanation":["말만 보면 안 돼요.","견주는 내용이 없어요.","싹을 틔워야 모판에 뿌려요."],"asset":{"type":"passage","lines":["첫째, 볍씨를 물에 담가 싹을 틔운다.","둘째, 싹이 튼 볍씨를 모판에 뿌려 기른다.","셋째, 자란 모를 논에 옮겨 심는다."],"title":"어떤 글 ㉠"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_review_a#19','kor',5,1,'u4','','g5_1_kor_u4_review_a','unit_review','K5-1-u4-C36',3,'mc','auto','단비가 짚신에 대해 모은 자료 가운데 가장 믿을 수 있는 것은 어느 것인가요?',ARRAY['K5-1-u4-X36']::text[],false,'{"seq":19,"concept":"K5-1-u4-C36","difficulty":3,"kind":"mc","stem":"단비가 짚신에 대해 모은 자료 가운데 가장 믿을 수 있는 것은 어느 것인가요?","options":[{"t":"만든 곳과 올린 때가 밝혀진 박물관 누리집의 짚신 설명","correct":true},{"t":"누가 썼는지 모르는 게시글","mis":"K5-1-u4-X36"},{"t":"친구가 어디서 들었다는 이야기","mis":"K5-1-u4-X36"},{"t":"사진이 예쁘지만 출처가 없는 글","mis":"K5-1-u4-X36"}],"explanation":["누가 썼는지 몰라요.","확인하기 어려워요.","믿을 수 있고 최신인지 알 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_review_a#20','kor',5,1,'u4','','g5_1_kor_u4_review_a','unit_review','K5-1-u4-C25',3,'mc','auto','강솔이의 글 ㉰가 하는 일로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u4-X25','K5-1-u4-X10']::text[],false,'{"seq":20,"concept":"K5-1-u4-C25","difficulty":3,"kind":"mc","stem":"강솔이의 글 ㉰가 하는 일로 알맞은 것은 어느 것인가요?","options":[{"t":"작은 습관이 다음 친구를 위한 배려라며 실천을 권한다","correct":true},{"t":"대상을 처음 소개한다","mis":"K5-1-u4-X25"},{"t":"세 방법을 하나씩 늘어놓는다","mis":"K5-1-u4-X25"},{"t":"도서관과 서점을 견준다","mis":"K5-1-u4-X10"}],"explanation":["그것은 처음이에요.","그것은 가운데예요.","끝은 묶고 권해요."],"asset":{"type":"passage","lines":["㉮ 학교 도서관 책은 여러 사람이 돌려 가며 읽는다. 책을 오래","　 읽으려면 어떻게 해야 할지 알아보자.","㉯ 첫째, 깨끗한 손으로 책장을 넘긴다. 손에 묻은 기름과 먼지는","　 책장을 누렇게 만든다. 둘째, 읽던 곳은 책장을 접지 말고","　 책갈피를 끼운다. 셋째, 다 읽은 책은 제때 돌려준다.","㉰ 이처럼 책을 아끼는 작은 습관은 다음에 읽을 친구를 위한","　 배려이다. 오늘 빌린 책부터 실천해 보자."],"title":"강솔이의 학급 신문 글 「도서관 책을 오래 읽는 방법」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_review_a#21','kor',5,1,'u4','','g5_1_kor_u4_review_a','unit_review','K5-1-u4-C48',3,'mc','auto','바르게 쓴 낱말은 어느 것인가요?',ARRAY['K5-1-u4-X48','K5-1-u4-X49']::text[],false,'{"seq":21,"concept":"K5-1-u4-C48","difficulty":3,"kind":"mc","stem":"바르게 쓴 낱말은 어느 것인가요?","options":[{"t":"샛말갛다","correct":true},{"t":"샛파랗다","mis":"K5-1-u4-X48"},{"t":"새퍼렇다","mis":"K5-1-u4-X49"},{"t":"싯노랗다","mis":"K5-1-u4-X49"}],"explanation":["첫소리 ㅍ 앞은 새-예요.","모음 ㅓ 앞은 시-예요.","ㅁ · ㅏ라 샛말갛다가 맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_review_a#22','kor',5,1,'u4','','g5_1_kor_u4_review_a','unit_review','K5-1-u4-C30',3,'mc','auto','「옛 물건 이야기」 모음집에 서우가 고를 대상으로 가장 알맞지 않은 것은 어느 것인가요?',ARRAY['K5-1-u4-X30']::text[],false,'{"seq":22,"concept":"K5-1-u4-C30","difficulty":3,"kind":"mc","stem":"「옛 물건 이야기」 모음집에 서우가 고를 대상으로 가장 알맞지 않은 것은 어느 것인가요?","options":[{"t":"아직 아무도 본 적 없는 미래의 물건","correct":true},{"t":"할머니 댁에서 써 본 맷돌","mis":"K5-1-u4-X30"},{"t":"박물관에서 본 짚신","mis":"K5-1-u4-X30"},{"t":"책에서 자료를 찾을 수 있는 다듬잇돌","mis":"K5-1-u4-X30"}],"explanation":["잘 아는 대상이에요.","알릴 값이 있어요.","옛 물건도 아니고 자료도 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_review_a#23','kor',5,1,'u4','','g5_1_kor_u4_review_a','unit_review','K5-1-u4-C19',4,'essay','teacher','단비의 글로 비교와 대조 정리표를 만드세요. 공통점 한 가지와 차이점 두 항목을 같은 항목끼리 마주 놓아 중심 낱말로 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K5-1-u4-C19","difficulty":4,"kind":"essay","stem":"단비의 글로 비교와 대조 정리표를 만드세요. 공통점 한 가지와 차이점 두 항목을 같은 항목끼리 마주 놓아 중심 낱말로 쓰세요.","answer_guide":{"answer":"예: 공통점 — 자연에서 얻은 재료로 만든 옛 신발. 재료 — 짚신: 볏짚을 꼬아 엮음 · 가벼움 / 나막신: 통나무를 팜 · 무거우나 물이 스미지 않음. 신는 날 — 짚신: 마른 날 / 나막신: 비 오는 날 · 질척한 날.","scoring_points":["공통점을 썼는가","차이점 두 항목을 같은 항목끼리 마주 놓았는가","중심 낱말로 짧게 썼는가"]},"explanation":["㉮를 봐요.","재료와 신는 날을 견줘요.","문장 대신 낱말로 써요."],"asset":{"type":"passage","lines":["㉮ 짚신과 나막신은 옛날 사람들이 신던 신발로, 둘 다 자연에서","　 얻은 재료로 만들었다는 공통점이 있다.","㉯ 짚신은 볏짚을 꼬아 엮어 만들어 가볍고 발이 편하다. 반면","　 나막신은 통나무를 파서 만들어 무겁지만 물이 스미지 않는다.","㉰ 신는 날도 달랐다. 짚신은 마른 날에 신었고, 나막신은 굽이","　 높아서 비가 오거나 땅이 질척한 날에 신었다.","㉱ 나는 나막신이 또각또각 울리는 소리가 세상에서 제일 좋다."],"title":"단비의 글 초안 「짚신과 나막신」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_review_a#24','kor',5,1,'u4','','g5_1_kor_u4_review_a','unit_review','K5-1-u4-C29',4,'essay','teacher','해담이의 계획에서 (　　　)에 알맞은 구조를 쓰고 그 까닭을 쓴 뒤, 읽을 사람인 저학년 동생들을 위해 글을 어떻게 쓰면 좋을지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K5-1-u4-C29","difficulty":4,"kind":"essay","stem":"해담이의 계획에서 (　　　)에 알맞은 구조를 쓰고 그 까닭을 쓴 뒤, 읽을 사람인 저학년 동생들을 위해 글을 어떻게 쓰면 좋을지 쓰세요.","answer_guide":{"answer":"예: 구조 — 열거 구조. 생김새 · 짐을 지는 방법 · 오늘날 볼 수 있는 곳처럼 지게의 여러 면을 항목별로 소개하기 때문이다. 동생들을 위해 멜빵 같은 어려운 말은 쉬운 말로 풀고, 지게를 진 모습을 그림으로 함께 넣는다.","scoring_points":["알맞은 구조를 썼는가","구조를 고른 까닭을 썼는가","읽을 사람을 생각한 쓰기 방법을 썼는가"]},"explanation":["쓸 내용을 봐요.","항목인가요, 단계인가요?","동생들이 어려워할 것은?"],"asset":{"type":"passage","lines":["목적 — 옛 물건이 생활에서 어떻게 쓰였는지 알리기","읽을 사람 — 학교 축제에서 모음집을 볼 저학년 동생들","대상 — 지게(민속 마을 체험에서 직접 져 본 적이 있음)","쓸 내용 — 생김새 · 짐을 지는 방법 · 오늘날 볼 수 있는 곳","구조 — (　　　　)"],"title":"해담이의 글 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_review_a#25','kor',5,1,'u4','','g5_1_kor_u4_review_a','unit_review','K5-1-u4-C13',4,'essay','teacher','「부채」 하나를 대상으로 열거 · 순서 · 비교와 대조 구조의 글을 쓴다면 각각 무엇을 말하는 글이 될지 쓰고, 구조를 정하는 것이 무엇인지 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K5-1-u4-C13","difficulty":4,"kind":"essay","stem":"「부채」 하나를 대상으로 열거 · 순서 · 비교와 대조 구조의 글을 쓴다면 각각 무엇을 말하는 글이 될지 쓰고, 구조를 정하는 것이 무엇인지 쓰세요.","answer_guide":{"answer":"예: 열거 구조라면 부채의 여러 가지 쓰임을 소개한다. 순서 구조라면 부채를 만드는 과정을 차례대로 알려 준다. 비교와 대조 구조라면 쥘부채와 둥근 부채의 같은 점과 다른 점을 견준다. 같은 대상이라도 무엇을 말하려는지가 구조를 정한다.","scoring_points":["열거로 쓸 내용을 썼는가","순서와 비교와 대조로 쓸 내용을 썼는가","구조를 정하는 것이 말하려는 내용이라고 썼는가"]},"explanation":["여러 쓰임은?","만드는 과정은? 견주기는?","대상보다 말하려는 것이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_review_b#1','kor',5,1,'u4','','g5_1_kor_u4_review_b','unit_review','K5-1-u4-C48',1,'mc','auto','「노랗다」 앞에 붙는 말로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u4-X48','K5-1-u4-X49']::text[],false,'{"seq":1,"concept":"K5-1-u4-C48","difficulty":1,"kind":"mc","stem":"「노랗다」 앞에 붙는 말로 알맞은 것은 어느 것인가요?","options":[{"t":"샛-","correct":true},{"t":"새-","mis":"K5-1-u4-X48"},{"t":"싯-","mis":"K5-1-u4-X49"},{"t":"시-","mis":"K5-1-u4-X48"}],"explanation":["첫소리가 ㄴ이에요.","모음이 ㅗ예요.","첫소리 ㄴ, 모음 ㅗ라 샛-이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_review_b#2','kor',5,1,'u4','','g5_1_kor_u4_review_b','unit_review','K5-1-u4-C49',1,'mc','auto','「누렇다」 앞에 붙는 말로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u4-X49','K5-1-u4-X48']::text[],false,'{"seq":2,"concept":"K5-1-u4-C49","difficulty":1,"kind":"mc","stem":"「누렇다」 앞에 붙는 말로 알맞은 것은 어느 것인가요?","options":[{"t":"싯-","correct":true},{"t":"샛-","mis":"K5-1-u4-X49"},{"t":"시-","mis":"K5-1-u4-X48"},{"t":"새-","mis":"K5-1-u4-X48"}],"explanation":["모음이 ㅜ예요.","첫소리가 ㄴ이에요.","첫소리 ㄴ, 모음 ㅜ라 싯-이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_review_b#3','kor',5,1,'u4','','g5_1_kor_u4_review_b','unit_review','K5-1-u4-C47',1,'mc','auto','「알맞은 낱말 고르기」의 ㉮에 알맞은 말은 어느 것인가요?',ARRAY['K5-1-u4-X49','K5-1-u4-X48','K5-1-u4-X47']::text[],false,'{"seq":3,"concept":"K5-1-u4-C47","difficulty":1,"kind":"mc","stem":"「알맞은 낱말 고르기」의 ㉮에 알맞은 말은 어느 것인가요?","options":[{"t":"새까맣다","correct":true},{"t":"시까맣다","mis":"K5-1-u4-X49"},{"t":"샛까맣다","mis":"K5-1-u4-X48"},{"t":"싯까맣다","mis":"K5-1-u4-X47"}],"explanation":["모음이 ㅏ예요.","첫소리가 된소리예요.","된소리 ㄲ · 모음 ㅏ라 새까맣다예요."],"asset":{"type":"passage","lines":["㉮ 별 하나 없는 밤하늘이 (새까맣다 / 시까맣다).","㉯ 갓 깬 병아리 털이 (샛노랗다 / 새노랗다).","㉰ 큰비가 온 뒤 흙탕물이 (싯누렇게 / 시누렇게) 흘렀다.","㉱ 눈 덮인 마당이 (새하얗다 / 샛하얗다)."],"title":"알맞은 낱말 고르기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_review_b#4','kor',5,1,'u4','','g5_1_kor_u4_review_b','unit_review','K5-1-u4-C11',1,'mc','auto','단비의 글 ㉯에서 차이점을 드러내는 말은 어느 것인가요?',ARRAY['K5-1-u4-X11']::text[],false,'{"seq":4,"concept":"K5-1-u4-C11","difficulty":1,"kind":"mc","stem":"단비의 글 ㉯에서 차이점을 드러내는 말은 어느 것인가요?","options":[{"t":"반면","correct":true},{"t":"둘 다","mis":"K5-1-u4-X11"},{"t":"공통점","mis":"K5-1-u4-X11"},{"t":"먼저","mis":"K5-1-u4-X11"}],"explanation":["같은 점을 말해요.","같은 점을 말해요.","「반면」이 다른 점을 이어 줘요."],"asset":{"type":"passage","lines":["㉮ 짚신과 나막신은 옛날 사람들이 신던 신발로, 둘 다 자연에서","　 얻은 재료로 만들었다는 공통점이 있다.","㉯ 짚신은 볏짚을 꼬아 엮어 만들어 가볍고 발이 편하다. 반면","　 나막신은 통나무를 파서 만들어 무겁지만 물이 스미지 않는다.","㉰ 신는 날도 달랐다. 짚신은 마른 날에 신었고, 나막신은 굽이","　 높아서 비가 오거나 땅이 질척한 날에 신었다.","㉱ 나는 나막신이 또각또각 울리는 소리가 세상에서 제일 좋다."],"title":"단비의 글 초안 「짚신과 나막신」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_review_b#5','kor',5,1,'u4','','g5_1_kor_u4_review_b','unit_review','K5-1-u4-C11',1,'mc','auto','무진이의 글에서 구조를 짐작하게 하는 말은 어느 것인가요?',ARRAY['K5-1-u4-X11']::text[],false,'{"seq":5,"concept":"K5-1-u4-C11","difficulty":1,"kind":"mc","stem":"무진이의 글에서 구조를 짐작하게 하는 말은 어느 것인가요?","options":[{"t":"첫째 · 둘째 · 셋째 · 넷째","correct":true},{"t":"먼저 · 다음으로","mis":"K5-1-u4-X11"},{"t":"반면 · 다르게","mis":"K5-1-u4-X11"},{"t":"모두 · 공통점","mis":"K5-1-u4-X11"}],"explanation":["글에 없는 말이에요.","글에 없는 말이에요.","항목을 여는 말이 있어요."],"asset":{"type":"passage","lines":["부채는 손으로 흔들어 바람을 일으키는 물건이다.","첫째, 더운 날 바람을 일으켜 땀을 식혀 준다.","둘째, 햇볕이 따가울 때 얼굴을 가리는 데 쓴다.","셋째, 판소리를 하는 소리꾼은 부채를 펴고 접으며 이야기를 살린다.","넷째, 옛날에는 단옷날 부채를 선물하며 여름을 잘 나기를 빌었다.","이처럼 부채는 바람을 일으키는 데에만 쓰인 것이 아니다."],"title":"무진이의 글 「부채의 여러 가지 쓰임」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_review_b#6','kor',5,1,'u4','','g5_1_kor_u4_review_b','unit_review','K5-1-u4-C18',1,'mc','auto','서우의 글에서 「그 뒤」에 하는 일은 어느 것인가요?',ARRAY['K5-1-u4-X18','K5-1-u4-X17']::text[],false,'{"seq":6,"concept":"K5-1-u4-C18","difficulty":1,"kind":"mc","stem":"서우의 글에서 「그 뒤」에 하는 일은 어느 것인가요?","options":[{"t":"손잡이를 잡고 위짝을 천천히 돌린다","correct":true},{"t":"콩을 물에 담가 불린다","mis":"K5-1-u4-X18"},{"t":"흘러나온 콩물을 그릇에 받는다","mis":"K5-1-u4-X18"},{"t":"맷돌은 돌 두 짝을 포갠 도구이다","mis":"K5-1-u4-X17"}],"explanation":["그것은 「먼저」예요.","그것은 「마지막으로」예요.","넣은 다음 돌려요."],"asset":{"type":"passage","lines":["맷돌은 둥근 돌 두 짝을 포개어 곡식을 가는 도구이다.","먼저, 콩을 물에 담가 하룻밤 불린다.","다음으로, 위짝의 구멍에 불린 콩과 물을 조금씩 넣는다.","그 뒤, 손잡이를 잡고 위짝을 한 방향으로 천천히 돌린다.","마지막으로, 두 짝 사이로 흘러나온 콩물을 그릇에 받는다."],"title":"서우의 글 「맷돌로 콩 가는 차례」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_review_b#7','kor',5,1,'u4','','g5_1_kor_u4_review_b','unit_review','K5-1-u4-C25',1,'mc','auto','강솔이의 글에서 가운데 부분은 어느 것인가요?',ARRAY['K5-1-u4-X25']::text[],false,'{"seq":7,"concept":"K5-1-u4-C25","difficulty":1,"kind":"mc","stem":"강솔이의 글에서 가운데 부분은 어느 것인가요?","options":[{"t":"㉯","correct":true},{"t":"㉮","mis":"K5-1-u4-X25"},{"t":"㉰","mis":"K5-1-u4-X25"},{"t":"㉮ · ㉰","mis":"K5-1-u4-X25"}],"explanation":["처음이에요.","끝이에요.","세 방법이 가운데예요."],"asset":{"type":"passage","lines":["㉮ 학교 도서관 책은 여러 사람이 돌려 가며 읽는다. 책을 오래","　 읽으려면 어떻게 해야 할지 알아보자.","㉯ 첫째, 깨끗한 손으로 책장을 넘긴다. 손에 묻은 기름과 먼지는","　 책장을 누렇게 만든다. 둘째, 읽던 곳은 책장을 접지 말고","　 책갈피를 끼운다. 셋째, 다 읽은 책은 제때 돌려준다.","㉰ 이처럼 책을 아끼는 작은 습관은 다음에 읽을 친구를 위한","　 배려이다. 오늘 빌린 책부터 실천해 보자."],"title":"강솔이의 학급 신문 글 「도서관 책을 오래 읽는 방법」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_review_b#8','kor',5,1,'u4','','g5_1_kor_u4_review_b','unit_review','K5-1-u4-C8',1,'mc','auto','해담이의 계획에서 (　　　)에 들어갈 구조로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u4-X13','K5-1-u4-X29']::text[],false,'{"seq":8,"concept":"K5-1-u4-C8","difficulty":1,"kind":"mc","stem":"해담이의 계획에서 (　　　)에 들어갈 구조로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"열거 구조","correct":true},{"t":"순서 구조","mis":"K5-1-u4-X13"},{"t":"비교와 대조 구조","mis":"K5-1-u4-X13"},{"t":"구조는 정하지 않아도 된다","mis":"K5-1-u4-X29"}],"explanation":["쓸 내용이 단계가 아니에요.","견주는 대상이 없어요.","여러 면을 항목별로 소개해요."],"asset":{"type":"passage","lines":["목적 — 옛 물건이 생활에서 어떻게 쓰였는지 알리기","읽을 사람 — 학교 축제에서 모음집을 볼 저학년 동생들","대상 — 지게(민속 마을 체험에서 직접 져 본 적이 있음)","쓸 내용 — 생김새 · 짐을 지는 방법 · 오늘날 볼 수 있는 곳","구조 — (　　　　)"],"title":"해담이의 글 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_review_b#9','kor',5,1,'u4','','g5_1_kor_u4_review_b','unit_review','K5-1-u4-C19',2,'mc','auto','단비가 차이점을 정리할 때 바르게 마주 놓은 것은 어느 것인가요?',ARRAY['K5-1-u4-X19']::text[],false,'{"seq":9,"concept":"K5-1-u4-C19","difficulty":2,"kind":"mc","stem":"단비가 차이점을 정리할 때 바르게 마주 놓은 것은 어느 것인가요?","options":[{"t":"재료 — 짚신: 볏짚 · 나막신: 통나무","correct":true},{"t":"재료 — 짚신: 볏짚 · 나막신: 비 오는 날","mis":"K5-1-u4-X19"},{"t":"신는 날 — 짚신: 마른 날 · 나막신: 통나무","mis":"K5-1-u4-X19"},{"t":"무게 — 짚신: 가볍다 · 나막신: 비 오는 날","mis":"K5-1-u4-X19"}],"explanation":["재료와 신는 날을 섞었어요.","신는 날과 재료를 섞었어요.","같은 항목끼리 마주 놓았어요."],"asset":{"type":"passage","lines":["㉮ 짚신과 나막신은 옛날 사람들이 신던 신발로, 둘 다 자연에서","　 얻은 재료로 만들었다는 공통점이 있다.","㉯ 짚신은 볏짚을 꼬아 엮어 만들어 가볍고 발이 편하다. 반면","　 나막신은 통나무를 파서 만들어 무겁지만 물이 스미지 않는다.","㉰ 신는 날도 달랐다. 짚신은 마른 날에 신었고, 나막신은 굽이","　 높아서 비가 오거나 땅이 질척한 날에 신었다.","㉱ 나는 나막신이 또각또각 울리는 소리가 세상에서 제일 좋다."],"title":"단비의 글 초안 「짚신과 나막신」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_review_b#10','kor',5,1,'u4','','g5_1_kor_u4_review_b','unit_review','K5-1-u4-C12',2,'mc','auto','무진이의 글에서 첫째와 둘째의 내용을 서로 바꾸어 보면 무엇을 알 수 있나요?',ARRAY['K5-1-u4-X12','K5-1-u4-X10']::text[],false,'{"seq":10,"concept":"K5-1-u4-C12","difficulty":2,"kind":"mc","stem":"무진이의 글에서 첫째와 둘째의 내용을 서로 바꾸어 보면 무엇을 알 수 있나요?","options":[{"t":"글이 그대로이므로 열거 구조임을 확인할 수 있다","correct":true},{"t":"글이 이상해지므로 순서 구조이다","mis":"K5-1-u4-X12"},{"t":"「첫째」가 있으니 바꾸어 볼 필요가 없다","mis":"K5-1-u4-X12"},{"t":"바꾸면 비교와 대조 구조가 된다","mis":"K5-1-u4-X10"}],"explanation":["바꾸어도 글이 그대로예요.","말만 보고 정하지 않아요.","바꾸어도 되면 열거예요."],"asset":{"type":"passage","lines":["부채는 손으로 흔들어 바람을 일으키는 물건이다.","첫째, 더운 날 바람을 일으켜 땀을 식혀 준다.","둘째, 햇볕이 따가울 때 얼굴을 가리는 데 쓴다.","셋째, 판소리를 하는 소리꾼은 부채를 펴고 접으며 이야기를 살린다.","넷째, 옛날에는 단옷날 부채를 선물하며 여름을 잘 나기를 빌었다.","이처럼 부채는 바람을 일으키는 데에만 쓰인 것이 아니다."],"title":"무진이의 글 「부채의 여러 가지 쓰임」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_review_b#11','kor',5,1,'u4','','g5_1_kor_u4_review_b','unit_review','K5-1-u4-C12',2,'mc','auto','서우가 「먼저 · 다음으로」 대신 「첫째 · 둘째」로 고쳐 쓴다면 이 글은 어떤 구조인가요?',ARRAY['K5-1-u4-X12','K5-1-u4-X03','K5-1-u4-X10']::text[],false,'{"seq":11,"concept":"K5-1-u4-C12","difficulty":2,"kind":"mc","stem":"서우가 「먼저 · 다음으로」 대신 「첫째 · 둘째」로 고쳐 쓴다면 이 글은 어떤 구조인가요?","options":[{"t":"그래도 순서 구조이다 — 차례를 바꾸면 방법이 달라지기 때문이다","correct":true},{"t":"열거 구조로 바뀐다","mis":"K5-1-u4-X12"},{"t":"구조가 없어진다","mis":"K5-1-u4-X03"},{"t":"비교와 대조 구조가 된다","mis":"K5-1-u4-X10"}],"explanation":["말이 바뀌어도 내용은 단계예요.","구조는 그대로 있어요.","내용의 성격이 구조를 정해요."],"asset":{"type":"passage","lines":["맷돌은 둥근 돌 두 짝을 포개어 곡식을 가는 도구이다.","먼저, 콩을 물에 담가 하룻밤 불린다.","다음으로, 위짝의 구멍에 불린 콩과 물을 조금씩 넣는다.","그 뒤, 손잡이를 잡고 위짝을 한 방향으로 천천히 돌린다.","마지막으로, 두 짝 사이로 흘러나온 콩물을 그릇에 받는다."],"title":"서우의 글 「맷돌로 콩 가는 차례」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_review_b#12','kor',5,1,'u4','','g5_1_kor_u4_review_b','unit_review','K5-1-u4-C26',2,'mc','auto','강솔이의 글을 요약할 때 줄여도 되는 내용은 어느 것인가요?',ARRAY['K5-1-u4-X26']::text[],false,'{"seq":12,"concept":"K5-1-u4-C26","difficulty":2,"kind":"mc","stem":"강솔이의 글을 요약할 때 줄여도 되는 내용은 어느 것인가요?","options":[{"t":"손에 묻은 기름과 먼지가 책장을 누렇게 만든다는 까닭","correct":true},{"t":"깨끗한 손으로 책장을 넘긴다","mis":"K5-1-u4-X26"},{"t":"읽던 곳에 책갈피를 끼운다","mis":"K5-1-u4-X26"},{"t":"다 읽은 책은 제때 돌려준다","mis":"K5-1-u4-X26"}],"explanation":["중심 내용이에요.","중심 내용이에요.","뒷받침하는 까닭은 줄여요."],"asset":{"type":"passage","lines":["㉮ 학교 도서관 책은 여러 사람이 돌려 가며 읽는다. 책을 오래","　 읽으려면 어떻게 해야 할지 알아보자.","㉯ 첫째, 깨끗한 손으로 책장을 넘긴다. 손에 묻은 기름과 먼지는","　 책장을 누렇게 만든다. 둘째, 읽던 곳은 책장을 접지 말고","　 책갈피를 끼운다. 셋째, 다 읽은 책은 제때 돌려준다.","㉰ 이처럼 책을 아끼는 작은 습관은 다음에 읽을 친구를 위한","　 배려이다. 오늘 빌린 책부터 실천해 보자."],"title":"강솔이의 학급 신문 글 「도서관 책을 오래 읽는 방법」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_review_b#13','kor',5,1,'u4','','g5_1_kor_u4_review_b','unit_review','K5-1-u4-C33',2,'mc','auto','해담이가 쓸 내용을 배열한 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u4-X33']::text[],false,'{"seq":13,"concept":"K5-1-u4-C33","difficulty":2,"kind":"mc","stem":"해담이가 쓸 내용을 배열한 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"생김새 → 짐을 지는 방법 → 오늘날 볼 수 있는 곳","correct":true},{"t":"떠오른 차례대로 아무렇게나","mis":"K5-1-u4-X33"},{"t":"오늘날 볼 수 있는 곳 → 체험 소감 → 생김새","mis":"K5-1-u4-X33"},{"t":"짐을 지는 방법 → 체험 소감 → 생김새","mis":"K5-1-u4-X33"}],"explanation":["떠오른 차례는 흩어져요.","무엇인지 모르는데 장소부터 나와요.","무엇인지부터 알려 줘요."],"asset":{"type":"passage","lines":["목적 — 옛 물건이 생활에서 어떻게 쓰였는지 알리기","읽을 사람 — 학교 축제에서 모음집을 볼 저학년 동생들","대상 — 지게(민속 마을 체험에서 직접 져 본 적이 있음)","쓸 내용 — 생김새 · 짐을 지는 방법 · 오늘날 볼 수 있는 곳","구조 — (　　　　)"],"title":"해담이의 글 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_review_b#14','kor',5,1,'u4','','g5_1_kor_u4_review_b','unit_review','K5-1-u4-C44',2,'mc','auto','해담네 반이 미리 함께 정할 것으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u4-X43','K5-1-u4-X44']::text[],false,'{"seq":14,"concept":"K5-1-u4-C44","difficulty":2,"kind":"mc","stem":"해담네 반이 미리 함께 정할 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"제목 다는 방식 · 분량 · 사진을 넣을지","correct":true},{"t":"모두 같은 구조","mis":"K5-1-u4-X43"},{"t":"모두 같은 대상","mis":"K5-1-u4-X43"},{"t":"정할 것이 없다","mis":"K5-1-u4-X44"}],"explanation":["구조는 저마다예요.","대상은 각자 골라요.","겉모습을 맞춰요."],"asset":{"type":"speech","turns":[{"who":"해담","text":"우리 반 모음집의 큰 주제는 「옛 물건 이야기」로 정했어. 이제 무엇을 함께 정할까?"},{"who":"무진","text":"모두 똑같이 비교와 대조 구조로 쓰자. 그래야 한 권처럼 보여."},{"who":"단비","text":"구조는 각자 대상에 맞게 고르고, 제목 다는 방식이랑 분량을 맞추자."},{"who":"서우","text":"머리말에는 왜 옛 물건을 모았는지 쓰고, 글 제목과 쪽수로 차례도 만들자."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_review_b#15','kor',5,1,'u4','','g5_1_kor_u4_review_b','unit_review','K5-1-u4-C40',2,'mc','auto','댓글을 받은 단비가 할 일로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u4-X40','K5-1-u4-X38']::text[],false,'{"seq":15,"concept":"K5-1-u4-C40","difficulty":2,"kind":"mc","stem":"댓글을 받은 단비가 할 일로 알맞은 것은 어느 것인가요?","options":[{"t":"읽을 사람의 처지에서 다시 읽고 고칠 곳을 고친다","correct":true},{"t":"댓글은 그냥 두고 그대로 낸다","mis":"K5-1-u4-X40"},{"t":"글을 모두 버리고 새 대상으로 쓴다","mis":"K5-1-u4-X40"},{"t":"느낌 문장을 더 넣는다","mis":"K5-1-u4-X38"}],"explanation":["다듬는 것도 쓰기예요.","고칠 곳만 고쳐요.","느낌은 중심이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_review_b#16','kor',5,1,'u4','','g5_1_kor_u4_review_b','unit_review','K5-1-u4-C11',2,'match','auto','구조와 그 구조를 가장 대표적으로 드러내는 말을 이으세요.','{}'::text[],false,'{"seq":16,"concept":"K5-1-u4-C11","difficulty":2,"kind":"match","stem":"구조와 그 구조를 가장 대표적으로 드러내는 말을 이으세요.","pairs":[{"l":"열거 구조","r":"첫째 · 둘째 · 셋째"},{"l":"순서 구조","r":"먼저 · 그 뒤 · 마지막으로"},{"l":"비교와 대조 구조","r":"모두 · 공통점 · 반면"}],"mis":"K5-1-u4-X11","explanation":["항목을 열어요.","차례를 밝혀요.","같은 점 · 다른 점을 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_review_b#17','kor',5,1,'u4','','g5_1_kor_u4_review_b','unit_review','K5-1-u4-C13',3,'error','auto','옛 물건 글의 구조에 대해 친구들이 한 말이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-1-u4-X13','K5-1-u4-X10']::text[],false,'{"seq":17,"concept":"K5-1-u4-C13","difficulty":3,"kind":"error","stem":"옛 물건 글의 구조에 대해 친구들이 한 말이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「짚신은 옛 신발이니까 비교와 대조 구조로만 써야 해.」","correct":true,"mis_target":"K5-1-u4-X13"},{"t":"「짚신 삼는 과정을 쓰면 순서 구조가 돼.」","mis":"K5-1-u4-X13"},{"t":"「짚신과 고무신을 견주면 비교와 대조 구조야.」","mis":"K5-1-u4-X10"}],"explanation":["알맞은 말이에요.","알맞은 말이에요.","대상이 구조를 정하지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_review_b#18','kor',5,1,'u4','','g5_1_kor_u4_review_b','unit_review','K5-1-u4-C12',3,'mc','auto','「어떤 글 ㉡」은 어떤 구조이고, 그렇게 볼 수 있는 까닭은 무엇인가요?',ARRAY['K5-1-u4-X12','K5-1-u4-X09','K5-1-u4-X10']::text[],false,'{"seq":18,"concept":"K5-1-u4-C12","difficulty":3,"kind":"mc","stem":"「어떤 글 ㉡」은 어떤 구조이고, 그렇게 볼 수 있는 까닭은 무엇인가요?","options":[{"t":"열거 구조 — 첫째와 둘째를 바꾸어도 글이 그대로다","correct":true},{"t":"순서 구조 — 첫째 · 둘째 · 셋째가 있기 때문이다","mis":"K5-1-u4-X12"},{"t":"순서 구조 — 바꾸면 글이 이상해지기 때문이다","mis":"K5-1-u4-X09"},{"t":"비교와 대조 구조 — 한지를 다른 종이와 견주었기 때문이다","mis":"K5-1-u4-X10"}],"explanation":["말만 보면 안 돼요.","바꾸어도 이상해지지 않아요.","특징을 나열했어요."],"asset":{"type":"passage","lines":["첫째, 한지는 질겨서 오래 간다.","둘째, 한지는 바람이 잘 통한다.","셋째, 한지를 바른 문은 빛을 부드럽게 들인다."],"title":"어떤 글 ㉡"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_review_b#19','kor',5,1,'u4','','g5_1_kor_u4_review_b','unit_review','K5-1-u4-C35',3,'mc','auto','서우가 「할머니께서 맷돌을 쓰시던 방법」을 알고 싶을 때 가장 알맞은 매체는 어느 것인가요?',ARRAY['K5-1-u4-X35']::text[],false,'{"seq":19,"concept":"K5-1-u4-C35","difficulty":3,"kind":"mc","stem":"서우가 「할머니께서 맷돌을 쓰시던 방법」을 알고 싶을 때 가장 알맞은 매체는 어느 것인가요?","options":[{"t":"할머니께 여쭙기","correct":true},{"t":"공공 기관 누리집","mis":"K5-1-u4-X35"},{"t":"맷돌을 파는 가게의 광고","mis":"K5-1-u4-X35"},{"t":"아무 책이나 한 권","mis":"K5-1-u4-X35"}],"explanation":["우리 집 이야기는 없어요.","광고는 알맞지 않아요.","그 답은 할머니께 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_review_b#20','kor',5,1,'u4','','g5_1_kor_u4_review_b','unit_review','K5-1-u4-C26',3,'mc','auto','무진이의 글을 한 문장으로 가장 잘 요약한 것은 어느 것인가요?',ARRAY['K5-1-u4-X26','K5-1-u4-X25','K5-1-u4-X38']::text[],false,'{"seq":20,"concept":"K5-1-u4-C26","difficulty":3,"kind":"mc","stem":"무진이의 글을 한 문장으로 가장 잘 요약한 것은 어느 것인가요?","options":[{"t":"부채는 바람을 일으키고, 햇볕을 가리고, 판소리에서 이야기를 살리고, 선물로도 쓰였다.","correct":true},{"t":"부채, 바람, 햇볕, 판소리, 단오.","mis":"K5-1-u4-X26"},{"t":"부채는 손으로 흔드는 물건이다.","mis":"K5-1-u4-X25"},{"t":"나는 부채가 좋다.","mis":"K5-1-u4-X38"}],"explanation":["낱말을 늘어놓았어요.","첫 문장만 옮겼어요.","네 쓰임을 이어 간추렸어요."],"asset":{"type":"passage","lines":["부채는 손으로 흔들어 바람을 일으키는 물건이다.","첫째, 더운 날 바람을 일으켜 땀을 식혀 준다.","둘째, 햇볕이 따가울 때 얼굴을 가리는 데 쓴다.","셋째, 판소리를 하는 소리꾼은 부채를 펴고 접으며 이야기를 살린다.","넷째, 옛날에는 단옷날 부채를 선물하며 여름을 잘 나기를 빌었다.","이처럼 부채는 바람을 일으키는 데에만 쓰인 것이 아니다."],"title":"무진이의 글 「부채의 여러 가지 쓰임」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_review_b#21','kor',5,1,'u4','','g5_1_kor_u4_review_b','unit_review','K5-1-u4-C48',3,'mc','auto','바르게 쓴 문장은 어느 것인가요?',ARRAY['K5-1-u4-X48','K5-1-u4-X49']::text[],false,'{"seq":21,"concept":"K5-1-u4-C48","difficulty":3,"kind":"mc","stem":"바르게 쓴 문장은 어느 것인가요?","options":[{"t":"눈 덮인 마당이 새하얗다.","correct":true},{"t":"흙탕물이 시누렇게 흘렀다.","mis":"K5-1-u4-X48"},{"t":"바닷물이 새퍼렇게 출렁였다.","mis":"K5-1-u4-X49"},{"t":"병아리 털이 새노랗다.","mis":"K5-1-u4-X48"}],"explanation":["ㄴ 앞은 싯-이에요.","ㅓ 앞은 시-예요.","ㅎ · ㅏ라 새하얗다가 맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_review_b#22','kor',5,1,'u4','','g5_1_kor_u4_review_b','unit_review','K5-1-u4-C28',3,'mc','auto','해담이가 지게에 대해 아는 것을 모두 쓰려 할 때 해 줄 말로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u4-X28','K5-1-u4-X33','K5-1-u4-X31']::text[],false,'{"seq":22,"concept":"K5-1-u4-C28","difficulty":3,"kind":"mc","stem":"해담이가 지게에 대해 아는 것을 모두 쓰려 할 때 해 줄 말로 알맞은 것은 어느 것인가요?","options":[{"t":"「읽을 동생들에게 필요한 것만 골라 써 봐.」","correct":true},{"t":"「아는 것을 다 쓰면 좋은 설명이 돼.」","mis":"K5-1-u4-X28"},{"t":"「떠오른 차례대로 쓰면 돼.」","mis":"K5-1-u4-X33"},{"t":"「어려운 말을 더 넣어 봐.」","mis":"K5-1-u4-X31"}],"explanation":["다 쓰는 글이 아니에요.","배열도 생각해요.","필요한 것을 골라요."],"asset":{"type":"passage","lines":["목적 — 옛 물건이 생활에서 어떻게 쓰였는지 알리기","읽을 사람 — 학교 축제에서 모음집을 볼 저학년 동생들","대상 — 지게(민속 마을 체험에서 직접 져 본 적이 있음)","쓸 내용 — 생김새 · 짐을 지는 방법 · 오늘날 볼 수 있는 곳","구조 — (　　　　)"],"title":"해담이의 글 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_review_b#23','kor',5,1,'u4','','g5_1_kor_u4_review_b','unit_review','K5-1-u4-C38',4,'essay','teacher','단비의 글 ㉱가 설명하는 글에 어울리지 않는 까닭을 쓰고, 비교와 대조 구조를 지키며 ㉱를 고쳐 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K5-1-u4-C38","difficulty":4,"kind":"essay","stem":"단비의 글 ㉱가 설명하는 글에 어울리지 않는 까닭을 쓰고, 비교와 대조 구조를 지키며 ㉱를 고쳐 쓰세요.","answer_guide":{"answer":"예: ㉱는 나막신 소리가 좋다는 글쓴이의 느낌만 담고 있어 대상의 특성을 알려 주지 못한다. 고쳐 쓰기 — 「걸을 때 나는 소리도 달랐다. 짚신은 소리가 거의 나지 않았지만, 반면 나막신은 바닥에 닿을 때마다 또각또각 소리가 났다.」","scoring_points":["어울리지 않는 까닭을 썼는가","두 신발을 견주어 고쳐 썼는가","느낌 대신 특성을 담았는가"]},"explanation":["누구의 느낌인가요?","두 신발을 나란히 놓아요.","특성을 알려 줘요."],"asset":{"type":"passage","lines":["㉮ 짚신과 나막신은 옛날 사람들이 신던 신발로, 둘 다 자연에서","　 얻은 재료로 만들었다는 공통점이 있다.","㉯ 짚신은 볏짚을 꼬아 엮어 만들어 가볍고 발이 편하다. 반면","　 나막신은 통나무를 파서 만들어 무겁지만 물이 스미지 않는다.","㉰ 신는 날도 달랐다. 짚신은 마른 날에 신었고, 나막신은 굽이","　 높아서 비가 오거나 땅이 질척한 날에 신었다.","㉱ 나는 나막신이 또각또각 울리는 소리가 세상에서 제일 좋다."],"title":"단비의 글 초안 「짚신과 나막신」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_review_b#24','kor',5,1,'u4','','g5_1_kor_u4_review_b','unit_review','K5-1-u4-C39',4,'essay','teacher','단비의 글 「짚신과 나막신」에 도움이 되는 댓글을 쓰세요. 좋았던 점과 보태면 좋을 점을 근거와 함께 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K5-1-u4-C39","difficulty":4,"kind":"essay","stem":"단비의 글 「짚신과 나막신」에 도움이 되는 댓글을 쓰세요. 좋았던 점과 보태면 좋을 점을 근거와 함께 쓰세요.","answer_guide":{"answer":"예: 「반면」이라는 말로 재료와 신는 날의 차이를 드러내서 두 신발이 한눈에 견주어졌어. 다만 ㉱는 네 느낌이라 설명하는 글에는 어울리지 않으니, 대신 걸을 때 나는 소리를 두 신발끼리 견주어 쓰면 더 좋겠어.","scoring_points":["좋았던 점을 근거와 함께 썼는가","보태면 좋을 점을 썼는가","예의 있게 썼는가"]},"explanation":["잘된 곳은 어디인가요?","고치면 좋을 곳은?","근거를 들어요."],"asset":{"type":"passage","lines":["㉮ 짚신과 나막신은 옛날 사람들이 신던 신발로, 둘 다 자연에서","　 얻은 재료로 만들었다는 공통점이 있다.","㉯ 짚신은 볏짚을 꼬아 엮어 만들어 가볍고 발이 편하다. 반면","　 나막신은 통나무를 파서 만들어 무겁지만 물이 스미지 않는다.","㉰ 신는 날도 달랐다. 짚신은 마른 날에 신었고, 나막신은 굽이","　 높아서 비가 오거나 땅이 질척한 날에 신었다.","㉱ 나는 나막신이 또각또각 울리는 소리가 세상에서 제일 좋다."],"title":"단비의 글 초안 「짚신과 나막신」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_review_b#25','kor',5,1,'u4','','g5_1_kor_u4_review_b','unit_review','K5-1-u4-C14',4,'essay','teacher','이 단원에서 배운 「글의 구조를 알고 요약하기」가 「대상을 설명하는 글 쓰기」에 어떻게 이어지는지 단비 · 무진 · 서우의 글을 예로 들어 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K5-1-u4-C14","difficulty":4,"kind":"essay","stem":"이 단원에서 배운 「글의 구조를 알고 요약하기」가 「대상을 설명하는 글 쓰기」에 어떻게 이어지는지 단비 · 무진 · 서우의 글을 예로 들어 쓰세요.","answer_guide":{"answer":"예: 글을 읽을 때 구조를 드러내는 말로 열거 · 순서 · 비교와 대조를 찾고 중심 내용을 간추리는 법을 익혔다. 이 구조는 글을 쓸 때 다시 쓰인다. 단비는 두 신발을 견주려고 비교와 대조를, 무진은 여러 쓰임을 소개하려고 열거를, 서우는 콩 가는 차례를 알리려고 순서를 골라 썼다. 읽으며 익힌 틀이 쓸 내용을 짜임새 있게 담는 틀이 된다.","scoring_points":["읽기에서 익힌 것을 썼는가","세 친구의 글을 예로 들었는가","읽기와 쓰기가 이어지는 까닭을 썼는가"]},"explanation":["읽을 때 무엇을 했나요?","세 친구는 어떤 틀을 골랐나요?","두 공부를 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_review_c#1','kor',5,1,'u4','','g5_1_kor_u4_review_c','unit_review','K5-1-u4-C48',1,'blank','auto','빈칸에 알맞은 말은 어느 것인가요? 「별 하나 없는 밤하늘이 (　　)까맣다.」',ARRAY['K5-1-u4-X48','K5-1-u4-X49']::text[],false,'{"seq":1,"concept":"K5-1-u4-C48","difficulty":1,"kind":"blank","stem":"빈칸에 알맞은 말은 어느 것인가요? 「별 하나 없는 밤하늘이 (　　)까맣다.」","options":[{"t":"새","correct":true},{"t":"샛","mis":"K5-1-u4-X48"},{"t":"시","mis":"K5-1-u4-X49"},{"t":"싯","mis":"K5-1-u4-X48"}],"explanation":["ㄴ · ㅁ 앞에 붙어요.","모음이 ㅏ예요.","첫소리 된소리 ㄲ, 모음 ㅏ라 「새」예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_review_c#2','kor',5,1,'u4','','g5_1_kor_u4_review_c','unit_review','K5-1-u4-C49',1,'blank','auto','빈칸에 알맞은 말은 어느 것인가요? 「부끄러워 얼굴이 (　　)뻘겋게 달아올랐다.」',ARRAY['K5-1-u4-X49','K5-1-u4-X48']::text[],false,'{"seq":2,"concept":"K5-1-u4-C49","difficulty":1,"kind":"blank","stem":"빈칸에 알맞은 말은 어느 것인가요? 「부끄러워 얼굴이 (　　)뻘겋게 달아올랐다.」","options":[{"t":"시","correct":true},{"t":"새","mis":"K5-1-u4-X49"},{"t":"싯","mis":"K5-1-u4-X48"},{"t":"샛","mis":"K5-1-u4-X48"}],"explanation":["모음이 ㅓ예요.","첫소리가 된소리예요.","첫소리 ㅃ, 모음 ㅓ라 「시」예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_review_c#3','kor',5,1,'u4','','g5_1_kor_u4_review_c','unit_review','K5-1-u4-C47',1,'mc','auto','「알맞은 낱말 고르기」의 ㉯에 알맞은 말은 어느 것인가요?',ARRAY['K5-1-u4-X48','K5-1-u4-X49','K5-1-u4-X47']::text[],false,'{"seq":3,"concept":"K5-1-u4-C47","difficulty":1,"kind":"mc","stem":"「알맞은 낱말 고르기」의 ㉯에 알맞은 말은 어느 것인가요?","options":[{"t":"샛노랗다","correct":true},{"t":"새노랗다","mis":"K5-1-u4-X48"},{"t":"싯노랗다","mis":"K5-1-u4-X49"},{"t":"시노랗다","mis":"K5-1-u4-X47"}],"explanation":["첫소리가 ㄴ이에요.","모음이 ㅗ예요.","ㄴ · ㅗ라 샛노랗다예요."],"asset":{"type":"passage","lines":["㉮ 별 하나 없는 밤하늘이 (새까맣다 / 시까맣다).","㉯ 갓 깬 병아리 털이 (샛노랗다 / 새노랗다).","㉰ 큰비가 온 뒤 흙탕물이 (싯누렇게 / 시누렇게) 흘렀다.","㉱ 눈 덮인 마당이 (새하얗다 / 샛하얗다)."],"title":"알맞은 낱말 고르기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_review_c#4','kor',5,1,'u4','','g5_1_kor_u4_review_c','unit_review','K5-1-u4-C10',1,'mc','auto','단비의 글에서 두 신발의 공통점으로 든 것은 어느 것인가요?',ARRAY['K5-1-u4-X19']::text[],false,'{"seq":4,"concept":"K5-1-u4-C10","difficulty":1,"kind":"mc","stem":"단비의 글에서 두 신발의 공통점으로 든 것은 어느 것인가요?","options":[{"t":"자연에서 얻은 재료로 만들었다","correct":true},{"t":"굽이 높다","mis":"K5-1-u4-X19"},{"t":"볏짚으로 만들었다","mis":"K5-1-u4-X19"},{"t":"비 오는 날에 신었다","mis":"K5-1-u4-X19"}],"explanation":["나막신만의 것이에요.","짚신만의 것이에요.","㉮에 공통점이 있어요."],"asset":{"type":"passage","lines":["㉮ 짚신과 나막신은 옛날 사람들이 신던 신발로, 둘 다 자연에서","　 얻은 재료로 만들었다는 공통점이 있다.","㉯ 짚신은 볏짚을 꼬아 엮어 만들어 가볍고 발이 편하다. 반면","　 나막신은 통나무를 파서 만들어 무겁지만 물이 스미지 않는다.","㉰ 신는 날도 달랐다. 짚신은 마른 날에 신었고, 나막신은 굽이","　 높아서 비가 오거나 땅이 질척한 날에 신었다.","㉱ 나는 나막신이 또각또각 울리는 소리가 세상에서 제일 좋다."],"title":"단비의 글 초안 「짚신과 나막신」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_review_c#5','kor',5,1,'u4','','g5_1_kor_u4_review_c','unit_review','K5-1-u4-C17',1,'mc','auto','무진이의 글을 열거 틀에 정리할 때 항목 칸에 들어갈 것은 어느 것인가요?',ARRAY['K5-1-u4-X17','K5-1-u4-X38']::text[],false,'{"seq":5,"concept":"K5-1-u4-C17","difficulty":1,"kind":"mc","stem":"무진이의 글을 열거 틀에 정리할 때 항목 칸에 들어갈 것은 어느 것인가요?","options":[{"t":"판소리에서 이야기를 살린다","correct":true},{"t":"부채는 손으로 흔들어 바람을 일으키는 물건이다","mis":"K5-1-u4-X17"},{"t":"부채는 바람을 일으키는 데에만 쓰인 것이 아니다","mis":"K5-1-u4-X17"},{"t":"나는 접는 부채가 더 좋다","mis":"K5-1-u4-X38"}],"explanation":["대상을 소개하는 첫 문장이에요.","앞을 묶는 끝 문장이에요.","셋째 쓰임이에요."],"asset":{"type":"passage","lines":["부채는 손으로 흔들어 바람을 일으키는 물건이다.","첫째, 더운 날 바람을 일으켜 땀을 식혀 준다.","둘째, 햇볕이 따가울 때 얼굴을 가리는 데 쓴다.","셋째, 판소리를 하는 소리꾼은 부채를 펴고 접으며 이야기를 살린다.","넷째, 옛날에는 단옷날 부채를 선물하며 여름을 잘 나기를 빌었다.","이처럼 부채는 바람을 일으키는 데에만 쓰인 것이 아니다."],"title":"무진이의 글 「부채의 여러 가지 쓰임」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_review_c#6','kor',5,1,'u4','','g5_1_kor_u4_review_c','unit_review','K5-1-u4-C11',1,'mc','auto','서우의 글에서 구조를 짐작하게 하는 말은 어느 것인가요?',ARRAY['K5-1-u4-X11','K5-1-u4-X24']::text[],false,'{"seq":6,"concept":"K5-1-u4-C11","difficulty":1,"kind":"mc","stem":"서우의 글에서 구조를 짐작하게 하는 말은 어느 것인가요?","options":[{"t":"먼저 · 다음으로 · 그 뒤 · 마지막으로","correct":true},{"t":"반면 · 다르게","mis":"K5-1-u4-X11"},{"t":"모두 · 공통점","mis":"K5-1-u4-X11"},{"t":"이처럼","mis":"K5-1-u4-X24"}],"explanation":["글에 없는 말이에요.","글에 없는 말이에요.","차례를 밝히는 말이 있어요."],"asset":{"type":"passage","lines":["맷돌은 둥근 돌 두 짝을 포개어 곡식을 가는 도구이다.","먼저, 콩을 물에 담가 하룻밤 불린다.","다음으로, 위짝의 구멍에 불린 콩과 물을 조금씩 넣는다.","그 뒤, 손잡이를 잡고 위짝을 한 방향으로 천천히 돌린다.","마지막으로, 두 짝 사이로 흘러나온 콩물을 그릇에 받는다."],"title":"서우의 글 「맷돌로 콩 가는 차례」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_review_c#7','kor',5,1,'u4','','g5_1_kor_u4_review_c','unit_review','K5-1-u4-C15',1,'mc','auto','강솔이의 글 ㉯에서 첫째 방법의 중심 문장은 어느 것인가요?',ARRAY['K5-1-u4-X16','K5-1-u4-X25']::text[],false,'{"seq":7,"concept":"K5-1-u4-C15","difficulty":1,"kind":"mc","stem":"강솔이의 글 ㉯에서 첫째 방법의 중심 문장은 어느 것인가요?","options":[{"t":"깨끗한 손으로 책장을 넘긴다","correct":true},{"t":"손에 묻은 기름과 먼지는 책장을 누렇게 만든다","mis":"K5-1-u4-X16"},{"t":"학교 도서관 책은 여러 사람이 돌려 가며 읽는다","mis":"K5-1-u4-X25"},{"t":"오늘 빌린 책부터 실천해 보자","mis":"K5-1-u4-X25"}],"explanation":["까닭을 대는 뒷받침 문장이에요.","처음 부분이에요.","첫째 방법을 대표해요."],"asset":{"type":"passage","lines":["㉮ 학교 도서관 책은 여러 사람이 돌려 가며 읽는다. 책을 오래","　 읽으려면 어떻게 해야 할지 알아보자.","㉯ 첫째, 깨끗한 손으로 책장을 넘긴다. 손에 묻은 기름과 먼지는","　 책장을 누렇게 만든다. 둘째, 읽던 곳은 책장을 접지 말고","　 책갈피를 끼운다. 셋째, 다 읽은 책은 제때 돌려준다.","㉰ 이처럼 책을 아끼는 작은 습관은 다음에 읽을 친구를 위한","　 배려이다. 오늘 빌린 책부터 실천해 보자."],"title":"강솔이의 학급 신문 글 「도서관 책을 오래 읽는 방법」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_review_c#8','kor',5,1,'u4','','g5_1_kor_u4_review_c','unit_review','K5-1-u4-C41',1,'mc','auto','해담네 반 모음집의 큰 주제 「옛 물건 이야기」가 알맞은 까닭은 무엇인가요?',ARRAY['K5-1-u4-X41','K5-1-u4-X43']::text[],false,'{"seq":8,"concept":"K5-1-u4-C41","difficulty":1,"kind":"mc","stem":"해담네 반 모음집의 큰 주제 「옛 물건 이야기」가 알맞은 까닭은 무엇인가요?","options":[{"t":"여러 친구가 저마다 다른 옛 물건을 골라 나누어 쓸 수 있다","correct":true},{"t":"한 사람만 아는 이야기라서","mis":"K5-1-u4-X41"},{"t":"모두 같은 물건을 써야 해서","mis":"K5-1-u4-X43"},{"t":"자료를 찾을 수 없어서","mis":"K5-1-u4-X41"}],"explanation":["여럿이 쓸 수 있어요.","물건은 저마다 골라요.","자료를 찾을 수 있어요."],"asset":{"type":"speech","turns":[{"who":"해담","text":"우리 반 모음집의 큰 주제는 「옛 물건 이야기」로 정했어. 이제 무엇을 함께 정할까?"},{"who":"무진","text":"모두 똑같이 비교와 대조 구조로 쓰자. 그래야 한 권처럼 보여."},{"who":"단비","text":"구조는 각자 대상에 맞게 고르고, 제목 다는 방식이랑 분량을 맞추자."},{"who":"서우","text":"머리말에는 왜 옛 물건을 모았는지 쓰고, 글 제목과 쪽수로 차례도 만들자."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_review_c#9','kor',5,1,'u4','','g5_1_kor_u4_review_c','unit_review','K5-1-u4-C39',2,'mc','auto','단비의 글에 남긴 댓글 가운데 가장 도움이 되는 것은 누구의 것인가요?',ARRAY['K5-1-u4-X39']::text[],false,'{"seq":9,"concept":"K5-1-u4-C39","difficulty":2,"kind":"mc","stem":"단비의 글에 남긴 댓글 가운데 가장 도움이 되는 것은 누구의 것인가요?","options":[{"t":"나","correct":true},{"t":"가","mis":"K5-1-u4-X39"},{"t":"다","mis":"K5-1-u4-X39"},{"t":"라","mis":"K5-1-u4-X39"}],"explanation":["칭찬만 있어요.","자기 글과 견주었어요.","좋았던 점과 보탤 점을 함께 말했어요."],"asset":{"type":"speech","turns":[{"who":"가","text":"잘 썼네."},{"who":"나","text":"비교와 대조 구조라 두 신발이 한눈에 견주어졌어. 볏짚이 무엇인지 짧게 풀어 주면 동생들도 읽기 쉽겠어."},{"who":"다","text":"내 글이 더 재미있는 것 같아."},{"who":"라","text":"㉱는 빼. 그냥 별로야."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_review_c#10','kor',5,1,'u4','','g5_1_kor_u4_review_c','unit_review','K5-1-u4-C20',2,'mc','auto','무진이가 부채의 쓰임을 틀에 정리하는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u4-X20','K5-1-u4-X21','K5-1-u4-X09']::text[],false,'{"seq":10,"concept":"K5-1-u4-C20","difficulty":2,"kind":"mc","stem":"무진이가 부채의 쓰임을 틀에 정리하는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"구조의 특징이 드러나면 네 칸 표든 부채 모양 그림이든 괜찮다","correct":true},{"t":"반드시 선생님이 보여 준 표 모양이어야 한다","mis":"K5-1-u4-X20"},{"t":"문장을 그대로 옮긴 칸이어야 한다","mis":"K5-1-u4-X21"},{"t":"차례가 있는 계단 모양이어야 한다","mis":"K5-1-u4-X09"}],"explanation":["틀은 예시일 뿐이에요.","중심 낱말로 적어요.","열거는 나란히 놓여요."],"asset":{"type":"passage","lines":["부채는 손으로 흔들어 바람을 일으키는 물건이다.","첫째, 더운 날 바람을 일으켜 땀을 식혀 준다.","둘째, 햇볕이 따가울 때 얼굴을 가리는 데 쓴다.","셋째, 판소리를 하는 소리꾼은 부채를 펴고 접으며 이야기를 살린다.","넷째, 옛날에는 단옷날 부채를 선물하며 여름을 잘 나기를 빌었다.","이처럼 부채는 바람을 일으키는 데에만 쓰인 것이 아니다."],"title":"무진이의 글 「부채의 여러 가지 쓰임」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_review_c#11','kor',5,1,'u4','','g5_1_kor_u4_review_c','unit_review','K5-1-u4-C13',2,'mc','auto','「맷돌」을 대상으로 비교와 대조 구조의 글을 쓴다면 무엇을 말하는 글이 알맞을까요?',ARRAY['K5-1-u4-X13','K5-1-u4-X38']::text[],false,'{"seq":11,"concept":"K5-1-u4-C13","difficulty":2,"kind":"mc","stem":"「맷돌」을 대상으로 비교와 대조 구조의 글을 쓴다면 무엇을 말하는 글이 알맞을까요?","options":[{"t":"맷돌과 절구의 같은 점과 다른 점","correct":true},{"t":"맷돌로 콩 가는 차례","mis":"K5-1-u4-X13"},{"t":"맷돌의 여러 가지 쓰임","mis":"K5-1-u4-X13"},{"t":"맷돌을 처음 본 내 느낌","mis":"K5-1-u4-X38"}],"explanation":["그것은 순서예요.","그것은 열거예요.","두 도구를 견줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_review_c#12','kor',5,1,'u4','','g5_1_kor_u4_review_c','unit_review','K5-1-u4-C24',2,'mc','auto','강솔이의 글 ㉰의 「이처럼」이 하는 일은 어느 것인가요?',ARRAY['K5-1-u4-X24','K5-1-u4-X11','K5-1-u4-X09']::text[],false,'{"seq":12,"concept":"K5-1-u4-C24","difficulty":2,"kind":"mc","stem":"강솔이의 글 ㉰의 「이처럼」이 하는 일은 어느 것인가요?","options":[{"t":"앞의 세 방법을 묶어 끝을 연다","correct":true},{"t":"넷째 방법을 연다","mis":"K5-1-u4-X24"},{"t":"두 대상의 차이를 말한다","mis":"K5-1-u4-X11"},{"t":"다음 단계를 연다","mis":"K5-1-u4-X09"}],"explanation":["새 항목이 아니에요.","견주는 말이 아니에요.","앞을 묶어 맺어요."],"asset":{"type":"passage","lines":["㉮ 학교 도서관 책은 여러 사람이 돌려 가며 읽는다. 책을 오래","　 읽으려면 어떻게 해야 할지 알아보자.","㉯ 첫째, 깨끗한 손으로 책장을 넘긴다. 손에 묻은 기름과 먼지는","　 책장을 누렇게 만든다. 둘째, 읽던 곳은 책장을 접지 말고","　 책갈피를 끼운다. 셋째, 다 읽은 책은 제때 돌려준다.","㉰ 이처럼 책을 아끼는 작은 습관은 다음에 읽을 친구를 위한","　 배려이다. 오늘 빌린 책부터 실천해 보자."],"title":"강솔이의 학급 신문 글 「도서관 책을 오래 읽는 방법」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_review_c#13','kor',5,1,'u4','','g5_1_kor_u4_review_c','unit_review','K5-1-u4-C29',2,'mc','auto','해담이의 계획을 정한 차례로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u4-X29']::text[],false,'{"seq":13,"concept":"K5-1-u4-C29","difficulty":2,"kind":"mc","stem":"해담이의 계획을 정한 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"목적 → 읽을 사람 → 대상 → 구조","correct":true},{"t":"구조 → 대상 → 목적 → 읽을 사람","mis":"K5-1-u4-X29"},{"t":"대상 → 구조 → 읽을 사람 → 목적","mis":"K5-1-u4-X29"},{"t":"읽을 사람만 정하면 된다","mis":"K5-1-u4-X29"}],"explanation":["구조는 맨 나중이에요.","목적부터 정해요.","네 가지를 차례대로 정해요."],"asset":{"type":"passage","lines":["목적 — 옛 물건이 생활에서 어떻게 쓰였는지 알리기","읽을 사람 — 학교 축제에서 모음집을 볼 저학년 동생들","대상 — 지게(민속 마을 체험에서 직접 져 본 적이 있음)","쓸 내용 — 생김새 · 짐을 지는 방법 · 오늘날 볼 수 있는 곳","구조 — (　　　　)"],"title":"해담이의 글 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_review_c#14','kor',5,1,'u4','','g5_1_kor_u4_review_c','unit_review','K5-1-u4-C42',2,'mc','auto','큰 주제를 정한 해담네 반이 다음에 할 일은 어느 것인가요?',ARRAY['K5-1-u4-X42']::text[],false,'{"seq":14,"concept":"K5-1-u4-C42","difficulty":2,"kind":"mc","stem":"큰 주제를 정한 해담네 반이 다음에 할 일은 어느 것인가요?","options":[{"t":"각자 설명할 옛 물건을 고른다","correct":true},{"t":"바로 모음집으로 묶는다","mis":"K5-1-u4-X42"},{"t":"표지부터 꾸민다","mis":"K5-1-u4-X42"},{"t":"주제를 다시 정한다","mis":"K5-1-u4-X42"}],"explanation":["글을 쓰기 전이에요.","묶는 일은 나중이에요.","주제 다음은 대상이에요."],"asset":{"type":"speech","turns":[{"who":"해담","text":"우리 반 모음집의 큰 주제는 「옛 물건 이야기」로 정했어. 이제 무엇을 함께 정할까?"},{"who":"무진","text":"모두 똑같이 비교와 대조 구조로 쓰자. 그래야 한 권처럼 보여."},{"who":"단비","text":"구조는 각자 대상에 맞게 고르고, 제목 다는 방식이랑 분량을 맞추자."},{"who":"서우","text":"머리말에는 왜 옛 물건을 모았는지 쓰고, 글 제목과 쪽수로 차례도 만들자."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_review_c#15','kor',5,1,'u4','','g5_1_kor_u4_review_c','unit_review','K5-1-u4-C40',2,'mc','auto','쓰기 과정을 점검한다는 것은 무엇을 돌아보는 것인가요?',ARRAY['K5-1-u4-X40']::text[],false,'{"seq":15,"concept":"K5-1-u4-C40","difficulty":2,"kind":"mc","stem":"쓰기 과정을 점검한다는 것은 무엇을 돌아보는 것인가요?","options":[{"t":"자료를 모으고 구조를 정해 끝까지 쓰고 다듬는 과정 전체","correct":true},{"t":"다 쓴 글의 길이만","mis":"K5-1-u4-X40"},{"t":"글자를 쓴 빠르기만","mis":"K5-1-u4-X40"},{"t":"맞춤법만","mis":"K5-1-u4-X40"}],"explanation":["결과만 보는 것이 아니에요.","빠르기는 기준이 아니에요.","과정 전체를 돌아봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_review_c#16','kor',5,1,'u4','','g5_1_kor_u4_review_c','unit_review','K5-1-u4-C14',2,'mc','auto','구조를 찾는 것이 요약의 첫걸음인 까닭은 무엇인가요?',ARRAY['K5-1-u4-X14','K5-1-u4-X05']::text[],false,'{"seq":16,"concept":"K5-1-u4-C14","difficulty":2,"kind":"mc","stem":"구조를 찾는 것이 요약의 첫걸음인 까닭은 무엇인가요?","options":[{"t":"구조가 보이면 어디가 중심 내용인지 드러나기 때문이다","correct":true},{"t":"구조를 찾으면 요약이 필요 없어서","mis":"K5-1-u4-X14"},{"t":"구조와 요약은 관계없어서","mis":"K5-1-u4-X14"},{"t":"구조를 찾으면 글이 길어져서","mis":"K5-1-u4-X05"}],"explanation":["요약은 해야 해요.","서로 이어져 있어요.","중심 내용을 찾게 해 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_review_c#17','kor',5,1,'u4','','g5_1_kor_u4_review_c','unit_review','K5-1-u4-C32',3,'mc','auto','무진이가 「셋째」 문단 안에서 쥘부채와 둥근 부채를 견주어 쓴다면 이 글의 구조는 어떻게 볼 수 있나요?',ARRAY['K5-1-u4-X32','K5-1-u4-X09']::text[],false,'{"seq":17,"concept":"K5-1-u4-C32","difficulty":3,"kind":"mc","stem":"무진이가 「셋째」 문단 안에서 쥘부채와 둥근 부채를 견주어 쓴다면 이 글의 구조는 어떻게 볼 수 있나요?","options":[{"t":"글 전체는 열거이고 그 항목 안에 비교와 대조가 함께 쓰인 것이다","correct":true},{"t":"글 전체가 비교와 대조 구조로 바뀐다","mis":"K5-1-u4-X32"},{"t":"한 글에 두 구조가 들어가면 틀린 글이다","mis":"K5-1-u4-X32"},{"t":"순서 구조가 된다","mis":"K5-1-u4-X09"}],"explanation":["큰 틀은 그대로예요.","한 글에 함께 쓰일 수 있어요.","큰 틀 안에 작은 틀이에요."],"asset":{"type":"passage","lines":["부채는 손으로 흔들어 바람을 일으키는 물건이다.","첫째, 더운 날 바람을 일으켜 땀을 식혀 준다.","둘째, 햇볕이 따가울 때 얼굴을 가리는 데 쓴다.","셋째, 판소리를 하는 소리꾼은 부채를 펴고 접으며 이야기를 살린다.","넷째, 옛날에는 단옷날 부채를 선물하며 여름을 잘 나기를 빌었다.","이처럼 부채는 바람을 일으키는 데에만 쓰인 것이 아니다."],"title":"무진이의 글 「부채의 여러 가지 쓰임」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_review_c#18','kor',5,1,'u4','','g5_1_kor_u4_review_c','unit_review','K5-1-u4-C12',3,'ox','auto','「첫째, 둘째」가 쓰인 글이 열거인지 순서인지는 그 말만 보고 정할 수 있어요.',ARRAY['K5-1-u4-X12']::text[],false,'{"seq":18,"concept":"K5-1-u4-C12","difficulty":3,"kind":"ox","stem":"「첫째, 둘째」가 쓰인 글이 열거인지 순서인지는 그 말만 보고 정할 수 있어요.","answer":"X","reason_options":[{"t":"그 말은 짐작을 돕는 단서일 뿐이라 내용의 순서를 바꾸어 보아야 하기 때문에","correct":true},{"t":"첫째 · 둘째는 열거 구조에만 쓰는 말이기 때문에","mis":"K5-1-u4-X12"}],"mis":"K5-1-u4-X12","explanation":["단서일 뿐이에요.","순서 구조에도 쓰여요.","바꾸어 보아 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_review_c#19','kor',5,1,'u4','','g5_1_kor_u4_review_c','unit_review','K5-1-u4-C34',3,'mc','auto','해담이가 지게 자료를 조사하며 꼭 함께 적어 둘 것은 어느 것인가요?',ARRAY['K5-1-u4-X34','K5-1-u4-X36']::text[],false,'{"seq":19,"concept":"K5-1-u4-C34","difficulty":3,"kind":"mc","stem":"해담이가 지게 자료를 조사하며 꼭 함께 적어 둘 것은 어느 것인가요?","options":[{"t":"찾은 곳과 찾은 날짜","correct":true},{"t":"자료의 글자 수","mis":"K5-1-u4-X34"},{"t":"찾을 때 든 기분","mis":"K5-1-u4-X34"},{"t":"자료의 바탕색","mis":"K5-1-u4-X36"}],"explanation":["필요 없어요.","필요 없어요.","출처와 날짜를 남겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_review_c#20','kor',5,1,'u4','','g5_1_kor_u4_review_c','unit_review','K5-1-u4-C27',3,'mc','auto','사회 교과서에서 여러 지역의 특산물을 하나씩 소개한 부분을 요약하는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u4-X27','K5-1-u4-X13','K5-1-u4-X21']::text[],false,'{"seq":20,"concept":"K5-1-u4-C27","difficulty":3,"kind":"mc","stem":"사회 교과서에서 여러 지역의 특산물을 하나씩 소개한 부분을 요약하는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"열거 구조로 보고 항목별로 정리한다","correct":true},{"t":"요약은 국어 글에만 쓰므로 하지 않는다","mis":"K5-1-u4-X27"},{"t":"순서 구조로 차례를 정한다","mis":"K5-1-u4-X13"},{"t":"통째로 옮겨 쓴다","mis":"K5-1-u4-X21"}],"explanation":["다른 과목 글도 요약해요.","차례가 있는 내용이 아니에요.","항목별로 정리해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_review_c#21','kor',5,1,'u4','','g5_1_kor_u4_review_c','unit_review','K5-1-u4-C49',3,'mc','auto','「하얗다」 앞에 새-가 붙는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u4-X48','K5-1-u4-X49','K5-1-u4-X47']::text[],false,'{"seq":21,"concept":"K5-1-u4-C49","difficulty":3,"kind":"mc","stem":"「하얗다」 앞에 새-가 붙는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"첫소리가 ㅎ이고 모음이 ㅏ이기 때문이다","correct":true},{"t":"첫소리가 ㄴ이기 때문이다","mis":"K5-1-u4-X48"},{"t":"모음이 ㅓ이기 때문이다","mis":"K5-1-u4-X49"},{"t":"아무것이나 붙여도 되기 때문이다","mis":"K5-1-u4-X47"}],"explanation":["첫소리는 ㅎ이에요.","모음은 ㅏ예요.","두 규칙을 겹쳐 보아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_review_c#22','kor',5,1,'u4','','g5_1_kor_u4_review_c','unit_review','K5-1-u4-C33',3,'mc','auto','단비가 처음 떠올린 차례가 「나막신 소리 소감 → 재료 → 공통점」이었다면 어떻게 고치는 것이 알맞나요?',ARRAY['K5-1-u4-X33','K5-1-u4-X38','K5-1-u4-X19']::text[],false,'{"seq":22,"concept":"K5-1-u4-C33","difficulty":3,"kind":"mc","stem":"단비가 처음 떠올린 차례가 「나막신 소리 소감 → 재료 → 공통점」이었다면 어떻게 고치는 것이 알맞나요?","options":[{"t":"공통점 → 재료와 만드는 방법의 차이 → 신는 날의 차이","correct":true},{"t":"떠오른 차례 그대로 둔다","mis":"K5-1-u4-X33"},{"t":"소감 → 소감 → 재료","mis":"K5-1-u4-X38"},{"t":"재료만 남기고 다 뺀다","mis":"K5-1-u4-X19"}],"explanation":["흥미와 짜임새를 생각해요.","느낌은 중심이 아니에요.","견줄 항목이 있어야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_review_c#23','kor',5,1,'u4','','g5_1_kor_u4_review_c','unit_review','K5-1-u4-C26',4,'essay','teacher','강솔이의 글을 처음 · 가운데 · 끝을 살려 세 문장 안팎으로 요약하세요.','{}'::text[],false,'{"seq":23,"concept":"K5-1-u4-C26","difficulty":4,"kind":"essay","stem":"강솔이의 글을 처음 · 가운데 · 끝을 살려 세 문장 안팎으로 요약하세요.","answer_guide":{"answer":"예: 학교 도서관 책은 여러 사람이 돌려 가며 읽는다. 책을 오래 읽으려면 깨끗한 손으로 책장을 넘기고, 읽던 곳에 책갈피를 끼우며, 다 읽은 책은 제때 돌려주어야 한다. 이런 작은 습관은 다음에 읽을 친구를 위한 배려이다.","scoring_points":["처음 · 가운데 · 끝을 갖추었는가","세 방법을 빠짐없이 담았는가","뒷받침하는 까닭은 줄였는가"]},"explanation":["처음은 무엇을 밝혔나요?","가운데는 세 방법이에요.","끝은 무엇을 권했나요?"],"asset":{"type":"passage","lines":["㉮ 학교 도서관 책은 여러 사람이 돌려 가며 읽는다. 책을 오래","　 읽으려면 어떻게 해야 할지 알아보자.","㉯ 첫째, 깨끗한 손으로 책장을 넘긴다. 손에 묻은 기름과 먼지는","　 책장을 누렇게 만든다. 둘째, 읽던 곳은 책장을 접지 말고","　 책갈피를 끼운다. 셋째, 다 읽은 책은 제때 돌려준다.","㉰ 이처럼 책을 아끼는 작은 습관은 다음에 읽을 친구를 위한","　 배려이다. 오늘 빌린 책부터 실천해 보자."],"title":"강솔이의 학급 신문 글 「도서관 책을 오래 읽는 방법」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_review_c#24','kor',5,1,'u4','','g5_1_kor_u4_review_c','unit_review','K5-1-u4-C44',4,'essay','teacher','해담네 반 모음집 회의에 이어, 「옛 물건 이야기」를 한 권으로 묶으려면 무엇을 함께 정하고 무엇을 넣어야 할지 쓰세요. 무진이의 말에 대한 생각도 함께 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K5-1-u4-C44","difficulty":4,"kind":"essay","stem":"해담네 반 모음집 회의에 이어, 「옛 물건 이야기」를 한 권으로 묶으려면 무엇을 함께 정하고 무엇을 넣어야 할지 쓰세요. 무진이의 말에 대한 생각도 함께 쓰세요.","answer_guide":{"answer":"예: 제목 다는 방식 · 글의 분량 · 사진을 넣을지를 함께 정하고, 표지 · 머리말 · 차례 · 출처를 넣는다. 무진이처럼 모두 같은 구조로 쓸 필요는 없다. 짚신과 나막신은 비교와 대조, 부채의 쓰임은 열거, 맷돌로 콩 가는 차례는 순서처럼 대상에 맞는 구조로 써도 겉모습을 맞추면 한 권이 된다.","scoring_points":["함께 정할 겉모습을 썼는가","넣을 것 네 가지를 썼는가","무진이의 말에 대한 생각을 까닭과 함께 썼는가"]},"explanation":["겉모습을 떠올려요.","표지 · 머리말 · 차례 · 출처예요.","구조까지 같아야 할까요?"],"asset":{"type":"speech","turns":[{"who":"해담","text":"우리 반 모음집의 큰 주제는 「옛 물건 이야기」로 정했어. 이제 무엇을 함께 정할까?"},{"who":"무진","text":"모두 똑같이 비교와 대조 구조로 쓰자. 그래야 한 권처럼 보여."},{"who":"단비","text":"구조는 각자 대상에 맞게 고르고, 제목 다는 방식이랑 분량을 맞추자."},{"who":"서우","text":"머리말에는 왜 옛 물건을 모았는지 쓰고, 글 제목과 쪽수로 차례도 만들자."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_review_c#25','kor',5,1,'u4','','g5_1_kor_u4_review_c','unit_review','K5-1-u4-C40',4,'essay','teacher','내가 설명하는 글을 한 편 쓴다고 할 때, 목적을 정하는 일부터 다 쓴 뒤 다듬는 일까지 쓰기 과정을 차례대로 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K5-1-u4-C40","difficulty":4,"kind":"essay","stem":"내가 설명하는 글을 한 편 쓴다고 할 때, 목적을 정하는 일부터 다 쓴 뒤 다듬는 일까지 쓰기 과정을 차례대로 쓰세요.","answer_guide":{"answer":"예: 먼저 글을 쓰는 목적과 읽을 사람을 정한다. 다음으로 잘 알고 흥미롭고 자료가 있는 대상을 고르고, 말하려는 내용에 맞는 구조를 정한다. 그 뒤 조사 계획을 세워 자료를 모으고 목적 · 최신 · 신뢰의 기준으로 점검한 다음, 정한 구조를 지키며 글을 쓴다. 마지막으로 친구들과 댓글을 나누고 읽을 사람의 처지에서 다시 읽어 더하고 빼며 다듬는다.","scoring_points":["목적 · 읽을 사람 · 대상 · 구조를 정하는 일을 썼는가","자료를 모으고 점검하며 쓰는 일을 썼는가","댓글과 다듬기까지 썼는가"]},"explanation":["무엇부터 정하나요?","자료는 어떻게 하나요?","다 쓴 뒤에는?"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_review_d#1','kor',5,1,'u4','','g5_1_kor_u4_review_d','unit_review','K5-1-u4-C48',1,'mc','auto','뒤에 오는 말의 첫소리가 ㄴ이나 ㅁ일 때 쓰는 것끼리 묶은 것은 어느 것인가요?',ARRAY['K5-1-u4-X48','K5-1-u4-X49']::text[],false,'{"seq":1,"concept":"K5-1-u4-C48","difficulty":1,"kind":"mc","stem":"뒤에 오는 말의 첫소리가 ㄴ이나 ㅁ일 때 쓰는 것끼리 묶은 것은 어느 것인가요?","options":[{"t":"샛- · 싯-","correct":true},{"t":"새- · 시-","mis":"K5-1-u4-X48"},{"t":"새- · 샛-","mis":"K5-1-u4-X49"},{"t":"시- · 싯-","mis":"K5-1-u4-X49"}],"explanation":["된소리 · 거센소리 · ㅎ 앞이에요.","모음으로 가른 묶음이에요.","ㄴ · ㅁ 앞에는 사이시옷이 붙은 샛- · 싯-이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_review_d#2','kor',5,1,'u4','','g5_1_kor_u4_review_d','unit_review','K5-1-u4-C49',1,'mc','auto','뒤에 오는 말의 모음이 ㅓ나 ㅜ일 때 쓰는 것끼리 묶은 것은 어느 것인가요?',ARRAY['K5-1-u4-X49','K5-1-u4-X48']::text[],false,'{"seq":2,"concept":"K5-1-u4-C49","difficulty":1,"kind":"mc","stem":"뒤에 오는 말의 모음이 ㅓ나 ㅜ일 때 쓰는 것끼리 묶은 것은 어느 것인가요?","options":[{"t":"시- · 싯-","correct":true},{"t":"새- · 샛-","mis":"K5-1-u4-X49"},{"t":"새- · 시-","mis":"K5-1-u4-X48"},{"t":"샛- · 싯-","mis":"K5-1-u4-X48"}],"explanation":["ㅏ · ㅗ 앞이에요.","첫소리로 가른 묶음이에요.","ㅓ · ㅜ 앞에는 시- · 싯-이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_review_d#3','kor',5,1,'u4','','g5_1_kor_u4_review_d','unit_review','K5-1-u4-C47',1,'ox','auto','새- · 샛- · 시- · 싯- 가운데 아무것이나 골라 붙여도 돼요.',ARRAY['K5-1-u4-X47']::text[],false,'{"seq":3,"concept":"K5-1-u4-C47","difficulty":1,"kind":"ox","stem":"새- · 샛- · 시- · 싯- 가운데 아무것이나 골라 붙여도 돼요.","answer":"X","reason_options":[{"t":"뒤에 오는 말의 첫소리와 모음에 따라 쓸 것이 정해져 있기 때문에","correct":true},{"t":"네 말은 뜻이 같으니 무엇을 써도 되기 때문에","mis":"K5-1-u4-X47"}],"mis":"K5-1-u4-X47","explanation":["뜻은 같아도 쓰임이 달라요.","규칙이 있어요.","첫소리와 모음을 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_review_d#4','kor',5,1,'u4','','g5_1_kor_u4_review_d','unit_review','K5-1-u4-C38',1,'mc','auto','단비의 글에서 설명하는 글에 어울리지 않는 단락은 어느 것인가요?',ARRAY['K5-1-u4-X38']::text[],false,'{"seq":4,"concept":"K5-1-u4-C38","difficulty":1,"kind":"mc","stem":"단비의 글에서 설명하는 글에 어울리지 않는 단락은 어느 것인가요?","options":[{"t":"㉱","correct":true},{"t":"㉮","mis":"K5-1-u4-X38"},{"t":"㉯","mis":"K5-1-u4-X38"},{"t":"㉰","mis":"K5-1-u4-X38"}],"explanation":["공통점을 설명해요.","차이점을 설명해요.","글쓴이의 느낌만 담겼어요."],"asset":{"type":"passage","lines":["㉮ 짚신과 나막신은 옛날 사람들이 신던 신발로, 둘 다 자연에서","　 얻은 재료로 만들었다는 공통점이 있다.","㉯ 짚신은 볏짚을 꼬아 엮어 만들어 가볍고 발이 편하다. 반면","　 나막신은 통나무를 파서 만들어 무겁지만 물이 스미지 않는다.","㉰ 신는 날도 달랐다. 짚신은 마른 날에 신었고, 나막신은 굽이","　 높아서 비가 오거나 땅이 질척한 날에 신었다.","㉱ 나는 나막신이 또각또각 울리는 소리가 세상에서 제일 좋다."],"title":"단비의 글 초안 「짚신과 나막신」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_review_d#5','kor',5,1,'u4','','g5_1_kor_u4_review_d','unit_review','K5-1-u4-C25',1,'mc','auto','무진이의 글 마지막 문장 「이처럼 부채는 …」이 하는 일은 어느 것인가요?',ARRAY['K5-1-u4-X25','K5-1-u4-X08']::text[],false,'{"seq":5,"concept":"K5-1-u4-C25","difficulty":1,"kind":"mc","stem":"무진이의 글 마지막 문장 「이처럼 부채는 …」이 하는 일은 어느 것인가요?","options":[{"t":"끝 — 앞의 쓰임을 묶어 정리한다","correct":true},{"t":"처음 — 대상을 소개한다","mis":"K5-1-u4-X25"},{"t":"가운데 — 다섯째 쓰임을 늘어놓는다","mis":"K5-1-u4-X25"},{"t":"순서 구조의 마지막 단계이다","mis":"K5-1-u4-X08"}],"explanation":["처음은 첫 문장이에요.","새 쓰임이 아니에요.","앞을 묶어 맺어요."],"asset":{"type":"passage","lines":["부채는 손으로 흔들어 바람을 일으키는 물건이다.","첫째, 더운 날 바람을 일으켜 땀을 식혀 준다.","둘째, 햇볕이 따가울 때 얼굴을 가리는 데 쓴다.","셋째, 판소리를 하는 소리꾼은 부채를 펴고 접으며 이야기를 살린다.","넷째, 옛날에는 단옷날 부채를 선물하며 여름을 잘 나기를 빌었다.","이처럼 부채는 바람을 일으키는 데에만 쓰인 것이 아니다."],"title":"무진이의 글 「부채의 여러 가지 쓰임」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_review_d#6','kor',5,1,'u4','','g5_1_kor_u4_review_d','unit_review','K5-1-u4-C18',1,'match','auto','서우의 글에서 단계와 하는 일을 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K5-1-u4-C18","difficulty":1,"kind":"match","stem":"서우의 글에서 단계와 하는 일을 이으세요.","pairs":[{"l":"먼저","r":"콩 불리기"},{"l":"다음으로","r":"콩과 물 넣기"},{"l":"그 뒤","r":"위짝 돌리기"},{"l":"마지막으로","r":"콩물 받기"}],"mis":"K5-1-u4-X18","explanation":["불려야 갈 수 있어요.","넣어야 돌릴 수 있어요.","차례대로 이어요."],"asset":{"type":"passage","lines":["맷돌은 둥근 돌 두 짝을 포개어 곡식을 가는 도구이다.","먼저, 콩을 물에 담가 하룻밤 불린다.","다음으로, 위짝의 구멍에 불린 콩과 물을 조금씩 넣는다.","그 뒤, 손잡이를 잡고 위짝을 한 방향으로 천천히 돌린다.","마지막으로, 두 짝 사이로 흘러나온 콩물을 그릇에 받는다."],"title":"서우의 글 「맷돌로 콩 가는 차례」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_review_d#7','kor',5,1,'u4','','g5_1_kor_u4_review_d','unit_review','K5-1-u4-C5',1,'mc','auto','강솔이의 글을 요약하는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u4-X05','K5-1-u4-X26']::text[],false,'{"seq":7,"concept":"K5-1-u4-C5","difficulty":1,"kind":"mc","stem":"강솔이의 글을 요약하는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"처음 · 가운데 · 끝의 중심 내용을 간추린다","correct":true},{"t":"글 전체를 그대로 옮긴다","mis":"K5-1-u4-X05"},{"t":"첫 문장만 적는다","mis":"K5-1-u4-X05"},{"t":"낱말만 늘어놓는다","mis":"K5-1-u4-X26"}],"explanation":["줄어들지 않아요.","중심 내용이 빠져요.","중심 내용을 간추려요."],"asset":{"type":"passage","lines":["㉮ 학교 도서관 책은 여러 사람이 돌려 가며 읽는다. 책을 오래","　 읽으려면 어떻게 해야 할지 알아보자.","㉯ 첫째, 깨끗한 손으로 책장을 넘긴다. 손에 묻은 기름과 먼지는","　 책장을 누렇게 만든다. 둘째, 읽던 곳은 책장을 접지 말고","　 책갈피를 끼운다. 셋째, 다 읽은 책은 제때 돌려준다.","㉰ 이처럼 책을 아끼는 작은 습관은 다음에 읽을 친구를 위한","　 배려이다. 오늘 빌린 책부터 실천해 보자."],"title":"강솔이의 학급 신문 글 「도서관 책을 오래 읽는 방법」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_review_d#8','kor',5,1,'u4','','g5_1_kor_u4_review_d','unit_review','K5-1-u4-C45',1,'mc','auto','서우가 말한 머리말에 들어갈 내용으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u4-X45']::text[],false,'{"seq":8,"concept":"K5-1-u4-C45","difficulty":1,"kind":"mc","stem":"서우가 말한 머리말에 들어갈 내용으로 알맞은 것은 어느 것인가요?","options":[{"t":"왜 옛 물건을 모았는지","correct":true},{"t":"글 제목과 쪽수","mis":"K5-1-u4-X45"},{"t":"각 글에서 활용한 자료","mis":"K5-1-u4-X45"},{"t":"친구들의 시험 점수","mis":"K5-1-u4-X45"}],"explanation":["그것은 차례예요.","그것은 출처예요.","모은 까닭을 밝혀요."],"asset":{"type":"speech","turns":[{"who":"해담","text":"우리 반 모음집의 큰 주제는 「옛 물건 이야기」로 정했어. 이제 무엇을 함께 정할까?"},{"who":"무진","text":"모두 똑같이 비교와 대조 구조로 쓰자. 그래야 한 권처럼 보여."},{"who":"단비","text":"구조는 각자 대상에 맞게 고르고, 제목 다는 방식이랑 분량을 맞추자."},{"who":"서우","text":"머리말에는 왜 옛 물건을 모았는지 쓰고, 글 제목과 쪽수로 차례도 만들자."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_review_d#9','kor',5,1,'u4','','g5_1_kor_u4_review_d','unit_review','K5-1-u4-C37',2,'mc','auto','단비가 「보관하는 방법」 문단을 더한다면 어떻게 쓰는 것이 알맞나요?',ARRAY['K5-1-u4-X37','K5-1-u4-X19','K5-1-u4-X38']::text[],false,'{"seq":9,"concept":"K5-1-u4-C37","difficulty":2,"kind":"mc","stem":"단비가 「보관하는 방법」 문단을 더한다면 어떻게 쓰는 것이 알맞나요?","options":[{"t":"짚신과 나막신을 어떻게 보관했는지 나란히 견주어 쓴다","correct":true},{"t":"짚신 만드는 차례만 먼저 · 다음으로로 쓴다","mis":"K5-1-u4-X37"},{"t":"나막신 이야기만 쓴다","mis":"K5-1-u4-X19"},{"t":"보관하며 든 느낌을 쓴다","mis":"K5-1-u4-X38"}],"explanation":["도중에 구조를 바꾸었어요.","한쪽만 쓰면 견줄 수 없어요.","정한 구조를 끝까지 지켜요."],"asset":{"type":"passage","lines":["㉮ 짚신과 나막신은 옛날 사람들이 신던 신발로, 둘 다 자연에서","　 얻은 재료로 만들었다는 공통점이 있다.","㉯ 짚신은 볏짚을 꼬아 엮어 만들어 가볍고 발이 편하다. 반면","　 나막신은 통나무를 파서 만들어 무겁지만 물이 스미지 않는다.","㉰ 신는 날도 달랐다. 짚신은 마른 날에 신었고, 나막신은 굽이","　 높아서 비가 오거나 땅이 질척한 날에 신었다.","㉱ 나는 나막신이 또각또각 울리는 소리가 세상에서 제일 좋다."],"title":"단비의 글 초안 「짚신과 나막신」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_review_d#10','kor',5,1,'u4','','g5_1_kor_u4_review_d','unit_review','K5-1-u4-C17',2,'ox','auto','무진이의 열거 틀에 「부채는 바람을 일으키는 데에만 쓰인 것이 아니다」를 한 항목으로 넣어야 해요.',ARRAY['K5-1-u4-X17']::text[],false,'{"seq":10,"concept":"K5-1-u4-C17","difficulty":2,"kind":"ox","stem":"무진이의 열거 틀에 「부채는 바람을 일으키는 데에만 쓰인 것이 아니다」를 한 항목으로 넣어야 해요.","answer":"X","reason_options":[{"t":"그 문장은 쓰임 하나가 아니라 앞의 쓰임을 묶어 정리하는 끝 문장이기 때문에","correct":true},{"t":"글에 있는 문장은 모두 틀의 칸에 넣어야 하기 때문에","mis":"K5-1-u4-X17"}],"mis":"K5-1-u4-X17","explanation":["항목은 쓰임 하나씩이에요.","묶는 문장은 끝이에요.","항목의 특징만 담아요."],"asset":{"type":"passage","lines":["부채는 손으로 흔들어 바람을 일으키는 물건이다.","첫째, 더운 날 바람을 일으켜 땀을 식혀 준다.","둘째, 햇볕이 따가울 때 얼굴을 가리는 데 쓴다.","셋째, 판소리를 하는 소리꾼은 부채를 펴고 접으며 이야기를 살린다.","넷째, 옛날에는 단옷날 부채를 선물하며 여름을 잘 나기를 빌었다.","이처럼 부채는 바람을 일으키는 데에만 쓰인 것이 아니다."],"title":"무진이의 글 「부채의 여러 가지 쓰임」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_review_d#11','kor',5,1,'u4','','g5_1_kor_u4_review_d','unit_review','K5-1-u4-C31',2,'mc','auto','서우의 글을 저학년 동생들이 읽는다면 어떻게 고치는 것이 좋을까요?',ARRAY['K5-1-u4-X31']::text[],false,'{"seq":11,"concept":"K5-1-u4-C31","difficulty":2,"kind":"mc","stem":"서우의 글을 저학년 동생들이 읽는다면 어떻게 고치는 것이 좋을까요?","options":[{"t":"「위짝」 같은 말을 쉽게 풀고 그림을 곁들인다","correct":true},{"t":"어려운 말을 더 넣는다","mis":"K5-1-u4-X31"},{"t":"그림을 모두 뺀다","mis":"K5-1-u4-X31"},{"t":"어른이 읽는 글과 똑같이 둔다","mis":"K5-1-u4-X31"}],"explanation":["더 어려워져요.","그림이 도움이 돼요.","읽을 사람을 생각해요."],"asset":{"type":"passage","lines":["맷돌은 둥근 돌 두 짝을 포개어 곡식을 가는 도구이다.","먼저, 콩을 물에 담가 하룻밤 불린다.","다음으로, 위짝의 구멍에 불린 콩과 물을 조금씩 넣는다.","그 뒤, 손잡이를 잡고 위짝을 한 방향으로 천천히 돌린다.","마지막으로, 두 짝 사이로 흘러나온 콩물을 그릇에 받는다."],"title":"서우의 글 「맷돌로 콩 가는 차례」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_review_d#12','kor',5,1,'u4','','g5_1_kor_u4_review_d','unit_review','K5-1-u4-C22',2,'mc','auto','강솔이의 글을 요약하는 차례로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u4-X22']::text[],false,'{"seq":12,"concept":"K5-1-u4-C22","difficulty":2,"kind":"mc","stem":"강솔이의 글을 요약하는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"구조 찾기 → 중심 문장 찾기 → 처음 · 가운데 · 끝 정리","correct":true},{"t":"요약문 먼저 쓰기 → 글 읽기 → 구조 찾기","mis":"K5-1-u4-X22"},{"t":"처음 · 가운데 · 끝 정리 → 중심 문장 찾기 → 구조 찾기","mis":"K5-1-u4-X22"},{"t":"중심 문장 찾기 → 요약문 쓰기 → 구조 찾기","mis":"K5-1-u4-X22"}],"explanation":["읽기 전에 쓸 수 없어요.","차례가 거꾸로예요.","구조를 먼저 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_review_d#13','kor',5,1,'u4','','g5_1_kor_u4_review_d','unit_review','K5-1-u4-C13',2,'mc','auto','해담이가 지게와 손수레의 같은 점과 다른 점을 쓰려고 마음을 바꾼다면 알맞은 구조는 어느 것인가요?',ARRAY['K5-1-u4-X13']::text[],false,'{"seq":13,"concept":"K5-1-u4-C13","difficulty":2,"kind":"mc","stem":"해담이가 지게와 손수레의 같은 점과 다른 점을 쓰려고 마음을 바꾼다면 알맞은 구조는 어느 것인가요?","options":[{"t":"비교와 대조 구조","correct":true},{"t":"열거 구조","mis":"K5-1-u4-X13"},{"t":"순서 구조","mis":"K5-1-u4-X13"},{"t":"지게는 열거 구조로만 쓸 수 있다","mis":"K5-1-u4-X13"}],"explanation":["견주는 글이에요.","차례가 아니에요.","말하려는 것이 바뀌면 구조도 바뀌어요."],"asset":{"type":"passage","lines":["목적 — 옛 물건이 생활에서 어떻게 쓰였는지 알리기","읽을 사람 — 학교 축제에서 모음집을 볼 저학년 동생들","대상 — 지게(민속 마을 체험에서 직접 져 본 적이 있음)","쓸 내용 — 생김새 · 짐을 지는 방법 · 오늘날 볼 수 있는 곳","구조 — (　　　　)"],"title":"해담이의 글 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_review_d#14','kor',5,1,'u4','','g5_1_kor_u4_review_d','unit_review','K5-1-u4-C45',2,'mc','auto','해담네 반 모음집에 넣을 것을 바르게 묶은 것은 어느 것인가요?',ARRAY['K5-1-u4-X45','K5-1-u4-X41']::text[],false,'{"seq":14,"concept":"K5-1-u4-C45","difficulty":2,"kind":"mc","stem":"해담네 반 모음집에 넣을 것을 바르게 묶은 것은 어느 것인가요?","options":[{"t":"표지 · 머리말 · 차례 · 출처","correct":true},{"t":"표지 · 시험 점수 · 차례 · 출처","mis":"K5-1-u4-X45"},{"t":"머리말 · 사물함 비밀번호 · 차례","mis":"K5-1-u4-X41"},{"t":"표지 하나만","mis":"K5-1-u4-X45"}],"explanation":["점수는 관계없어요.","비밀번호는 넣지 않아요.","네 가지를 갖춰요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_review_d#15','kor',5,1,'u4','','g5_1_kor_u4_review_d','unit_review','K5-1-u4-C39',2,'error','auto','단비의 글에 남긴 댓글을 두고 한 말이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-1-u4-X39']::text[],false,'{"seq":15,"concept":"K5-1-u4-C39","difficulty":2,"kind":"error","stem":"단비의 글에 남긴 댓글을 두고 한 말이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「「다」처럼 자기 글이 더 낫다고 말해 주는 게 도움이 돼.」","correct":true,"mis_target":"K5-1-u4-X39"},{"t":"「두 신발이 한눈에 견주어졌다는 말은 좋았던 점이야.」","mis":"K5-1-u4-X39"},{"t":"「볏짚 뜻을 풀어 달라는 말은 보탤 점이야.」","mis":"K5-1-u4-X39"}],"explanation":["알맞은 말이에요.","알맞은 말이에요.","견주어 깎아내리는 말은 도움이 안 돼요."],"asset":{"type":"speech","turns":[{"who":"가","text":"잘 썼네."},{"who":"나","text":"비교와 대조 구조라 두 신발이 한눈에 견주어졌어. 볏짚이 무엇인지 짧게 풀어 주면 동생들도 읽기 쉽겠어."},{"who":"다","text":"내 글이 더 재미있는 것 같아."},{"who":"라","text":"㉱는 빼. 그냥 별로야."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_review_d#16','kor',5,1,'u4','','g5_1_kor_u4_review_d','unit_review','K5-1-u4-C1',2,'mc','auto','「짚신과 나막신」 같은 글을 쓰는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u4-X01','K5-1-u4-X04']::text[],false,'{"seq":16,"concept":"K5-1-u4-C1","difficulty":2,"kind":"mc","stem":"「짚신과 나막신」 같은 글을 쓰는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"읽는 사람이 잘 모르는 대상을 알려 주려고","correct":true},{"t":"미안한 마음을 전하려고","mis":"K5-1-u4-X01"},{"t":"겪은 일을 일기로 남기려고","mis":"K5-1-u4-X01"},{"t":"글자 수를 늘리려고","mis":"K5-1-u4-X04"}],"explanation":["마음을 전하는 글이 아니에요.","일기가 아니에요.","대상을 설명하는 글이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_review_d#17','kor',5,1,'u4','','g5_1_kor_u4_review_d','unit_review','K5-1-u4-C13',3,'mc','auto','해담이가 「지게로 짐을 지는 차례」를 쓴다면 알맞은 구조와 그 까닭은 어느 것인가요?',ARRAY['K5-1-u4-X13','K5-1-u4-X08']::text[],false,'{"seq":17,"concept":"K5-1-u4-C13","difficulty":3,"kind":"mc","stem":"해담이가 「지게로 짐을 지는 차례」를 쓴다면 알맞은 구조와 그 까닭은 어느 것인가요?","options":[{"t":"순서 구조 — 차례를 바꾸면 짐 지는 방법이 달라지기 때문이다","correct":true},{"t":"열거 구조 — 지게 글은 열거로 정해져 있기 때문이다","mis":"K5-1-u4-X13"},{"t":"비교와 대조 구조 — 지게가 나오기 때문이다","mis":"K5-1-u4-X13"},{"t":"열거 구조 — 차례를 바꾸어도 똑같기 때문이다","mis":"K5-1-u4-X08"}],"explanation":["대상이 정하지 않아요.","견주는 내용이 아니에요.","차례가 곧 방법이에요."],"asset":{"type":"passage","lines":["목적 — 옛 물건이 생활에서 어떻게 쓰였는지 알리기","읽을 사람 — 학교 축제에서 모음집을 볼 저학년 동생들","대상 — 지게(민속 마을 체험에서 직접 져 본 적이 있음)","쓸 내용 — 생김새 · 짐을 지는 방법 · 오늘날 볼 수 있는 곳","구조 — (　　　　)"],"title":"해담이의 글 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_review_d#18','kor',5,1,'u4','','g5_1_kor_u4_review_d','unit_review','K5-1-u4-C14',3,'mc','auto','「먼저」로 시작하는 글을 읽을 때 짐작하며 읽는 모습으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u4-X11','K5-1-u4-X06','K5-1-u4-X14']::text[],false,'{"seq":18,"concept":"K5-1-u4-C14","difficulty":3,"kind":"mc","stem":"「먼저」로 시작하는 글을 읽을 때 짐작하며 읽는 모습으로 알맞은 것은 어느 것인가요?","options":[{"t":"「다음으로」 · 「그 뒤」처럼 이어질 단계를 짐작하며 읽는다","correct":true},{"t":"다른 대상과 견주는 내용이 나올 것이라 짐작한다","mis":"K5-1-u4-X11"},{"t":"드러내는 말이 있으니 내용은 안 읽어도 된다","mis":"K5-1-u4-X06"},{"t":"글이 곧 끝날 것이라 짐작한다","mis":"K5-1-u4-X14"}],"explanation":["「먼저」는 차례를 여는 말이에요.","내용은 읽어야 해요.","이어질 단계를 짐작해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_review_d#19','kor',5,1,'u4','','g5_1_kor_u4_review_d','unit_review','K5-1-u4-C36',3,'error','auto','자료 점검에 대해 친구들이 한 말이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-1-u4-X36']::text[],false,'{"seq":19,"concept":"K5-1-u4-C36","difficulty":3,"kind":"error","stem":"자료 점검에 대해 친구들이 한 말이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「분량이 길수록 좋은 자료야.」","correct":true,"mis_target":"K5-1-u4-X36"},{"t":"「찾는 목적에 맞는지 봐야 해.」","mis":"K5-1-u4-X36"},{"t":"「믿을 수 있는 곳에서 낸 것인지 봐야 해.」","mis":"K5-1-u4-X36"}],"explanation":["알맞은 말이에요.","알맞은 말이에요.","길이는 기준이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_review_d#20','kor',5,1,'u4','','g5_1_kor_u4_review_d','unit_review','K5-1-u4-C16',3,'mc','auto','강솔이의 글 ㉯의 「손에 묻은 기름과 먼지는 책장을 누렇게 만든다.」는 어떤 문장인가요?',ARRAY['K5-1-u4-X16','K5-1-u4-X25']::text[],false,'{"seq":20,"concept":"K5-1-u4-C16","difficulty":3,"kind":"mc","stem":"강솔이의 글 ㉯의 「손에 묻은 기름과 먼지는 책장을 누렇게 만든다.」는 어떤 문장인가요?","options":[{"t":"첫째 방법을 풀어 주는 뒷받침 문장","correct":true},{"t":"가운데 부분의 중심 문장","mis":"K5-1-u4-X16"},{"t":"글 전체의 중심 문장","mis":"K5-1-u4-X16"},{"t":"끝 부분의 문장","mis":"K5-1-u4-X25"}],"explanation":["까닭을 대는 문장이에요.","글 전체를 대표하지 않아요.","첫째 방법의 까닭을 풀어 줘요."],"asset":{"type":"passage","lines":["㉮ 학교 도서관 책은 여러 사람이 돌려 가며 읽는다. 책을 오래","　 읽으려면 어떻게 해야 할지 알아보자.","㉯ 첫째, 깨끗한 손으로 책장을 넘긴다. 손에 묻은 기름과 먼지는","　 책장을 누렇게 만든다. 둘째, 읽던 곳은 책장을 접지 말고","　 책갈피를 끼운다. 셋째, 다 읽은 책은 제때 돌려준다.","㉰ 이처럼 책을 아끼는 작은 습관은 다음에 읽을 친구를 위한","　 배려이다. 오늘 빌린 책부터 실천해 보자."],"title":"강솔이의 학급 신문 글 「도서관 책을 오래 읽는 방법」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_review_d#21','kor',5,1,'u4','','g5_1_kor_u4_review_d','unit_review','K5-1-u4-C49',3,'mc','auto','「싯멀겋다」에 싯-이 붙은 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u4-X48','K5-1-u4-X49']::text[],false,'{"seq":21,"concept":"K5-1-u4-C49","difficulty":3,"kind":"mc","stem":"「싯멀겋다」에 싯-이 붙은 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"첫소리가 ㅁ이고 모음이 ㅓ이기 때문이다","correct":true},{"t":"첫소리가 된소리이고 모음이 ㅏ이기 때문이다","mis":"K5-1-u4-X48"},{"t":"첫소리가 ㅎ이기 때문이다","mis":"K5-1-u4-X48"},{"t":"모음이 ㅗ이기 때문이다","mis":"K5-1-u4-X49"}],"explanation":["첫소리는 ㅁ이에요.","첫소리는 ㅁ이에요.","ㅁ은 싯-, ㅓ도 싯-이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_review_d#22','kor',5,1,'u4','','g5_1_kor_u4_review_d','unit_review','K5-1-u4-C2',3,'mc','auto','다른 나라 친구가 「짚신이 뭐야?」라고 물었을 때 단비의 대답으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u4-X02','K5-1-u4-X01','K5-1-u4-X38']::text[],false,'{"seq":22,"concept":"K5-1-u4-C2","difficulty":3,"kind":"mc","stem":"다른 나라 친구가 「짚신이 뭐야?」라고 물었을 때 단비의 대답으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「짚신은 볏짚을 엮어 만든 옛 신발이야. 가볍고, 마른 날에 신었어.」","correct":true},{"t":"「짚신은 짚이고, 신이고, 옛날이고, 가볍고, 또…….」","mis":"K5-1-u4-X02"},{"t":"「몰라도 돼.」","mis":"K5-1-u4-X01"},{"t":"「나는 짚신이 좋아.」","mis":"K5-1-u4-X38"}],"explanation":["떠오르는 대로 늘어놓았어요.","알려 주지 않았어요.","무엇인지부터 차례로 알려 줬어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_review_d#23','kor',5,1,'u4','','g5_1_kor_u4_review_d','unit_review','K5-1-u4-C18',4,'essay','teacher','서우의 글에서 단계의 차례를 바꾸면 안 되는 까닭을 쓰고, 「먼저 · 다음으로」 대신 「첫째 · 둘째」로 고쳐 써도 순서 구조인 까닭을 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K5-1-u4-C18","difficulty":4,"kind":"essay","stem":"서우의 글에서 단계의 차례를 바꾸면 안 되는 까닭을 쓰고, 「먼저 · 다음으로」 대신 「첫째 · 둘째」로 고쳐 써도 순서 구조인 까닭을 쓰세요.","answer_guide":{"answer":"예: 콩을 불리지 않고 맷돌에 넣거나 콩을 넣기 전에 위짝을 돌리면 콩물을 얻을 수 없으므로 단계의 차례가 곧 방법이다. 「첫째 · 둘째」로 바꾸어도 첫째와 둘째의 내용을 서로 바꾸면 방법이 어긋나므로 여전히 순서 구조이다.","scoring_points":["차례를 바꾸면 안 되는 까닭을 썼는가","첫째 · 둘째로 바꾸어도 순서인 까닭을 썼는가","내용을 바꾸어 보는 방법을 썼는가"]},"explanation":["바꾸면 무슨 일이 생기나요?","말이 바뀌어도 내용은?","바꾸어 보아 확인해요."],"asset":{"type":"passage","lines":["맷돌은 둥근 돌 두 짝을 포개어 곡식을 가는 도구이다.","먼저, 콩을 물에 담가 하룻밤 불린다.","다음으로, 위짝의 구멍에 불린 콩과 물을 조금씩 넣는다.","그 뒤, 손잡이를 잡고 위짝을 한 방향으로 천천히 돌린다.","마지막으로, 두 짝 사이로 흘러나온 콩물을 그릇에 받는다."],"title":"서우의 글 「맷돌로 콩 가는 차례」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_review_d#24','kor',5,1,'u4','','g5_1_kor_u4_review_d','unit_review','K5-1-u4-C49',4,'essay','teacher','새- · 샛- · 시- · 싯-을 고르는 두 규칙을 쓰고, 「알맞은 낱말 고르기」의 ㉰와 ㉱에서 알맞은 말을 골라 까닭을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K5-1-u4-C49","difficulty":4,"kind":"essay","stem":"새- · 샛- · 시- · 싯-을 고르는 두 규칙을 쓰고, 「알맞은 낱말 고르기」의 ㉰와 ㉱에서 알맞은 말을 골라 까닭을 쓰세요.","answer_guide":{"answer":"예: 첫째 규칙 — 뒤에 오는 말의 첫소리가 된소리 · 거센소리 · ㅎ이면 새- · 시-, ㄴ · ㅁ이면 샛- · 싯-을 쓴다. 둘째 규칙 — 모음이 ㅏ · ㅗ이면 새- · 샛-, ㅓ · ㅜ이면 시- · 싯-을 쓴다. ㉰는 「싯누렇게」이다. 누렇다의 첫소리가 ㄴ이고 모음이 ㅜ이기 때문이다. ㉱는 「새하얗다」이다. 하얗다의 첫소리가 ㅎ이고 모음이 ㅏ이기 때문이다.","scoring_points":["첫소리 규칙을 썼는가","모음 규칙을 썼는가","㉰ · ㉱를 바르게 고르고 까닭을 썼는가"]},"explanation":["첫소리를 봐요.","모음을 봐요.","두 규칙을 겹쳐요."],"asset":{"type":"passage","lines":["㉮ 별 하나 없는 밤하늘이 (새까맣다 / 시까맣다).","㉯ 갓 깬 병아리 털이 (샛노랗다 / 새노랗다).","㉰ 큰비가 온 뒤 흙탕물이 (싯누렇게 / 시누렇게) 흘렀다.","㉱ 눈 덮인 마당이 (새하얗다 / 샛하얗다)."],"title":"알맞은 낱말 고르기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u4_review_d#25','kor',5,1,'u4','','g5_1_kor_u4_review_d','unit_review','K5-1-u4-C46',4,'essay','teacher','해담네 반 모음집에 실린 「짚신과 나막신」 · 「부채의 여러 가지 쓰임」 · 「맷돌로 콩 가는 차례」의 구조를 각각 찾고, 같은 주제인데 구조가 다른 것에 대한 생각을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K5-1-u4-C46","difficulty":4,"kind":"essay","stem":"해담네 반 모음집에 실린 「짚신과 나막신」 · 「부채의 여러 가지 쓰임」 · 「맷돌로 콩 가는 차례」의 구조를 각각 찾고, 같은 주제인데 구조가 다른 것에 대한 생각을 쓰세요.","answer_guide":{"answer":"예: 「짚신과 나막신」은 비교와 대조, 「부채의 여러 가지 쓰임」은 열거, 「맷돌로 콩 가는 차례」는 순서 구조이다. 모두 옛 물건 이야기이지만 말하려는 내용이 달라 구조도 다르다. 그래서 읽는 느낌도 저마다 달라 모음집이 더 풍성해진다.","scoring_points":["세 글의 구조를 바르게 찾았는가","구조가 다른 까닭을 썼는가","읽는 느낌이나 모음집에 주는 점을 썼는가"]},"explanation":["세 글의 드러내는 말을 봐요.","말하려는 내용이 같나요?","읽는 느낌은 어떤가요?"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
